window.SQE_TERMS["ls"] = [
  {t:"sra-regulatory-role", w:"Legal Services Act 2007 (LSA)", d:"Statute creating the regulatory framework, regulatory objectives and reserved legal activities."},
  {t:"sra-regulatory-role", w:"Legal Services Board (LSB)", d:"Oversight regulator that supervises approved regulators such as the Law Society."},
  {t:"sra-regulatory-role", w:"Legal Ombudsman (LeO)", d:"Independent body resolving consumer complaints about service by legal providers."},
  {t:"sra-regulatory-role", w:"Regulatory objectives", d:"LSA aims including the rule of law, access to justice and consumers' interests."},
  {t:"sra-regulatory-role", w:"Reserved legal activities", d:"Six activities only authorised persons may do, e.g. conducting litigation and conveyancing."},
  {t:"sra-regulatory-role", w:"Professional principles", d:"LSA duties: independence, integrity, proper standards, client interests, court duty and confidentiality."},
  {t:"pii-other-providers", w:"Minimum Terms and Conditions (MTC)", d:"Compulsory terms every SRA firm's indemnity insurance policy must include."},
  {t:"pii-other-providers", w:"Minimum cover £2m / £3m", d:"Each claim cover: £2m generally, £3m for incorporated firms and LLPs."},
  {t:"pii-other-providers", w:"Six years' run-off cover", d:"Cover for claims after a firm closes without a successor practice."},
  {t:"pii-other-providers", w:"Compensation Fund", d:"Discretionary last-resort fund for clients losing money through dishonesty or failure to account."},
  {t:"pii-other-providers", w:"Licensed body (ABS)", d:"Firm with non-lawyer managers or owners, licensed under Part 5 LSA 2007."},
  {t:"pii-other-providers", w:"COLP and COFA", d:"Compliance officers for legal practice and for finance and administration."},
  {t:"equality-act", w:"Protected characteristics", d:"Nine characteristics, including age, disability, race, religion, sex and sexual orientation."},
  {t:"equality-act", w:"Direct discrimination (s.13)", d:"Treating someone less favourably because of a protected characteristic."},
  {t:"equality-act", w:"Indirect discrimination (s.19)", d:"A provision, criterion or practice that puts a protected group at particular disadvantage."},
  {t:"equality-act", w:"Harassment (s.26)", d:"Unwanted conduct related to a protected characteristic creating an offensive environment."},
  {t:"equality-act", w:"Victimisation (s.27)", d:"Subjecting someone to detriment because they did a protected act."},
  {t:"equality-act", w:"Reasonable adjustments", d:"Duty to take reasonable steps to avoid disabled people being substantially disadvantaged."},
  {t:"aml-framework-cdd", w:"Placement, layering, integration", d:"The three stages of laundering criminal money into apparently legitimate funds."},
  {t:"aml-framework-cdd", w:"Money Laundering Regulations 2017", d:"Rules requiring regulated firms to carry out due diligence and risk assessments."},
  {t:"aml-framework-cdd", w:"Customer due diligence (CDD)", d:"Identifying and verifying the client and any beneficial owner."},
  {t:"aml-framework-cdd", w:"Beneficial owner", d:"An individual who ultimately owns or controls over 25% of a client entity."},
  {t:"aml-framework-cdd", w:"Enhanced due diligence (EDD)", d:"Extra checks for high-risk situations, such as politically exposed persons."},
  {t:"aml-framework-cdd", w:"Nominated officer (MLRO)", d:"Person in the firm who receives internal suspicion reports and decides on SARs."},
  {t:"poca-offences-reporting", w:"s.327 Concealing", d:"Offence to conceal, disguise, convert, transfer or remove criminal property."},
  {t:"poca-offences-reporting", w:"s.328 Arrangements", d:"Offence to enter an arrangement facilitating another's acquisition or control of criminal property."},
  {t:"poca-offences-reporting", w:"Bowman v Fels", d:"Ordinary conduct of litigation is not an arrangement under s.328."},
  {t:"poca-offences-reporting", w:"DAML", d:"Defence against money laundering: consent from the NCA after an authorised disclosure."},
  {t:"poca-offences-reporting", w:"7 working day notice period", d:"NCA period to respond to a DAML; silence means consent."},
  {t:"poca-offences-reporting", w:"s.333A tipping off", d:"Offence to disclose that a SAR has been made, likely prejudicing an investigation."},
  {t:"poca-offences-reporting", w:"s.330 failure to disclose", d:"Regulated-sector offence of not reporting knowledge, suspicion or reasonable grounds."},
  {t:"financial-services", w:"s.19 FSMA general prohibition", d:"Only authorised or exempt persons may carry on regulated activities."},
  {t:"financial-services", w:"Regulated Activities Order 2001 (RAO)", d:"Lists the specified investments and activities that FSMA regulates."},
  {t:"financial-services", w:"Specified investment", d:"Investment such as shares, bonds, units or insurance covered by the RAO."},
  {t:"financial-services", w:"Part 20 exemption", d:"Lets law firms carry on incidental regulated activities without FCA authorisation."},
  {t:"financial-services", w:"Necessary part of other services", d:"Exclusion where the activity is a necessary part of providing legal services."},
  {t:"financial-services", w:"Introducing", d:"Exclusion for introducing a client to an authorised person for independent advice."},
  {t:"funding-private-cfa-dba", w:"Conditional fee agreement (CFA)", d:"No win, no fee agreement, possibly with a success fee if the case wins."},
  {t:"funding-private-cfa-dba", w:"Success fee", d:"Percentage uplift on base costs, capped at 100%, payable by the client."},
  {t:"funding-private-cfa-dba", w:"PI success fee cap", d:"In personal injury, success fee is capped at 25% of PSLA and past losses."},
  {t:"funding-private-cfa-dba", w:"Damages-based agreement (DBA)", d:"Lawyer takes a percentage of the damages recovered if the case succeeds."},
  {t:"funding-private-cfa-dba", w:"DBA caps", d:"Maximum DBA payment: 25% in personal injury, 35% employment, 50% other cases."},
  {t:"funding-private-cfa-dba", w:"ATE insurance", d:"After-the-event insurance covering the client's risk of paying the opponent's costs."},
  {t:"funding-legal-aid-tpf-lei", w:"LASPO 2012", d:"Act defining civil legal aid scope; many areas taken out of scope."},
  {t:"funding-legal-aid-tpf-lei", w:"Exceptional case funding", d:"Legal aid outside scope where refusal would breach human rights."},
  {t:"funding-legal-aid-tpf-lei", w:"Statutory charge", d:"Legal Aid Agency recovers its costs from property recovered or preserved."},
  {t:"funding-legal-aid-tpf-lei", w:"Merits test", d:"Legal aid needs adequate prospects of success, often at least 50%."},
  {t:"funding-legal-aid-tpf-lei", w:"R (PACCAR) v CAT", d:"Litigation funding agreements based on a share of damages are DBAs."},
  {t:"funding-legal-aid-tpf-lei", w:"Before-the-event (BTE) insurance", d:"Legal expenses insurance taken out before a dispute, often within home or motor policies."},
  {t:"transparency-client-care", w:"SRA Transparency Rules", d:"Firms must publish price and service information for certain services on their websites."},
  {t:"transparency-client-care", w:"SRA digital badge", d:"Clickable website logo confirming the firm is regulated by the SRA."},
  {t:"transparency-client-care", w:"Code para 8.3 complaints", d:"Clients must be told in writing at engagement of their right to complain."},
  {t:"transparency-client-care", w:"8 weeks", d:"Time for the firm's own complaints process before the client can go to LeO."},
  {t:"transparency-client-care", w:"Code para 8.7", d:"Clients must receive the best possible information on pricing and likely overall cost."},
  {t:"transparency-client-care", w:"Unsolicited approaches", d:"Code para 8.9 bans unsolicited approaches to members of the public."}
];

;
window.SQE_CARDS = window.SQE_CARDS || {};
window.SQE_CARDS["ls"] = [["What does the Legal Services Act 2007 do?","It sets up a **structure of regulators**. It sets **regulatory objectives** and **professional principles**. It lists six **reserved legal activities**.","sra-regulatory-role"],
["What is the role of the Legal Services Board (LSB)?","It is the **oversight regulator**. It supervises the **approved regulators**. It does not regulate individual lawyers.","sra-regulatory-role"],
["What is the relationship between the Law Society and the SRA?","The **Law Society** is the **approved regulator** for solicitors. It has **delegated** all its regulatory functions to the **SRA**.","sra-regulatory-role"],
["What does the Legal Ombudsman (LeO) deal with?","Consumer complaints about **poor service**. For example delay, poor communication or mistakes.","sra-regulatory-role"],
["Where does a complaint go if it is about poor service rather than a breach of the rules?","First to the **firm's complaints procedure**. Then to the **Legal Ombudsman**. A rule breach is a **conduct** matter for the **SRA**. One set of facts can raise both.","sra-regulatory-role"],
["When can a client take a complaint to the Legal Ombudsman?","After **8 weeks** without resolution, or once the firm gives its **final response**. Within **6 months** of the final response. Within **1 year** of the problem (or of when they should have known).","sra-regulatory-role"],
["What can the Legal Ombudsman order?","An **apology**, a **fee reduction** or **compensation**. Compensation is capped at **£50,000**.","sra-regulatory-role"],
["What are the LSA regulatory objectives?","Public interest; rule of law; **access to justice**; consumer interests; **competition**. An independent, strong, diverse and effective profession; public understanding of legal rights. Adherence to the professional principles; **prevention and detection of economic offences** (added by ECCTA 2023).","sra-regulatory-role"],
["What are the LSA professional principles?","**Independence and integrity**. **Proper standards** of work. Act in clients' **best interests**. **Duty to the court**. Keep clients' affairs **confidential**.","sra-regulatory-role"],
["Is promoting competition a regulatory objective or a professional principle?","A **regulatory objective** (an aim for regulators). Confidentiality and duty to the court are **professional principles** (duties on lawyers).","sra-regulatory-role"],
["What are the seven SRA Principles?","Uphold the **rule of law** and proper administration of justice. Uphold **public trust and confidence**. Act with **independence**, **honesty** and **integrity**. Encourage **equality, diversity and inclusion**. Act in the **best interests of each client**.","sra-regulatory-role"],
["Which SRA Principles win if they conflict?","Those protecting the **public interest** (including the rule of law and public confidence). They take precedence over the **client's interests**.","sra-regulatory-role"],
["Which two Codes of Conduct does the SRA have?","The **Code for Solicitors, RELs, RFLs and RSLs** (individuals). The **Code for Firms** (firms, managers, COLP and COFA).","sra-regulatory-role"],
["What does it mean that the SRA is principles-based and outcomes-focused?","It sets **high-level Principles** and short Codes. Solicitors use **professional judgement** to apply them. Guidance explains what they mean in practice.","sra-regulatory-role"],
["What does it mean that the SRA is risk-based?","It targets resources at the greatest **risks to the public**. Current risks are published in its **Risk Outlook** (e.g. money laundering, cybercrime, **SLAPPs**). Higher-risk firms get closer supervision.","sra-regulatory-role"],
["What is a SLAPP?","A **strategic lawsuit against public participation**. An abusive legal threat or claim designed to **silence critics or journalists**.","sra-regulatory-role"],
["What is the maximum fine the SRA can impose on a solicitor or traditional firm?","**£25,000**. It is **unlimited** for conduct relating to **economic crime** (under ECCTA, since 2024).","sra-regulatory-role"],
["What fines can the SRA impose on an ABS?","Up to **£250 million** on the ABS. Up to **£50 million** on its managers and employees.","sra-regulatory-role"],
["What other powers does the SRA have besides fines?","**Warnings** and **rebukes**. **Conditions** on a practising certificate or authorisation. **s.43 orders** controlling employment of non-solicitors. **Intervention** into a firm.","sra-regulatory-role"],
["Who can strike off or suspend a solicitor?","Only the **SDT** (or the High Court). The **SRA cannot**. The SDT can also impose an **unlimited fine** in any case.","sra-regulatory-role"],
["Who can carry on a reserved legal activity?","An **authorised person** (e.g. solicitor with a practising certificate). Or an **exempt person** (e.g. a litigant in person).","sra-regulatory-role"],
["What are the six reserved legal activities?","**Rights of audience**; **conduct of litigation**; **reserved instrument activities**. **Probate activities**; **notarial activities**; **administration of oaths**.","sra-regulatory-role"],
["Which reserved activities can a person do lawfully if they are not paid?","**Reserved instrument activities** (land transfers, leases, mortgages, lodging at HMLR): an individual acting **without a fee** is exempt. **Probate activities** (preparing papers for a grant) are only reserved when done **for a fee**. A friend doing either for free is not caught.","sra-regulatory-role"],
["What does administration of oaths cover?","Taking sworn statements: **affidavits** and **statutory declarations**.","sra-regulatory-role"],
["Which common legal services are not reserved legal activities under the Legal Services Act 2007?","**Will writing**; general legal **advice**; most **contract** drafting. **Employment tribunal** representation; most **tax** advice; **immigration** advice (regulated separately, not reserved). Mediation; estate administration **after** the grant.","sra-regulatory-role"],
["What is the consequence of carrying on a reserved activity when not entitled?","A **criminal offence** (s.14, up to **2 years**). **Pretending** to be entitled is also an offence (s.17). An employer whose employee does so commits an offence (s.16).","sra-regulatory-role"],
["Can unauthorised staff carry out litigation tasks?","Yes, **for and on behalf of** an authorised individual (Mazur, CA 2026). That individual must **retain responsibility** and have proper **supervision, management and control**. They need not approve every step personally.","sra-regulatory-role"],
["Can an unregulated will-writing company prepare probate papers for a fee?","**No**. Will writing is not reserved. But preparing papers for a **grant of probate** for a fee is a reserved **probate activity**.","sra-regulatory-role"],
["When can a freelance solicitor do reserved work without being an authorised firm?","They **employ no one**. They hold no client money except for **fees or disbursements on account**. They have **adequate and appropriate insurance**.","sra-regulatory-role"],
["What can a solicitor in an unregulated business do?","**Non-reserved** work only. They remain bound by the **SRA Principles and Code**. They must tell clients there is **no compulsory PII** and **no Compensation Fund** protection.","sra-regulatory-role"],
["What two financial safety nets do clients of SRA-authorised firms get?","**Professional indemnity insurance (PII)** for negligence. The **SRA Compensation Fund** for dishonesty or failure to account.","pii-other-providers"],
["Who must hold PII on the Minimum Terms and Conditions?","Every **SRA-authorised firm**. Cover must come from a **participating insurer**. Freelance solicitors need only **adequate and appropriate** insurance.","pii-other-providers"],
["What is the minimum PII cover for a firm?","**£3 million** per claim for **LLPs and companies**. **£2 million** for sole practitioners and partnerships. **Defence costs** are paid on top.","pii-other-providers"],
["What does claims-made basis mean for PII?","The policy in force **when the claim is first made** pays. Not the policy in force when the mistake happened.","pii-other-providers"],
["Who and what does PII cover?","The firm, its **principals** and **employees**. For **civil liability** arising from **private legal practice**.","pii-other-providers"],
["Can the PII excess be deducted from the client's payment?","**No**. The insurer pays the claimant in **full**. It recovers the excess from the **firm**.","pii-other-providers"],
["Can a PII insurer refuse to pay because the firm lied when buying cover?","**No**. It cannot avoid or reduce payment for **non-disclosure**, **misrepresentation** or breach of terms. It can **recover** from the firm afterwards.","pii-other-providers"],
["What happens if a firm fails to renew its PII?","**Extended policy period** of **30 days**. Then a **cessation period** of **60 days** (90 in total). No new work in the cessation period. No cover by the end means the firm must **close**.","pii-other-providers"],
["What run-off cover applies when a firm closes?","**6 years' run-off cover** if it closes **without a successor practice**. It covers claims made after closure about earlier work.","pii-other-providers"],
["Should a firm buy more than the minimum PII?","It should consider **top-up cover** where its work could produce **bigger claims**. For example high-value commercial or corporate deals.","pii-other-providers"],
["What is the nature of the SRA Compensation Fund?","**Discretionary**: no legal right to payment. A fund of **last resort**. Paid for by **contributions** from the profession.","pii-other-providers"],
["What losses does the Compensation Fund cover?","Loss caused by **dishonesty** of a solicitor, firm or employee. **Failure to account** for money received. Grants where a firm lacked required **PII**.","pii-other-providers"],
["Who can apply to the Compensation Fund?","**Individuals**. Smaller businesses, charities and trusts (turnover, income or assets broadly under **£2 million**). Large businesses cannot.","pii-other-providers"],
["What are the Compensation Fund limits?","Maximum grant normally **£2 million** per claim. Claim normally within **12 months** of becoming aware of the loss.","pii-other-providers"],
["Can clients of an unregulated business use the Compensation Fund?","**No**. Even if a solicitor works there.","pii-other-providers"],
["A solicitor misses a limitation date. Which protection responds?","**PII**: it is **negligence**.","pii-other-providers"],
["A solicitor steals completion money. Which protection responds?","The **Compensation Fund**: it is **dishonesty**. It is a **last resort** if PII does not respond.","pii-other-providers"],
["What is an ABS?","A **licensed body** under **Part 5 LSA 2007**. A firm doing reserved activities with **non-lawyer** owners or managers.","pii-other-providers"],
["Who licenses ABSs?","A **licensing authority**: the **SRA**, the **CLC** or certain other approved regulators.","pii-other-providers"],
["What compliance officers must an SRA firm have?","A **COLP** (compliance with the rules generally). A **COFA** (Accounts Rules). Both **approved** by the regulator. All SRA firms need them, not only ABSs.","pii-other-providers"],
["When must an owner of an ABS be approved?","When they hold a **material interest**. Generally **10%** or more of shares or votes, or significant influence. They must be **fit and proper**.","pii-other-providers"],
["Who regulates barristers and what can public access barristers do?","The **Bar Standards Board**. Public access barristers take instructions **directly from the public** without a solicitor.","pii-other-providers"],
["Who regulates chartered legal executives?","**CILEx Regulation (CRL)**. They can gain **practice rights** and run their own firms or be partners in SRA firms.","pii-other-providers"],
["What can licensed conveyancers do and who regulates them?","**Reserved instrument activities** and **probate**. Regulated by the **Council for Licensed Conveyancers**, which also licenses ABSs.","pii-other-providers"],
["Who regulates notaries?","The **Faculty Office** of the Archbishop of Canterbury.","pii-other-providers"],
["What protections do clients of unregulated providers lack?","**No compulsory PII**. **No Compensation Fund**. Often no access to the **Legal Ombudsman**.","pii-other-providers"],
["Who regulates immigration advisers and claims management companies?","Immigration advisers: the **Immigration Advice Authority**. Claims management companies: the **FCA**.","pii-other-providers"],
["In what two roles does the Equality Act 2010 bind a law firm?","As a **service provider** to clients (**Part 3**). As an **employer** (**Part 5**).","equality-act"],
["Which SRA rules overlap with the Equality Act?","**Principle 6** (encourage equality, diversity and inclusion). **Code para 1.1** (do not unfairly discriminate). **Code para 1.5** (treat colleagues fairly; no bullying or harassment).","equality-act"],
["What are the nine protected characteristics?","Age; disability; gender reassignment; marriage and civil partnership; pregnancy and maternity. Race; religion or belief; sex; sexual orientation.","equality-act"],
["Who does age protect in the provision of services?","Only people aged **18 or over**.","equality-act"],
["What is a disability under s.6 Equality Act?","A **physical or mental impairment**. With a **substantial** and **long-term** (**12 months**) adverse effect on normal day-to-day activities. **Cancer, HIV and MS** count from diagnosis.","equality-act"],
["Is marriage and civil partnership protected when receiving services?","**No**. It is protected **at work only**. Being single is not protected.","equality-act"],
["What does sex mean in the Equality Act?","**Biological sex** (For Women Scotland, 2025).","equality-act"],
["What does religion or belief cover?","Any religion, any religious or philosophical belief. And the **lack** of religion or belief.","equality-act"],
["What is direct discrimination (s.13)?","Treating a person **less favourably** than others **because of** a protected characteristic. It includes discrimination by **association** and by **perception**.","equality-act"],
["Can direct discrimination be justified?","**No**, except for **age**. Age discrimination can be justified as a **proportionate means of achieving a legitimate aim**.","equality-act"],
["What are the elements of indirect discrimination (s.19)?","A **PCP** applied to everyone. It puts a group sharing a characteristic at a **particular disadvantage**. It disadvantages the individual. The firm **cannot show** it is a **proportionate means of achieving a legitimate aim**.","equality-act"],
["How do you tell direct from indirect discrimination?","Direct: the rule **mentions or targets** the characteristic. Indirect: the rule is **neutral on its face** but hits one group harder. Only indirect (and age) can be **justified**.","equality-act"],
["What is discrimination arising from disability (s.15)?","**Unfavourable** treatment because of **something arising** from the disability. Defences: it is **proportionate**, or the firm **did not know** and could not reasonably have known of the disability.","equality-act"],
["What is harassment (s.26)?","**Unwanted conduct related to** a protected characteristic. With the **purpose or effect** of violating **dignity** or creating an **intimidating, hostile, degrading, humiliating or offensive** environment.","equality-act"],
["How is the effect of alleged harassment judged?","The person's **perception**. The other circumstances. Whether it is **reasonable** for the conduct to have that effect.","equality-act"],
["Which characteristics are not covered by harassment?","**Marriage and civil partnership** and **pregnancy and maternity** are never covered by harassment (s.26(5)). When the firm is providing services to clients, **religion or belief** and **sexual orientation** are not covered either (s.29(8)). Such cases are brought as direct discrimination.","equality-act"],
["What is victimisation (s.27)?","A **detriment** because the person did a **protected act**. For example bringing a claim, giving evidence or alleging a breach. A **false** allegation made in **bad faith** is not protected.","equality-act"],
["Does a victimisation claim depend on the original complaint being upheld?","**No**. It is enough that the complaint was made in **good faith**.","equality-act"],
["Does pregnancy and maternity discrimination need a comparator?","**No**. It is **unfavourable treatment** because of pregnancy or maternity leave, in work and services.","equality-act"],
["What three things can trigger the duty to make reasonable adjustments?","A **PCP**. A **physical feature**. Lack of an **auxiliary aid or service**.","equality-act"],
["How is the reasonable adjustments duty different for service providers?","It is **anticipatory**. The firm must think in advance about what disabled clients in general may need. For employers it is owed to a **known** disabled person.","equality-act"],
["Can a firm charge a disabled client for a reasonable adjustment?","**No**. The firm **cannot pass on the cost**, e.g. of a BSL interpreter.","equality-act"],
["What factors decide whether an adjustment is reasonable?","**Effectiveness**. **Practicability**. **Cost**. The firm's **resources** and size.","equality-act"],
["Is failing to make a reasonable adjustment discrimination?","**Yes** (s.21).","equality-act"],
["When is a firm vicariously liable for discrimination by employees (s.109)?","For acts done **in the course of employment**, whether or not it knew or approved. Its only defence is taking **all reasonable steps** to prevent them. The employee can also be personally liable (s.110).","equality-act"],
["What is the employer's duty to prevent sexual harassment (s.40A)?","Take **reasonable steps** to prevent **sexual harassment** of employees (from 26 October 2024). If breached, the tribunal can uplift compensation by up to **25%**.","equality-act"],
["What positive action is lawful?","Proportionate steps to help an **under-represented** group, e.g. encouragement and mentoring. Preferring such a candidate where candidates are **equally qualified** (tie-breaker).","equality-act"],
["Is positive discrimination lawful?","Generally **no**. Choosing someone regardless of merit, or quotas, is unlawful.","equality-act"],
["When can a firm lawfully refuse a client?","For a legitimate reason: lack of **expertise** or **capacity**, a **conflict**, or a request to act unlawfully. **Never** because of a protected characteristic.","equality-act"],
["What diversity reporting must SRA firms do?","Collect and report **workforce diversity data** to the SRA. Publish a **summary**.","equality-act"],
["What are the three stages of money laundering?","**Placement**: cash enters the system. **Layering**: moved to hide its origin. **Integration**: returns looking clean.","aml-framework-cdd"],
["What is a classic money laundering red flag in a client account?","Money paid in, then the deal **cancelled**. A request to send it to a **different person** or **another country**.","aml-framework-cdd"],
["How do POCA and the MLR 2017 fit together?","**POCA** creates the **criminal offences** and applies to everyone. The **MLR 2017** impose **preventive duties** (including CDD) on the **regulated sector**.","aml-framework-cdd"],
["What does the FATF do?","Sets global **AML standards**. Assesses countries. Publishes **high-risk jurisdiction** lists (black and grey lists).","aml-framework-cdd"],
["Who enforces financial sanctions?","HM Treasury's **OFSI**. Sanctions have **no** de minimis or risk-based exceptions.","aml-framework-cdd"],
["Who supervises SRA firms for AML?","The **SRA**. Professional body supervisors are overseen by **OPBAS** (part of the FCA).","aml-framework-cdd"],
["Is breach of the MLR 2017 a crime?","**Yes**, up to **2 years**. Even if no money is actually laundered.","aml-framework-cdd"],
["When do the MLR 2017 apply to solicitors?","When they **participate in financial or real property transactions**. E.g. buying or selling **land** or **businesses**; managing **client money** or assets; managing accounts. Organising contributions to companies; creating or managing **trusts or companies**.","aml-framework-cdd"],
["Who else is in the regulated sector besides lawyers on transactions?","**Tax advisers**. **Trust or company service providers** (company formation, acting as director or trustee, registered office, selling off-the-shelf companies).","aml-framework-cdd"],
["Which legal work is usually out of scope of the MLR 2017?","Pure **litigation**. **Employment** advice. **Family** work without property transfers. **Will drafting**. **Criminal** defence.","aml-framework-cdd"],
["Do the POCA principal offences apply outside the regulated sector?","**Yes**. ss.327-329 apply to **everyone**. Only the **s.330** failure to disclose offence is limited to the regulated sector.","aml-framework-cdd"],
["What firm-wide AML duties do the MLR 2017 impose?","Written **firm-wide risk assessment** (reg 18). **Policies, controls and procedures** (reg 19). Appoint an **MLCO** and an **MLRO** (reg 21). **Screen** and **train** staff.","aml-framework-cdd"],
["What is the role of the MLRO?","The **nominated officer**. Receives internal suspicion reports. Decides whether to make a **SAR** to the **NCA**.","aml-framework-cdd"],
["How long must CDD records be kept?","**5 years** after the end of the business relationship or completion of the occasional transaction.","aml-framework-cdd"],
["Can a person with a relevant criminal conviction own or manage a firm doing in-scope work?","**No**. Owners, officers and managers must be **approved** by the supervisor.","aml-framework-cdd"],
["When must CDD be carried out?","Establishing a **business relationship**. An **occasional transaction** of **£12,000 or more**. Any **suspicion** of money laundering. **Doubts** about earlier ID. Existing clients on a **risk-sensitive** basis.","aml-framework-cdd"],
["What does CDD involve?","**Identify and verify** the client from a reliable, independent source. **Identify** the **beneficial owner** and take reasonable measures to verify. Understand the **purpose** of the transaction. **Ongoing monitoring**.","aml-framework-cdd"],
["Who is a beneficial owner of a company?","Any individual owning or controlling **more than 25%** of shares or votes. Or who otherwise exercises **control**.","aml-framework-cdd"],
["Who are the beneficial owners of a trust?","The **settlor**, **trustees**, **beneficiaries** (or class). Anyone controlling the trust.","aml-framework-cdd"],
["Is checking the PSC register enough to verify a beneficial owner?","**No**, not on its own. Any **discrepancy** must be reported to **Companies House**.","aml-framework-cdd"],
["When must CDD verification be completed?","Normally **before** the relationship or transaction. It may be finished **during** a relationship if needed not to interrupt business and the risk is **low**.","aml-framework-cdd"],
["What must a firm do if it cannot complete CDD (reg 31)?","**Not** carry out the transaction or start the relationship. **Terminate** any existing relationship. **Consider** making a SAR.","aml-framework-cdd"],
["What is the lawyers' exception to reg 31?","Where the lawyer is **ascertaining the legal position** for the client. Or **defending or representing** the client in proceedings.","aml-framework-cdd"],
["What is simplified due diligence?","**Reduced** CDD for **low-risk** clients (e.g. listed companies, UK public authorities). It is **not no CDD**. Not available if there is any **suspicion**.","aml-framework-cdd"],
["What extra measures does enhanced due diligence involve?","More information on client and beneficial owner. **Source of funds** and **source of wealth**. **Senior management approval**. Closer **ongoing monitoring**.","aml-framework-cdd"],
["When is EDD mandatory?","A party established in a **FATF call for action country** (the FATF 'black list', not the grey list). A **PEP** or their family or close associate. **Unusually complex or unusually large** transactions, unusual patterns, or no apparent purpose. **False or stolen** ID. Any other **high-risk** case.","aml-framework-cdd"],
["Who is a politically exposed person (PEP)?","Someone with a **prominent public function**, UK or abroad. E.g. heads of state, ministers, **MPs**, senior judges, ambassadors. **Not** middle-ranking or junior officials.","aml-framework-cdd"],
["Which relatives and associates of a PEP are caught?","**Family**: spouse or partner, children and their partners, **parents**. **Known close associates**, e.g. joint business owners.","aml-framework-cdd"],
["What must a firm do when acting for a PEP?","Obtain **senior management approval**. Establish **source of wealth** and **source of funds**. Conduct **enhanced ongoing monitoring**.","aml-framework-cdd"],
["How are domestic PEPs treated?","As a **lower starting level of risk** than foreign PEPs. They are **still PEPs** and EDD still applies, but may be less extensive.","aml-framework-cdd"],
["How long does a person remain a PEP after leaving office?","At least **12 months**. This does not apply to their family members.","aml-framework-cdd"],
["What are the conditions for relying on another firm's CDD (reg 39)?","The other regulated person must **agree**. The relying firm **remains liable**. It must **immediately obtain** the information. It must be able to get **copies** of documents within **2 working days**.","aml-framework-cdd"],
["What are the two groups of POCA money laundering offences?","**Principal offences** (ss.327-329): direct involvement, apply to **everyone**. **Non-direct** offences (ss.330-333A, s.342): failing to report, tipping off, prejudicing an investigation.","poca-offences-reporting"],
["What is criminal conduct under s.340 POCA?","An offence anywhere in the UK, or conduct abroad that would be an offence here. **Any** crime counts, including **tax evasion**. There is **no minimum value**.","poca-offences-reporting"],
["What is criminal property?","Property that **constitutes or represents** a person's **benefit** from criminal conduct. The offender must **know or suspect** that it does. **Saved costs** (e.g. tax not paid) can be a benefit.","poca-offences-reporting"],
["What does suspicion mean for POCA?","A **possibility that is more than fanciful** that the facts exist. A vague unease is not enough. It need not be clear or firmly grounded (Da Silva).","poca-offences-reporting"],
["Name some money laundering red flags.","**Secretive** client; **large cash** or funds from an unknown **third party**. Money in with no transaction, or refund to a third party. Transactions with **no economic sense**. **Complex structures** with no reason; unusually **high fees** accepted.","poca-offences-reporting"],
["What is the maximum sentence for the principal offences?","**14 years** and/or an unlimited fine.","poca-offences-reporting"],
["What is the s.327 offence?","**Concealing**, disguising, converting or transferring criminal property. Or **removing** it from the UK jurisdictions.","poca-offences-reporting"],
["What is the s.328 offence?","Entering into or becoming **concerned in an arrangement**. Which you know or suspect **facilitates** acquisition, retention, use or control of criminal property **by or for another**. The main risk for **transactional** lawyers.","poca-offences-reporting"],
["What is the s.329 offence and its special defence?","**Acquiring, using or possessing** criminal property. Defence: **adequate consideration** (e.g. normal fees for genuine work). Not if you know or suspect the services help the criminal.","poca-offences-reporting"],
["Does conducting litigation fall within s.328?","**No**. Ordinary **conduct of legal proceedings** or a consensual **settlement** is not an arrangement (Bowman v Fels). **Sham litigation** is still caught.","poca-offences-reporting"],
["What is the main defence to the principal offences?","An **authorised disclosure** (s.338) to the **MLRO** or NCA **before** the act. Then **appropriate consent** (s.335), known as a **DAML**.","poca-offences-reporting"],
["Can a disclosure after the act be a defence?","**Yes**, if there was **good reason** for not disclosing earlier. And it was made as soon as practicable on your own initiative.","poca-offences-reporting"],
["What is the overseas conduct defence?","The conduct was **lawful where it happened**. And it would not carry more than **12 months'** imprisonment in the UK.","poca-offences-reporting"],
["What is the NCA notice period?","**7 working days**, from the first working day after the disclosure. If the NCA does not refuse, consent is **deemed** and you can proceed.","poca-offences-reporting"],
["What is the moratorium period?","**31 days** from the NCA's refusal. You **must not** proceed. If nothing more happens, you may go ahead at the end.","poca-offences-reporting"],
["How long can the moratorium be extended?","By the court, up to **31 days** at a time. Maximum **186 days** beyond the initial 31.","poca-offences-reporting"],
["What are the elements of s.330 failure to disclose?","You **know or suspect**, or have **reasonable grounds** to. The information came **in the course of business in the regulated sector**. You can identify the launderer or property, or it may assist. You do not disclose to the **MLRO** or NCA **as soon as practicable**.","poca-offences-reporting"],
["Can s.330 be committed by negligence?","**Yes**. It has an **objective** limb: reasonable grounds to suspect. Maximum **5 years**.","poca-offences-reporting"],
["What are the defences to s.330?","**Reasonable excuse**. **Privileged circumstances**. **Lack of training** (for an employee who did not actually suspect).","poca-offences-reporting"],
["What is the privileged circumstances defence?","A legal adviser need not disclose information received from a client for **legal advice**, or from anyone for **legal proceedings**. Lost if the information was given to **further a criminal purpose**.","poca-offences-reporting"],
["What are the s.331 and s.332 offences?","**s.331**: a regulated sector **MLRO** fails to pass on a report to the NCA. **s.332**: an MLRO **outside** the regulated sector fails to pass one on (subjective test only).","poca-offences-reporting"],
["What is tipping off (s.333A)?","Disclosing that a **SAR** has been made or an **investigation** is contemplated, where **likely to prejudice** it. **Regulated sector** only. Maximum **2 years**.","poca-offences-reporting"],
["What are the main tipping off defences?","Disclosure **within the firm** or group, or between professionals about a shared client to prevent an offence. Disclosure to the **supervisor**. A legal adviser disclosing to **dissuade** a client from an offence (s.333D).","poca-offences-reporting"],
["What is prejudicing an investigation (s.342)?","Making a disclosure **likely to prejudice** an investigation. Or **falsifying, concealing or destroying** documents. Applies to **anyone**; maximum **5 years**.","poca-offences-reporting"],
["Is telling a client there is a delay tipping off?","**No**, if you do not say why. But you must **not lie** to the client.","poca-offences-reporting"],
["What is the correct reporting procedure for a fee earner?","**Stop** the transaction. Report promptly to the **MLRO**. The MLRO decides whether to make a **SAR** and request a DAML. **Wait** for consent. **Do not tip off**. **Record** reasons.","poca-offences-reporting"],
["Does a SAR breach the duty of confidentiality?","**No**. It is a disclosure **permitted by law** (Code para 6.3). POCA protects the reporter from civil claims.","poca-offences-reporting"],
["When is legal professional privilege lost?","When the communication is made to **further a crime or fraud** (crime-fraud exception). The s.330 privileged circumstances defence is lost in the same way.","poca-offences-reporting"],
["What does s.19 FSMA (the general prohibition) say?","No one may carry on a **regulated activity** in the UK, or **purport** to, unless **authorised** or **exempt**.","financial-services"],
["What are the consequences of breaching the general prohibition?","**Criminal offence** (s.23, up to **2 years**). Agreements are **unenforceable** against the other party, who can recover money and **compensation** (s.26). A serious **regulatory** matter for a solicitor.","financial-services"],
["What is the defence to the s.23 offence?","Taking **all reasonable precautions** and exercising **all due diligence**.","financial-services"],
["Which bodies authorise financial firms?","The **FCA** (conduct; most firms). The **PRA** (banks, insurers, major investment firms).","financial-services"],
["What are the four questions for whether an activity is regulated?","Is there a **specified investment**? A **specified activity**? Is it **by way of business**? Does an **exclusion** apply, and if not, can **Part 20** be used?","financial-services"],
["Which investments are specified investments under FSMA 2000?","**Shares**; **debentures, bonds, gilts**; units in **collective investment schemes**. Options, futures, CFDs; **contracts of insurance** (incl. **ATE**). **Deposits**; regulated **mortgage** contracts; funeral plans; credit agreements.","financial-services"],
["What is not a specified investment?","**Land and buildings**. **Cash**. Physical goods (gold, art). Ordinary contracts for goods and services.","financial-services"],
["Is selling a client's house regulated under FSMA?","**No**: land is not a specified investment. Arranging the client's **mortgage** could be.","financial-services"],
["Name the specified activities.","**Dealing** as principal or agent; **arranging** deals; **managing** investments (with discretion). **Safeguarding and administering**; **advising** on investments. Insurance distribution, consumer credit and mortgage activities.","financial-services"],
["What counts as advising on investments?","Advice to an **investor** on the **merits** of buying or selling a **particular** investment. **Generic** advice (e.g. shares are riskier than gilts) is not.","financial-services"],
["What is the effect of an exclusion?","The activity is **not regulated** at all. No authorisation or exemption is needed.","financial-services"],
["What is the introducing exclusion (art 33)?","Introducing a client to an **authorised person** (e.g. an **IFA**) for independent advice or discretionary management.","financial-services"],
["When does the dealing or arranging through an authorised person exclusion apply (arts 22, 29)?","The transaction is with or through an **authorised person**. The client has **not sought or received advice** from you on the merits.","financial-services"],
["What is the necessary part of professional services exclusion (art 67)?","Arranging or advising that is a **necessary** part of other services. And **not remunerated separately**.","financial-services"],
["What is the trustees and personal representatives exclusion (art 66)?","Activities by a **trustee or PR** acting as such. Not **separately paid** for it.","financial-services"],
["What is the sale of a body corporate exclusion (art 70)?","Dealing, arranging or advising on a sale of shares carrying **50% or more** of the votes in a company. Between individuals or bodies corporate.","financial-services"],
["What are the four conditions of the Part 20 exemption (s.327)?","**No unaccounted-for reward**: commission passed to the client. **Incidental** to legal services. Only activities **permitted** by the SRA Scope Rules. **Compliance** with the Scope and Conduct of Business Rules.","financial-services"],
["What is the difference between incidental and necessary?","**Incidental** is the Part 20 test: arises from a legal service. **Necessary** is the art 67 exclusion: a necessary part of the service, not separately paid.","financial-services"],
["What do the SRA Scope Rules prohibit?","**Market making** and dealing as principal for profit. **Recommending** a **retail investment product** or **personal pension**, or advising on pension transfers. Discretionary management for private clients (limited exceptions). Acting as a **lender** under regulated credit or mortgages.","financial-services"],
["What must a firm doing insurance distribution under Part 20 do?","Be on the **FCA Register** as an exempt professional firm.","financial-services"],
["What do the SRA Conduct of Business Rules require?","**Status disclosure**: not FCA-authorised, regulated by SRA, how to complain. **Best execution**. **Records** of transactions and **commissions**. Written confirmation of **execution-only** deals.","financial-services"],
["What should a solicitor do if a client wants a recommendation of a particular pension or unit trust?","**Introduce** them to an **IFA** (excluded under art 33). Recommending a retail investment product is **prohibited** under Part 20.","financial-services"],
["What is the financial promotion restriction (s.21)?","No **invitation or inducement** to engage in investment activity in the course of business. Unless **authorised**, **approved** by an authorised person, or an **exemption** applies.","financial-services"],
["Name exemptions from the financial promotion restriction.","**One-off** tailored non-real-time communications. **Sale of a body corporate**. Exempt professional firms' communications **incidental** to their services.","financial-services"],
["When is letting a client pay fees by instalments exempt from consumer credit rules?","**12 or fewer** instalments. Within **12 months**. **No interest** or other charges.","financial-services"],
["What costs information must a solicitor give under Code para 8.7?","The **best possible information** about how the matter will be **priced**. And the **likely overall cost**, at the outset and as the matter progresses.","funding-private-cfa-dba"],
["What funding and cost points should be discussed at the outset?","The **basis** of charging and an **estimate**. **Disbursements** and **VAT**. Existing funding: **BTE**, **trade union**, **legal aid**. **Costs risk** and whether the outcome justifies the cost.","funding-private-cfa-dba"],
["What is the general costs rule in litigation?","The **loser pays** the winner's costs (CPR Part 44), at the court's discretion. The winner rarely recovers all its costs. The client stays liable to pay **their own solicitor**.","funding-private-cfa-dba"],
["How is a private retainer usually charged?","At an **hourly rate** (varying with seniority). Plus **disbursements** and **VAT**. Payable whatever the outcome.","funding-private-cfa-dba"],
["Is an estimate binding?","**No**. But it must be **realistic** and the client told promptly if it will be exceeded.","funding-private-cfa-dba"],
["Is a quotation or fixed fee binding?","**Yes**. The firm cannot charge more for the work described. Extra work outside the scope can be charged if agreed.","funding-private-cfa-dba"],
["What is a costs cap?","A **binding** upper limit. The **firm** bears the risk above it.","funding-private-cfa-dba"],
["How must money on account of costs be held?","As **client money** in the **client account**. Until a bill is delivered or it is spent on a disbursement.","funding-private-cfa-dba"],
["When can a firm charge interest on unpaid bills?","Only if the **client agreed** it (usually in the client care letter).","funding-private-cfa-dba"],
["How can a client challenge a solicitor's bill?","Ask the court to **assess** it under the **Solicitors Act 1974**. Apply within **one month** of delivery for assessment as of right. Or complain to the firm and then the **Legal Ombudsman**.","funding-private-cfa-dba"],
["What is the risk of a fixed fee for the firm?","If the matter takes longer, the **firm** bears the extra cost. It must define what is **included and excluded**.","funding-private-cfa-dba"],
["How do fixed recoverable costs differ from fixed fees?","**FRC** limit what the winner recovers from the **opponent** (fast and intermediate track, up to **£100,000**). They do not limit what client and solicitor agree. The client may pay the **difference**.","funding-private-cfa-dba"],
["How does a CFA work?","Fees are payable **only if the client wins**. On a win: **base costs** plus any **success fee**. The success fee is a **percentage uplift on base costs**.","funding-private-cfa-dba"],
["What is a discounted CFA?","**No win, lower fee**. A reduced rate if the client loses. Full rates (perhaps plus a success fee) if they win.","funding-private-cfa-dba"],
["What formalities apply to a CFA (s.58 CLSA)?","Must be **in writing**. Not for **criminal** or **family** proceedings. Must state the success fee **percentage**.","funding-private-cfa-dba"],
["What is the general cap on a CFA success fee?","**100%** of base costs.","funding-private-cfa-dba"],
["What is the personal injury cap on a CFA success fee?","**25%** of damages for **PSLA** and **past pecuniary loss**, net of CRU. **Future loss** is excluded.","funding-private-cfa-dba"],
["Who pays a CFA success fee?","The **client**, usually from damages (since **1 April 2013**, LASPO s.44). It is **not recoverable** from the opponent. The opponent still pays **base costs**.","funding-private-cfa-dba"],
["What might a client who loses under a CFA still pay?","Their own **disbursements**. The **opponent's costs** (hence ATE, or QOCS in personal injury).","funding-private-cfa-dba"],
["How does a DBA work?","The lawyer takes a **percentage of the sum recovered**. Only if the client wins.","funding-private-cfa-dba"],
["What are the DBA caps?","**Personal injury**: **25%** of PSLA and past loss. **Employment tribunal**: **35%**. **Other civil claims**: **50%**. Caps **include VAT** and counsel's fees.","funding-private-cfa-dba"],
["What happens if a DBA does not comply with the Regulations?","It is **unenforceable**: the lawyer gets nothing under it. It must be in writing and specify the claim, when payment is due and why that percentage.","funding-private-cfa-dba"],
["Where are DBAs not allowed?","**Criminal** and **family** proceedings. **Opt-out collective proceedings** in the CAT.","funding-private-cfa-dba"],
["How do recovered costs interact with a DBA payment?","Costs recovered from the opponent are **set off** against the DBA payment. The client pays only the **balance** from damages.","funding-private-cfa-dba"],
["What is the indemnity principle?","Costs recovered from the opponent cannot exceed what the client is **liable to pay** their own lawyer.","funding-private-cfa-dba"],
["Are hybrid DBAs allowed?","Generally regarded as **not permitted**. On a win the lawyer's only payment is the agreed **percentage** (plus expenses).","funding-private-cfa-dba"],
["What is the key difference between a CFA and a DBA?","A CFA success fee is a percentage of **costs**. A DBA payment is a percentage of **damages**.","funding-private-cfa-dba"],
["Who administers civil legal aid?","The **Legal Aid Agency** (Ministry of Justice), under **Part 1 LASPO 2012**. Only providers with an **LAA contract** can do the work.","funding-legal-aid-tpf-lei"],
["What three hurdles must a civil legal aid case pass?","**Scope**. **Means test**. **Merits test**.","funding-legal-aid-tpf-lei"],
["Which family cases are in scope for legal aid?","Cases with evidence of **domestic abuse** or **child abuse** (for the victim). **Care proceedings**.","funding-legal-aid-tpf-lei"],
["Name other areas in scope for legal aid.","**Housing** (possession, homelessness, serious disrepair). **Debt** where the **home is at risk**. **Discrimination**. **Asylum**. **Judicial review**, mental health, community care.","funding-legal-aid-tpf-lei"],
["When is clinical negligence in scope for legal aid?","Only for infants with **birth-related brain injury** (in the womb or within **8 weeks** of birth).","funding-legal-aid-tpf-lei"],
["Name areas out of scope for legal aid.","Private family disputes **without abuse** evidence. Most **personal injury**. Most **contract** and **employment** claims. Most non-asylum immigration; welfare benefits advice.","funding-legal-aid-tpf-lei"],
["What is exceptional case funding?","Funding for an out-of-scope case (LASPO **s.10**). Where refusal would **breach ECHR rights** (e.g. Article 6) or risk a breach.","funding-legal-aid-tpf-lei"],
["What does the legal aid means test look at?","**Gross income**. **Disposable income**. **Disposable capital**.","funding-legal-aid-tpf-lei"],
["What is passporting?","Clients on certain means-tested benefits (e.g. **Universal Credit**) **automatically pass the income test**. Their **capital** is still assessed.","funding-legal-aid-tpf-lei"],
["Which legal aid matters are not means tested?","For example **parents and children** in **care proceedings**.","funding-legal-aid-tpf-lei"],
["What prospects of success are needed for full representation?","Generally **moderate** (**50% or more**). **Marginal** may be enough in some categories. **Poor** (below 45%) fails.","funding-legal-aid-tpf-lei"],
["What other merits criteria apply?","**Cost-benefit**: likely benefit must justify cost. **Reasonable private paying client** test.","funding-legal-aid-tpf-lei"],
["What are the levels of legal aid service?","**Legal Help** (advice, no court). **Family Help**. **Legal Representation** (investigative and full).","funding-legal-aid-tpf-lei"],
["What is the statutory charge?","The LAA's **first charge** on money or property **recovered or preserved** (LASPO **s.25**). It recovers unrecovered legal aid costs. The client must be **warned** at the outset.","funding-legal-aid-tpf-lei"],
["What costs protection does a legally aided loser have?","They pay the opponent's costs only up to a **reasonable** amount (LASPO **s.26**). Considering both parties' **resources** and conduct. Often **nil**.","funding-legal-aid-tpf-lei"],
["How does third-party litigation funding work?","A commercial funder pays costs in return for a **multiple** of its investment or a **percentage** of damages. If the claim fails the funder gets **nothing** (non-recourse).","funding-legal-aid-tpf-lei"],
["How are litigation funders regulated?","No statutory regulator. **Self-regulated** through the **Association of Litigation Funders** Code.","funding-legal-aid-tpf-lei"],
["To whom does the solicitor owe duties in a funded case?","The **client**, not the funder. The client still gives **instructions**. Watch for **conflicts**.","funding-legal-aid-tpf-lei"],
["Can a funder be ordered to pay the opponent's costs?","**Yes**, by a **non-party costs order** if the claim fails.","funding-legal-aid-tpf-lei"],
["What is the effect of PACCAR?","A funding agreement based on a **percentage of damages** is a **DBA**. It is **unenforceable** unless DBA-compliant. It cannot be used in opt-out CAT collective proceedings.","funding-legal-aid-tpf-lei"],
["Is a funding agreement based on a multiple of the investment a DBA?","**No** (Sony v Neill), even if capped by reference to damages.","funding-legal-aid-tpf-lei"],
["Has PACCAR been reversed by statute?","**No**. As at September 2026 it **remains the law**.","funding-legal-aid-tpf-lei"],
["What is BTE insurance?","Cover bought **before** any dispute, often an add-on to home or motor insurance, or via a trade union. Solicitors should **always check** for it.","funding-legal-aid-tpf-lei"],
["What are typical BTE terms?","A **limit** on cover. **Reasonable prospects** of success. Insurer's **consent** before steps.","funding-legal-aid-tpf-lei"],
["When can a BTE insured choose their own lawyer?","Once **proceedings or an inquiry** start. Or where a **conflict of interest** arises.","funding-legal-aid-tpf-lei"],
["What does ATE insurance cover?","The **opponent's costs** if the client loses. Often the client's own **disbursements**.","funding-legal-aid-tpf-lei"],
["Is the ATE premium recoverable from the opponent?","**No** (since April 2013). Exception: in **clinical negligence**, the part covering **expert reports on liability and causation**.","funding-legal-aid-tpf-lei"],
["What protects personal injury claimants from adverse costs?","**QOCS** (CPR 44.13-44.17). So ATE mainly covers their own **disbursements**.","funding-legal-aid-tpf-lei"],
["Is arranging ATE insurance a regulated activity?","**Yes**: **insurance distribution**. The firm must use **Part 20** (and be on the FCA Register) or an authorised intermediary.","funding-legal-aid-tpf-lei"],
["In what order should funding options be considered?","**BTE** or union. **Legal aid** if in scope. **CFA or DBA** with ATE. **Third-party funding** for high-value claims. Otherwise **private**.","funding-legal-aid-tpf-lei"],
["Who must comply with the SRA Transparency Rules?","**SRA-authorised firms**. **Freelance solicitors** (with adaptations).","transparency-client-care"],
["Where must Transparency Rules information be published?","On the firm's **website** in a **prominent** place. Without a website, **available on request**.","transparency-client-care"],
["For which individual services must price information be published?","**Residential conveyancing**. **Uncontested probate**. **Motoring offences**. **Bringing** ET claims for unfair or wrongful dismissal. **Immigration** (not asylum).","transparency-client-care"],
["For which business services must price information be published?","**Debt recovery** up to **£100,000**. **Defending** ET claims for unfair or wrongful dismissal. **Licensing** applications for business premises.","transparency-client-care"],
["What must published costs information include?","**Total cost** (or average or range); the **basis** of charges. **Experience and qualifications** of staff and supervisors. Likely **disbursements** and **VAT**. Any **CFA or DBA** fees; **services included**. **Key stages** and **timescales**.","transparency-client-care"],
["What must every firm publish, whatever services it offers?","Its **complaints procedure**, including how to complain to **LeO** and the **SRA**. That it is **regulated by the SRA**, with its number (and the **SRA clickable logo**).","transparency-client-care"],
["Does a commercial property firm need to publish prices?","**No**: commercial property is not a listed service. It must still publish its **complaints procedure**.","transparency-client-care"],
["What does Code para 8.1 require?","Identify **who you are acting for** in each matter.","transparency-client-care"],
["What must clients be told under Code para 8.3?","**In writing at engagement**: their right to **complain** about services and charges. How and to whom. Any right to complain to **LeO** and **when**.","transparency-client-care"],
["What must clients be told under Code para 8.4?","If unresolved after **8 weeks**: in writing, their right to go to **LeO**, the time frame and full contact details. If the complaints procedure is **exhausted**: that the firm cannot settle it, the name and website of an approved **ADR** body and whether the firm will use it.","transparency-client-care"],
["How must complaints be dealt with (para 8.5)?","**Promptly**, **fairly** and **free of charge**.","transparency-client-care"],
["What does Code para 8.6 require?","Information in a way clients can **understand**. So they can make **informed decisions**.","transparency-client-care"],
["What does Code para 8.8 require of publicity?","It must be **accurate and not misleading**, including about **charges** and **interest**.","transparency-client-care"],
["What does Code para 8.9 prohibit?","**Unsolicited approaches** to the public to advertise services. Except to **current or former clients**.","transparency-client-care"],
["What do Code paras 8.10 and 8.11 require?","Clients understand **whether and how** services are **regulated**. And what **protections** are available (PII, Compensation Fund).","transparency-client-care"],
["What are the Legal Ombudsman time limits?","Within **6 months** of the firm's final response (if it told the client about LeO). **And** within **1 year** of the act or of when the client should have known.","transparency-client-care"],
["Does the Legal Ombudsman deal with misconduct?","**No**. LeO deals with **service**. **Conduct** is for the **SRA**, at any time.","transparency-client-care"],
["What does a client care letter usually cover?","**Who** does and supervises the work. **Scope** of the retainer. **Costs** and funding. **Complaints**. **Regulation**. Other terms such as AML checks and ending the retainer.","transparency-client-care"],
["When do the Consumer Contracts Regulations 2013 give a client of a law firm a right to cancel?","When a **consumer** contract is made **off-premises** or **at a distance** (e.g. online, phone, at the client's home). The firm must give **pre-contract information** and the right to **cancel within 14 days**.","transparency-client-care"],
["What if the firm fails to give cancellation information?","The cancellation period is **extended** by up to **12 months**.","transparency-client-care"],
["What if a consumer client wants work started within the 14 days?","They must **expressly request** it. If they cancel, they pay for **work done** up to cancellation.","transparency-client-care"]];

;
window.SQE_QA = window.SQE_QA || {};
window.SQE_QA["ls"] = [
 {
  "t": "sra-regulatory-role",
  "q": "Westbrook Wills Ltd is an unregulated company employing no solicitors. It advertises a range of services to the public for a fee.\n\nWhich of the following services can Westbrook Wills Ltd lawfully provide?",
  "o": [
   "Preparing the papers on which to apply for a grant of probate.",
   "Drafting a will for a client and supervising its execution.",
   "Issuing a claim form in the County Court on behalf of a client.",
   "Preparing and lodging a TR1 transfer at HM Land Registry.",
   "Appearing as advocate for a client at a fast track trial in the County Court."
  ],
  "a": 1,
  "e": "**Drafting a will** is not a reserved legal activity, so an unregulated business can do it.\n\nThe six reserved legal activities under the **Legal Services Act 2007** are rights of audience, conduct of litigation, reserved instrument activities, probate activities, notarial activities and administration of oaths. Only authorised (or exempt) persons may carry them out.\n- Preparing probate papers for a fee is a **probate activity**.\n- Issuing a claim form is **conduct of litigation**.\n- Preparing and lodging a land transfer for a fee is a **reserved instrument activity**.\n- Appearing as an advocate at a fast track trial is exercising a **right of audience** (lay representatives have a limited statutory right only in small claims hearings).\n\nCarrying on a reserved activity when not entitled is a **criminal offence**."
 },
 {
  "t": "sra-regulatory-role",
  "q": "Priya instructed Elm Solicitors on her divorce. She is unhappy that her solicitor repeatedly failed to return her calls and missed a deadline for filing a document. She complained to the firm five weeks ago and has received an acknowledgement but no final response.\n\nWhich of the following best describes Priya's position?",
  "o": [
   "She can go to the SRA now, because poor service is a conduct matter for the regulator.",
   "She must apply to the Solicitors Disciplinary Tribunal, which hears all complaints about solicitors.",
   "She can go to the Legal Ombudsman now, because the firm has had a reasonable time to respond.",
   "She can only bring a claim in negligence, because the Legal Ombudsman cannot award compensation.",
   "She must wait for 8 weeks or a final response before going to the Legal Ombudsman."
  ],
  "a": 4,
  "e": "Delay and poor communication are **service** complaints, which go to the firm and then to the **Legal Ombudsman**. LeO normally accepts a complaint only after **8 weeks** without resolution or once the firm has given its **final response**, so Priya must wait. The SRA deals with **conduct** (rule breaches), and the SDT hears serious disciplinary cases brought by the SRA. LeO can award compensation up to **£50,000**."
 },
 {
  "t": "sra-regulatory-role",
  "q": "Tom is a paralegal (not an authorised person) at Gale LLP. He drafts and files a defence and serves documents in a County Court claim. Nadia, a partner and solicitor with a practising certificate, has overall conduct of the claim, reviews Tom's work at regular file reviews and has put a supervision policy in place. She does not approve every step personally.\n\nWhich of the following best describes the position?",
  "o": [
   "Tom is committing a criminal offence, because only an authorised person may take any step in litigation.",
   "The arrangement is lawful only if Nadia personally approves each document before it is filed.",
   "Tom may lawfully do these tasks on Nadia's behalf, as she keeps responsibility and supervises.",
   "The arrangement is lawful, because the conduct of litigation is not a reserved legal activity.",
   "The arrangement is lawful only if Tom is a CILEX member with litigation practice rights."
  ],
  "a": 2,
  "e": "The **conduct of litigation** is a reserved activity, but an unauthorised person may carry out litigation tasks **for and on behalf of** an authorised individual who **retains responsibility** and has appropriate **supervision, management and control** arrangements. The authorised person **need not approve every step** personally. Tom therefore commits no offence, and he does not need his own practice rights."
 },
 {
  "t": "pii-other-providers",
  "q": "Hollis & Co LLP is closing down. It has no successor practice. A former client discovers two years after the closure that the firm negligently failed to register a charge in his favour, and wishes to claim.\n\nWhich of the following best describes the position?",
  "o": [
   "The claim can be made against the firm's run-off cover, which the minimum terms require for six years after closure.",
   "The client must apply to the SRA Compensation Fund because negligence claims after closure are excluded from PII.",
   "The claim fails because the firm's PII policy lapsed when it stopped practising.",
   "The client can only claim against the individual members of the LLP personally because PII does not survive closure.",
   "The client must complain to the Legal Ombudsman, which has exclusive jurisdiction once a firm has closed."
  ],
  "a": 0,
  "e": "The best answer is that the claim can be made under the firm's **run-off cover**.\n\nUnder the SRA **Minimum Terms and Conditions** of PII, when a firm ceases practice without a successor practice, its policy must provide **six years' run-off cover** for claims made after closure arising from work done while it practised. PII is on a **claims-made** basis, so without run-off the claim would be uncovered.\n\n- The policy does not simply lapse: run-off exists precisely for this situation.\n- The **Compensation Fund** is a discretionary last resort mainly for **dishonesty** or failure to account, not ordinary negligence covered by insurance.\n- Members of an LLP are generally not personally liable for the LLP's debts.\n- **LeO** deals with service complaints; it does not have exclusive jurisdiction over a negligence claim."
 },
 {
  "t": "pii-other-providers",
  "q": "Ravi is a chartered accountant. He wants to buy 30% of the shares in Kendall Solicitors Ltd, an SRA-authorised recognised body, and become a director. None of the current owners objects.\n\nWhich of the following best describes what is required?",
  "o": [
   "Nothing further, because non-lawyers may own up to 49% of a recognised body without approval.",
   "Ravi must first qualify as a solicitor, because only lawyers may own or manage a law firm.",
   "The firm must become FCA-authorised, because a non-lawyer owner makes the firm a financial institution.",
   "The firm will need to be licensed as an ABS and Ravi must be approved by the SRA as an owner and manager.",
   "Ravi must register with the Legal Services Board, which approves non-lawyer owners directly."
  ],
  "a": 3,
  "e": "The firm must become an **alternative business structure (ABS)**, a licensed body under **Part 5 of the Legal Services Act 2007**, and Ravi must be **approved** by the licensing authority.\n\nA firm with a non-lawyer owner or manager must be licensed as an ABS. Anyone with a **material interest** (generally **10%** or more) must be approved as fit and proper, and managers must also be approved. The SRA is a licensing authority.\n\n- There is no free 49% allowance for non-lawyers in a recognised body.\n- ABSs exist precisely so non-lawyers can own and manage law firms.\n- Non-lawyer ownership does not trigger FCA authorisation.\n- The LSB oversees regulators; it does not approve individual owners."
 },
 {
  "t": "pii-other-providers",
  "q": "Jasmine is a sole practitioner. She steals £400,000 of a client's sale proceeds from the client account and disappears. The client, Ade, is a retired teacher. Jasmine's PII insurer declines to cover the loss, and Jasmine has no assets.\n\nWhich of the following best describes how Ade may recover his money?",
  "o": [
   "He has a legal right to full payment from the Legal Ombudsman.",
   "He can apply to the SRA Compensation Fund, which may make a discretionary grant as a last resort.",
   "He can recover from the Law Society, which is liable for the dishonesty of all solicitors.",
   "He can claim against the firm's run-off cover, which applies to dishonesty claims.",
   "He has no remedy, because PII covers only negligence."
  ],
  "a": 1,
  "e": "The **SRA Compensation Fund** covers losses caused by a solicitor's **dishonesty** or **failure to account**, where no other remedy is available. It is **discretionary** and a fund of **last resort**, so Ade has no legal right to payment, but as an individual he is eligible and the normal limit is **£2 million**. The Legal Ombudsman deals with poor service, and run-off cover is part of PII for claims after closure, not a separate dishonesty fund."
 },
 {
  "t": "equality-act",
  "q": "Patience instructs Grange Solicitors in a boundary dispute. She is profoundly deaf and uses British Sign Language. The firm arranges a BSL interpreter for her meetings and proposes to add the interpreter's fees to her bill as a disbursement.\n\nWhich of the following best describes the firm's position?",
  "o": [
   "The firm may add the fees because an interpreter is a disbursement like any expert fee.",
   "The firm may add the fees only if Patience agreed to them in writing at the outset.",
   "The firm must split the cost equally with Patience as a matter of reasonableness.",
   "The firm need not provide an interpreter at all if Patience can bring a family member.",
   "The firm must not charge Patience for the interpreter because it is a reasonable adjustment."
  ],
  "a": 4,
  "e": "The firm **must not charge Patience** for the interpreter.\n\nUnder **ss.20-21 Equality Act 2010**, a service provider must take reasonable steps to provide an **auxiliary aid or service** where a disabled person would otherwise be at a substantial disadvantage. A BSL interpreter is a classic auxiliary service. The Act provides that the disabled person **cannot be required to pay** for the cost of a reasonable adjustment.\n\n- Treating it as a disbursement, even with consent or by sharing the cost, passes the cost to the disabled client, which is not allowed.\n- Relying on family members is not an adequate adjustment and raises confidentiality concerns.\n- The duty is also **anticipatory** for service providers."
 },
 {
  "t": "equality-act",
  "q": "Marlow LLP introduces a rule that all associates must work full-time in the office, five days a week, with no exceptions. Fiona, an associate with childcare responsibilities, is refused a request to work four days a week. Statistically, women at the firm are much more likely than men to be unable to comply.\n\nWhich of the following best describes Fiona's likely claim?",
  "o": [
   "Harassment, because the refusal created an offensive environment for her.",
   "Direct sex discrimination, which the firm cannot justify in any circumstances.",
   "Indirect sex discrimination, unless the firm can justify the rule as proportionate.",
   "Victimisation, because she has been subjected to a detriment for asking.",
   "No claim, because the same rule is applied equally to every associate, male or female."
  ],
  "a": 2,
  "e": "The best answer is **indirect sex discrimination**, subject to justification.\n\nUnder **s.19 Equality Act 2010**, indirect discrimination occurs where a **provision, criterion or practice** applied to everyone puts people sharing a protected characteristic at a **particular disadvantage**, it disadvantages the claimant, and the employer cannot show it is a **proportionate means of achieving a legitimate aim**. A full-time rule disproportionately disadvantages women, who more often have primary childcare responsibilities.\n\n- **Direct** discrimination requires less favourable treatment **because of** sex. The rule applies to everyone.\n- **Harassment** requires unwanted conduct related to sex with the prohibited purpose or effect; nothing suggests this.\n- **Victimisation** requires a **protected act**, such as bringing a discrimination complaint; a flexible working request is not one.\n- Applying a rule equally is exactly what indirect discrimination catches."
 },
 {
  "t": "equality-act",
  "q": "Tariq asks Byrne Solicitors to act on his purchase of a shop. Gareth, the partner who would handle it, tells reception to turn Tariq away because Gareth \"prefers not to act for clients of his faith\". The firm has the expertise and capacity to act, and there is no conflict.\n\nWhich of the following best describes the position?",
  "o": [
   "The refusal is direct religious discrimination and breaches the SRA Code and Principles.",
   "The refusal is lawful if the firm offers Tariq a referral to another firm.",
   "The firm may refuse, because a firm is always free to decide which instructions it accepts.",
   "The refusal is indirect discrimination, which the firm can justify as a business choice.",
   "The refusal breaches the Code only if Tariq makes a complaint to the firm."
  ],
  "a": 0,
  "e": "The refusal is **direct discrimination** because of **religion or belief**.\n\nUnder **s.13 Equality Act 2010**, refusing a service **because of** a protected characteristic is direct discrimination, which cannot be justified (except for age). Firms are bound as **service providers**. It also breaches **Code para 1.1** (you do not unfairly discriminate by allowing your personal views to affect your professional relationships) and **Principle 6** (encourage equality, diversity and inclusion).\n\n- A firm is generally free to refuse instructions, but not for a discriminatory reason.\n- Offering a referral does not cure the discrimination.\n- This is **direct**, not indirect, discrimination: the reason is the client's faith itself.\n- The breach happens whether or not Tariq complains."
 },
 {
  "t": "aml-framework-cdd",
  "q": "Northfield Trading Ltd, a private company, instructs Cole Solicitors to act on the purchase of a warehouse. The company's shares are held as follows: Anna 40%, Ben 35%, and five other investors with 5% each.\n\nAs part of customer due diligence, which of the following must the firm do?",
  "o": [
   "Identify and verify the company only, because beneficial owners need be identified only for trusts.",
   "Identify and verify Anna and Ben only if the firm has a suspicion of money laundering.",
   "Identify and verify every shareholder, because all shareholders of a private company are beneficial owners.",
   "Identify and verify the company, and identify Anna and Ben and take reasonable steps to verify them.",
   "Rely on the company's own written confirmation of its shareholders without further checks."
  ],
  "a": 3,
  "e": "The firm must **identify and verify the company**, and identify the **beneficial owners**, **Anna and Ben**, taking reasonable measures to verify their identity.\n\nUnder the **MLR 2017**, a property purchase is in scope. **CDD** requires identifying and verifying the client and identifying any **beneficial owner**: for a company, an individual who owns or controls **more than 25%** of the shares or voting rights. Anna (40%) and Ben (35%) qualify; the 5% holders do not. The firm must also understand the ownership and control structure.\n\n- Beneficial owners must be identified for companies as well as trusts.\n- Beneficial ownership checks are part of **standard** CDD, not just triggered by suspicion.\n- Shareholders at 25% or below are not beneficial owners unless they control the company otherwise.\n- The client's own unverified statement is not enough."
 },
 {
  "t": "aml-framework-cdd",
  "q": "Dmitri instructs Ashby Solicitors to buy a London flat for £3 million. During the onboarding process, the firm learns that his wife, Elena, is currently the finance minister of an overseas country. Dmitri will pay the price from a personal account.\n\nWhich of the following must the firm do?",
  "o": [
   "Carry out standard CDD only, because Dmitri himself holds no public office.",
   "Apply enhanced due diligence, including source of wealth and senior management approval.",
   "Refuse to act, because a firm may not act for a PEP or for any member of a PEP's family.",
   "Make a SAR to the NCA immediately, because acting for a PEP's family is suspicious in itself.",
   "Apply simplified due diligence, because the price is being paid from a personal account."
  ],
  "a": 1,
  "e": "The firm must apply **enhanced due diligence**.\n\nUnder **reg 35 MLR 2017**, a **politically exposed person** includes a person entrusted with a prominent public function (here, Elena, a foreign minister), and the rules extend to their **family members**, including a spouse. For a PEP or family member, the firm must obtain **senior management approval**, take adequate measures to establish **source of wealth and source of funds**, and conduct **enhanced ongoing monitoring**.\n\n- Dmitri is caught as a **family member** even though he holds no office.\n- **SDD** is for low-risk cases; this is high risk.\n- Firms **may** act for PEPs; the rules require EDD, not refusal.\n- PEP status alone is not grounds for suspicion; a SAR is needed only if there is knowledge or suspicion of laundering."
 },
 {
  "t": "aml-framework-cdd",
  "q": "Chen Solicitors is acting for Orla on a share purchase. Orla's bank, an FCA-regulated credit institution, has already carried out customer due diligence on her and agrees that Chen Solicitors may rely on it.\n\nWhich of the following best describes the position?",
  "o": [
   "Chen Solicitors may rely on the bank and need not keep any record of Orla's identity.",
   "Chen Solicitors may rely on the bank, and liability for any CDD failure passes to the bank.",
   "Chen Solicitors cannot rely on a bank because reliance is permitted only between law firms.",
   "Chen Solicitors may rely on the bank only if Orla is a PEP and the bank has applied enhanced checks.",
   "Chen Solicitors may rely on the bank but remains liable for any failure in the CDD."
  ],
  "a": 4,
  "e": "Chen Solicitors may **rely** on the bank but **remains liable** for any failure.\n\nUnder **reg 39 MLR 2017**, a relevant person may rely on certain other regulated persons (including credit institutions and other firms) to apply CDD, if they agree. However, the relying firm **remains liable** for any failure, must **immediately obtain** the CDD information, and must have an arrangement to get **copies of documents** within 2 working days of request.\n\n- Liability does **not** pass to the bank.\n- Reliance is not limited to law firms.\n- PEP status is irrelevant to whether reliance is allowed (if anything, higher risk makes reliance less appropriate).\n- The firm must still hold the CDD information."
 },
 {
  "t": "aml-framework-cdd",
  "q": "Sam instructs Pryor Solicitors to set up a family trust and transfer investment property into it. Despite repeated requests over three weeks, Sam refuses to provide any identification documents and will not say who will benefit from the trust. He asks the firm to proceed anyway.\n\nWhat is the best advice to the firm?",
  "o": [
   "Proceed, but note the file that CDD is outstanding and complete it within six months.",
   "Proceed, because CDD only needs to be completed before any money is received.",
   "Do not proceed with the transaction, terminate the relationship and consider whether to make a SAR.",
   "Proceed only if Sam signs a written indemnity against any money laundering liability.",
   "Report Sam to the SRA, because a client's refusal to provide ID is a breach of the SRA Code."
  ],
  "a": 2,
  "e": "The firm must **not proceed**, must **terminate** the relationship and must **consider making a SAR**.\n\nSetting up a trust and transferring property is within the **MLR 2017**. Under **reg 31**, where a firm **cannot apply CDD**, it must not carry out the transaction or establish the relationship, must terminate any existing relationship, and must consider whether a suspicious activity report is required. The refusal to identify himself or the beneficiaries is also a red flag.\n\n- There is no six-month grace period; verification must normally be done before the relationship is established.\n- CDD timing is not tied to the receipt of money.\n- An indemnity cannot exclude criminal or regulatory liability.\n- The SRA regulates solicitors, not clients."
 },
 {
  "t": "poca-offences-reporting",
  "q": "Lena, a solicitor at Hart LLP, acts for Paul on the purchase of a house. Paul tells her the £150,000 deposit will come from his building business, adding that he \"never puts most of the cash takings through the books\" so he pays little tax. Completion is due in ten days.\n\nWhat should Lena do?",
  "o": [
   "Report her suspicion promptly to the firm's MLRO and not proceed with the transaction until appropriate consent is obtained.",
   "Proceed, because a solicitor acting on a purchase is not entering into an arrangement.",
   "Tell Paul she must report the matter and invite him to regularise his tax affairs before completion.",
   "Proceed with completion, because tax evasion does not generate criminal property.",
   "Report the matter directly to HMRC, which will decide whether the transaction can proceed."
  ],
  "a": 0,
  "e": "Lena should report promptly to the **MLRO** and **not proceed** until consent (a **DAML**) is obtained.\n\nTax evasion is **criminal conduct**, so money representing the evaded tax is **criminal property** under **s.340 POCA**. By acting on a purchase funded by it, Lena would be **concerned in an arrangement** facilitating its use (**s.328**). Her defence is an **authorised disclosure** to the MLRO, who will make a SAR to the **NCA** and seek consent. She must also avoid **tipping off**.\n\n- Tax evasion does produce criminal property; any crime counts.\n- Transactional work is the classic **s.328** risk (Bowman v Fels exempts only litigation).\n- Telling Paul she is reporting him risks **tipping off** and **prejudicing an investigation**.\n- SARs go to the **NCA**, not HMRC."
 },
 {
  "t": "poca-offences-reporting",
  "q": "The MLRO at Quinn Solicitors makes a SAR to the NCA and requests a defence against money laundering (DAML) on a client's sale of a property. Seven working days pass, beginning with the first working day after the SAR, and the firm hears nothing from the NCA.\n\nWhich of the following best describes the firm's position?",
  "o": [
   "The firm must wait a further 31 days from the end of the notice period before proceeding.",
   "The firm must apply to the court for permission to proceed.",
   "The firm must not proceed until it receives express written consent from the NCA.",
   "The firm may proceed, because consent is deemed given when the notice period ends.",
   "The firm must ask the client for an indemnity before proceeding."
  ],
  "a": 3,
  "e": "The firm **may proceed**: consent is **deemed** once the notice period expires without refusal.\n\nUnder **s.335 POCA**, after an authorised disclosure requesting consent, the NCA has a **notice period of 7 working days**. If it does not refuse within that period, the person is treated as having **appropriate consent** and has a defence to the principal offences.\n\n- The **31-day moratorium** applies only if consent is **refused** within the notice period.\n- Express consent is not required: silence for 7 working days is enough.\n- No court application is needed (the court is involved only in extending a moratorium, by up to 186 days in total beyond the initial 31 days).\n- An indemnity is irrelevant to criminal liability."
 },
 {
  "t": "poca-offences-reporting",
  "q": "The completion of a sale has been delayed while Vale Solicitors awaits consent from the NCA following a SAR. The client, Yusuf, telephones his solicitor, Kim, demanding to know why the money has not been sent.\n\nWhat is the best way for Kim to respond?",
  "o": [
   "Explain that a report has been made to the NCA but reassure Yusuf it is routine.",
   "Give a neutral reason for the delay without lying or revealing the SAR, and consult the MLRO.",
   "Transfer the money, because the client's instructions must be followed promptly.",
   "Tell Yusuf the firm suspects his funds are criminal, to give him the chance to explain.",
   "Tell Yusuf the firm can no longer act for him, and give him the NCA's reference so he can follow up."
  ],
  "a": 1,
  "e": "Kim should **avoid revealing the SAR or any investigation**, giving a neutral response without positive lies, and consult the **MLRO**.\n\nUnder **s.333A POCA**, it is an offence in the regulated sector to disclose that a **SAR has been made** where this is likely to prejudice any investigation (**tipping off**). Disclosing a suspicion could also amount to **prejudicing an investigation** (**s.342**). Kim must also not mislead (Code para **1.4**), so she should be careful in wording; the MLRO and NCA guidance help with what can be said.\n\n- Saying a report has been made, even as routine, is tipping off.\n- Telling Yusuf of the suspicion risks prejudicing an investigation.\n- Transferring the money without consent would expose the firm to a **s.328** offence.\n- Giving the NCA reference reveals the SAR."
 },
 {
  "t": "poca-offences-reporting",
  "q": "Fenella consults Ruth, a solicitor, for advice on her liability after admitting that she failed to declare rental income to HMRC over several years. She wants to know her position and how to put things right. Ruth's firm is in the regulated sector.\n\nWhich of the following best describes Ruth's obligation?",
  "o": [
   "Ruth must report to the MLRO, because she knows Fenella has committed tax evasion.",
   "Ruth must report directly to HMRC rather than to the NCA, because the underlying offence is a tax offence.",
   "Ruth must report, because the privilege defence applies only to litigation.",
   "Ruth must refuse to advise Fenella, because advising a tax evader is a principal money laundering offence.",
   "Ruth need not disclose, because the information came to her in privileged circumstances."
  ],
  "a": 4,
  "e": "Ruth **need not disclose**: the **privileged circumstances** defence applies.\n\nUnder **s.330(6)(b) and (10) POCA**, a professional legal adviser does not commit the **failure to disclose** offence where the information came to them in **privileged circumstances**, that is from a client in connection with the giving of **legal advice** (or in connection with legal proceedings), unless it was communicated with the intention of **furthering a criminal purpose**. Fenella seeks advice on regularising her position, not help to continue the evasion.\n\n- Knowledge alone does not trigger the duty where the privilege defence applies.\n- SARs go to the NCA, not HMRC.\n- Advising on her past conduct is not itself a principal offence, as long as Ruth does not facilitate dealing with criminal property.\n- The privilege defence covers **legal advice**, not just litigation."
 },
 {
  "t": "poca-offences-reporting",
  "q": "Ola, a trainee at a conveyancing firm, notices that a client is buying a series of properties in cash through different companies with no obvious business purpose. A reasonable conveyancer would have been suspicious, but Ola did not actually suspect anything and did not report it. The firm had given her full AML training.\n\nWhich of the following best describes Ola's position?",
  "o": [
   "Ola commits no offence, because she did not personally suspect money laundering.",
   "Ola commits the tipping off offence, because failing to report alerts the client that nothing is being done.",
   "Ola may have committed the s.330 offence, because the test is partly objective.",
   "Ola commits no offence, because only the MLRO can commit offences of failing to report.",
   "Ola commits the s.328 offence, because failing to report is itself an arrangement."
  ],
  "a": 2,
  "e": "Ola may have committed the **s.330 failure to disclose** offence.\n\n**s.330 POCA** applies in the **regulated sector** where a person **knows, suspects, or has reasonable grounds for knowing or suspecting** money laundering and does not disclose to the MLRO or NCA as soon as practicable. The **reasonable grounds** limb is **objective**: if a reasonable person in her position would have suspected, she can be liable even without actual suspicion.\n\nThe defence for employees who were **not trained** does not help her, because she received training.\n\n- Lack of actual suspicion is not a defence under the objective limb.\n- Tipping off involves disclosing that a report has been made.\n- The MLRO has a separate offence (s.331), but employees are liable under s.330.\n- Failing to report is not an arrangement under s.328."
 },
 {
  "t": "financial-services",
  "q": "Gwen is the executor of her late father's estate, which includes a portfolio of shares. She instructs Tolley Solicitors, an SRA-regulated firm that is not FCA-authorised, and asks the solicitor to recommend which particular shares she should sell first and which to keep as long-term investments.\n\nWhich of the following best describes the firm's position?",
  "o": [
   "This is advising on investments, so the firm needs an exclusion or the Part 20 exemption.",
   "The firm may give the advice, because advice to an executor is never a regulated activity.",
   "The firm may give the advice only if it charges a separate fee for it and records that fee on the bill.",
   "The firm may give the advice freely, because shares in an estate are not specified investments.",
   "The firm must refuse to deal with the shares at all and pass the estate to a stockbroker."
  ],
  "a": 0,
  "e": "The best answer is that this is **advising on investments**, so the firm must find an **exclusion** or rely on the **Part 20 exemption**.\n\nShares are a **specified investment** under the RAO, and advising on the **merits** of buying or selling **particular** investments is a **specified activity**. Gwen receives the advice as an investor (executor), so it is potentially regulated. The firm must then consider exclusions (e.g. art 66 trustees/PRs applies to the PR herself, not the solicitor; art 67 necessary part of other services) and, failing those, the **Part 20** regime: the activity must be **incidental** to the probate work, any commission accounted for, and permitted by the SRA Scope Rules.\n\n- Shares are specified investments wherever held.\n- Advice to an executor can be regulated.\n- Charging a separate fee makes exclusions **less** likely to apply.\n- The firm may deal with the shares, typically through an authorised stockbroker."
 },
 {
  "t": "financial-services",
  "q": "Hugo, a solicitor at Pell Solicitors (not FCA-authorised), acts for Mrs Banerjee on her divorce. She asks Hugo which personal pension plan she should put her lump sum settlement into. Hugo has some knowledge of pensions.\n\nWhat is the best course of action for Hugo?",
  "o": [
   "Recommend a suitable pension, because the advice is incidental to the divorce work.",
   "Recommend a pension provided he discloses that the firm is not FCA-authorised.",
   "Recommend a pension, because pensions are not specified investments under the RAO.",
   "Introduce her to an FCA-authorised independent financial adviser.",
   "Recommend a pension, provided the firm does not charge for the advice."
  ],
  "a": 3,
  "e": "Hugo should **introduce her to an authorised IFA**.\n\nPersonal pensions are **long-term insurance** or collective investments and are **specified investments**; recommending one is **advising on investments**. The **SRA Financial Services (Scope) Rules** prohibit exempt firms from **recommending** that a client buy a **retail investment product** or a personal pension (and from advising on pension transfers) other than through an authorised person. **Introducing** a client to an **authorised person** for advice is an **excluded** activity (art 33), provided any reward is accounted for to the client.\n\n- Even incidental advice is caught by the Scope Rules' prohibition.\n- A status disclosure does not make prohibited advice lawful.\n- Pensions are specified investments.\n- Not charging does not take it outside the regime."
 },
 {
  "t": "financial-services",
  "q": "Ivan and Jo each own 50% of the shares in Sedge Ltd. They have agreed to sell all their shares to Bramble plc. Aldous Solicitors, which is not FCA-authorised, will advise Ivan and Jo on the sale terms, negotiate the share purchase agreement and arrange completion.\n\nWhich of the following best describes the regulatory position of the firm's work?",
  "o": [
   "The firm must be FCA-authorised, because shares are specified investments under the RAO.",
   "The work is excluded from regulation as the sale of a body corporate.",
   "The firm must rely on the Part 20 exemption, because no exclusion can apply to share sales.",
   "The work is not regulated because shares in private companies are not specified investments.",
   "The work is regulated, so the buyer must appoint an authorised firm instead."
  ],
  "a": 1,
  "e": "The work falls within the **sale of a body corporate** exclusion (**art 70 RAO**).\n\nShares are **specified investments**, and arranging and advising on their sale would be specified activities. But art 70 excludes dealing, arranging and advising in connection with a transaction to acquire or dispose of shares carrying **50% or more** of the voting rights in a body corporate, between parties who are individuals or companies (broadly, not acting as trustees for investors). Here 100% is being sold to a company.\n\n- Authorisation is not needed if an exclusion applies.\n- Part 20 need only be considered if no exclusion applies.\n- Private company shares are still specified investments.\n- The buyer's arrangements have no bearing on whether the seller's solicitor needs authorisation."
 },
 {
  "t": "funding-private-cfa-dba",
  "q": "Olu was injured in a road traffic accident. He agrees a conditional fee agreement with Mark & Co. The CFA provides for a 100% success fee. Olu recovers damages of £40,000 for pain, suffering and loss of amenity and £10,000 for past loss of earnings (no CRU deduction applies) and £30,000 for future losses. His base costs are £30,000.\n\nWhat is the maximum success fee Olu can be required to pay Mark & Co?",
  "o": [
   "£30,000, being 100% of base costs.",
   "£20,000, being 25% of the total damages.",
   "Nothing, because success fees are recoverable from the defendant.",
   "£10,000, being 25% of general damages only.",
   "£12,500, being 25% of the damages for PSLA and past losses."
  ],
  "a": 4,
  "e": "The maximum success fee is **£12,500**.\n\nIn **personal injury** claims at first instance, the success fee payable by the client under a CFA is capped at **25%** of damages for **pain, suffering and loss of amenity** and **past pecuniary loss** (net of CRU). **Future losses** are excluded. Here: 25% x (£40,000 + £10,000) = £12,500. The contractual 100% success fee (£30,000) is limited by this cap.\n\n- 100% of base costs is the general cap but the PI cap is lower here.\n- 25% of total damages wrongly includes future losses.\n- £10,000 wrongly excludes past pecuniary loss.\n- Since **April 2013** success fees are **not recoverable** from the losing defendant; the client pays."
 },
 {
  "t": "funding-private-cfa-dba",
  "q": "Bella wants to bring an unfair dismissal claim in the employment tribunal. She cannot afford hourly rates and has no legal expenses insurance. Her solicitor proposes a damages-based agreement.\n\nWhat is the maximum percentage of her recovered sums that the DBA can provide for the solicitor to receive, including VAT?",
  "o": [
   "25%",
   "40%",
   "35%",
   "50%",
   "100%"
  ],
  "a": 2,
  "e": "The maximum is **35%**.\n\nUnder the **Damages-Based Agreements Regulations 2013**, the payment a lawyer can take under a DBA is capped (inclusive of **VAT** and counsel's fees) at:\n- **25%** in **personal injury** claims (of damages for PSLA and past losses);\n- **35%** in **employment tribunal** matters;\n- **50%** in **all other** civil claims.\n\n- 25% is the personal injury cap.\n- 50% is the cap for other civil claims.\n- 40% is not a statutory cap for DBAs.\n- 100% is the cap on a CFA success fee as a percentage of base costs, a different concept."
 },
 {
  "t": "funding-private-cfa-dba",
  "q": "Rhys brings a breach of contract claim against a supplier under a damages-based agreement providing for his solicitor to receive 30% of sums recovered. He is awarded £200,000 and the court orders the supplier to pay £45,000 towards his costs.\n\nHow much of his damages must Rhys pay his solicitor?",
  "o": [
   "£15,000.",
   "£45,000.",
   "£60,000.",
   "£105,000.",
   "Nothing, because the costs order exceeds the DBA payment."
  ],
  "a": 0,
  "e": "The DBA payment is **30% of £200,000 = £60,000**, within the **50%** cap for ordinary civil claims. The **costs recovered** from the opponent (£45,000) are **set off** against that payment, so Rhys pays only the **balance** of £15,000 out of his damages. Adding the costs to the percentage would charge him twice."
 },
 {
  "t": "funding-legal-aid-tpf-lei",
  "q": "Mrs Okafor, a 55-year-old, believes surgery on her knee was negligently performed. She cannot afford to fund the claim privately. She asks her solicitor how her claim might be funded.\n\nWhat is the best advice?",
  "o": [
   "She should apply for civil legal aid, which is available for all clinical negligence claims.",
   "She must fund privately because CFAs are not permitted in clinical negligence.",
   "She should enter a third-party funding agreement giving the funder 30% of damages, which is enforceable under current law.",
   "She should check whether she has BTE insurance, and otherwise consider a CFA with ATE insurance.",
   "She should enter a DBA under which the solicitor receives 50% of all damages."
  ],
  "a": 3,
  "e": "The best advice is to **check for BTE insurance**, and otherwise consider a **CFA with ATE insurance**.\n\nSince **LASPO 2012**, civil legal aid for clinical negligence is limited to **infants** with **neurological injury** at birth, so an adult claim is **out of scope**. A **CFA** is the usual funding route, with **ATE** to cover adverse costs and disbursements (in PI, **QOCS** gives protection against adverse costs, but ATE still covers disbursements such as expert fees). BTE should always be checked first.\n\n- Legal aid is not available for this claim.\n- A funding agreement taking a **percentage of damages** is a **DBA** after **PACCAR** and is unenforceable unless it complies with the DBA Regulations.\n- CFAs are permitted in clinical negligence.\n- A DBA in personal injury is capped at **25%** of PSLA and past losses, not 50%."
 },
 {
  "t": "funding-legal-aid-tpf-lei",
  "q": "Torrent Ltd wishes to bring a large competition damages claim. A litigation funder offers to fund the claim in return for 30% of any damages recovered. The agreement does not comply with the Damages-Based Agreements Regulations 2013. The agreement is signed in October 2026.\n\nWhich of the following best describes the enforceability of the funding agreement?",
  "o": [
   "It is enforceable, because Parliament reversed the PACCAR decision by legislation in 2024.",
   "It is unenforceable, because it is a DBA that does not comply with the regulations.",
   "It is enforceable, provided the funder is a member of the Association of Litigation Funders.",
   "It is unenforceable, because funding agreements are void as champertous in all cases.",
   "It is enforceable, because litigation funders are not lawyers and so cannot be party to a DBA."
  ],
  "a": 1,
  "e": "The agreement is **unenforceable**.\n\nIn **R (PACCAR) v Competition Appeal Tribunal [2023] UKSC 28** the Supreme Court held that a litigation funding agreement under which the funder's return is calculated as a **percentage of damages** is a **damages-based agreement** under **s.58AA CLSA 1990**. A DBA that does not comply with the **2013 Regulations** is unenforceable.\n\nThe Litigation Funding Agreements (Enforceability) Bill fell in **May 2024**. Although the government said in December 2025 it would legislate, there was no legislation in force by September 2026.\n\n- Parliament has **not** reversed PACCAR.\n- PACCAR applies to funders even though they are not lawyers.\n- ALF membership does not affect statutory enforceability.\n- Funding agreements are not automatically champertous; agreements based on a **multiple** of investment can be enforceable."
 },
 {
  "t": "funding-legal-aid-tpf-lei",
  "q": "Kerry is injured when she slips in a supermarket. She asks her solicitor about funding a claim against the supermarket. She mentions she has home insurance with a legal expenses add-on and that the insurer wants her to use its panel firm.\n\nWhich of the following is the best advice?",
  "o": [
   "The insurer can insist on its panel firm for the whole claim, including after proceedings are issued, as a condition of cover.",
   "BTE cover is irrelevant to personal injury claims and she should use a CFA.",
   "She should apply for legal aid, because BTE insurance makes her eligible for legal aid.",
   "She must take out ATE insurance before her BTE insurer will agree to fund any part of the claim.",
   "She should check whether her BTE policy covers the claim, and note her right to choose a lawyer once proceedings are issued."
  ],
  "a": 4,
  "e": "The best advice is to **check her BTE cover** and note her **freedom to choose** a lawyer once proceedings are issued.\n\nA solicitor must discuss funding and check for existing **BTE** cover (often a home or motor insurance add-on). Under the **Insurance Companies (Legal Expenses Insurance) Regulations 1990**, the insured has the right to **choose their own lawyer** at least once **proceedings** are commenced (or where there is a conflict of interest). Before then, the insurer may require the use of its panel.\n\n- The insurer cannot insist on its panel firm once proceedings are issued.\n- BTE often covers personal injury claims.\n- ATE is not a precondition to BTE.\n- Most personal injury claims are out of scope for legal aid."
 },
 {
  "t": "transparency-client-care",
  "q": "Alder Solicitors offers residential conveyancing, wills and commercial lease work to the public. Its website gives an hourly rate and a contact form but no other information about its conveyancing charges.\n\nWhich of the following best describes the firm's position under the SRA Transparency Rules?",
  "o": [
   "It complies, because it publishes an hourly rate.",
   "It must publish full price information for all of its services, including its commercial lease work and wills.",
   "It must publish price information for conveyancing, including disbursements, timescales and staff experience.",
   "It need not publish any price information because it is a small firm.",
   "It need only publish price information for conveyancing if a prospective client asks to see it."
  ],
  "a": 2,
  "e": "The firm must publish **full price information** for **residential conveyancing**.\n\nThe **SRA Transparency Rules** require firms to publish costs information on their website for specified services, including **residential conveyancing** for individuals. It must include the **total cost** (or an average or range), the **basis** of charges, likely **disbursements**, **VAT**, what is included, the **key stages**, **timescales**, and the **experience and qualifications** of those doing the work.\n\n- An hourly rate alone is not enough.\n- **Wills** and **commercial leases** are not on the list of specified services.\n- There is no small-firm exemption (only a no-website exception, where the information must be available on request).\n- Information must be published proactively, not just on request."
 },
 {
  "t": "transparency-client-care",
  "q": "Helen telephones Brook Solicitors and instructs them to deal with her lease extension. She has never visited the office. The solicitor agrees terms by email and starts work the next morning, but does not tell Helen about any right to cancel. Ten days later Helen says she no longer wants to go ahead.\n\nWhich of the following best describes the position?",
  "o": [
   "Helen can cancel and may not have to pay for the work done.",
   "Helen cannot cancel, because the contract was agreed in writing by email before work began.",
   "Helen can cancel but must pay for all work done, because the firm acted on her instructions.",
   "Helen cannot cancel, because the right to cancel applies only to goods, not services.",
   "Helen can cancel only if the firm agrees, because legal services are excluded from consumer protection."
  ],
  "a": 0,
  "e": "A contract with a consumer made **at a distance** falls under the **Consumer Contracts Regulations 2013**. The firm should have given **pre-contract information** and told Helen of her right to **cancel within 14 days**, and obtained her **express request** to start work in that period. Without that, she can cancel and may pay nothing for the work done, and the cancellation period is extended by up to **12 months**."
 },
 {
  "t": "transparency-client-care",
  "q": "Oak & Co is a small firm doing only commercial property work for businesses. Its website gives its SRA number and logo but no other information about complaints or prices. A business client starts a lease matter. The client care letter sets out costs and scope, but says the firm will explain complaints options only if a complaint arises.\n\nWhich of the following best describes the firm's position?",
  "o": [
   "It complies, because commercial property is not a service for which information must be published.",
   "It breaches the Transparency Rules only by failing to publish prices for commercial property work.",
   "It complies, because complaints information need only be given to individual consumers.",
   "It breaches the rules on publishing and giving complaints information.",
   "It breaches the rules only if the client later complains and is not told about the Legal Ombudsman."
  ],
  "a": 3,
  "e": "Price information is needed only for **listed services**, and commercial property is not one, so no prices need be published. But **every** firm must publish its **complaints procedure**, and **Code para 8.3** requires clients to be told **in writing at the time of engagement** about their right to complain and any right to go to the **Legal Ombudsman**. Waiting until a complaint arises is too late."
 }
];

;
window.SQE_QUICK = window.SQE_QUICK || {};
window.SQE_QUICK["contract"] = [
  {t:"offer-acceptance", q:"A shop displays a handbag priced at £50 on a shelf. A customer takes it to the till, but the cashier refuses to sell it. Was a contract formed when the customer picked it up?", o:["No: the display is an invitation to treat","Yes: the display was an offer accepted by picking it up","Yes: a price tag is a binding unilateral offer","No: shop sales need a written contract"], e:"**Goods on display are an invitation to treat**: the customer makes the offer at the till, which the shop may refuse (Boots)."},
  {t:"offer-acceptance", q:"The seller offers to sell a horse for £1,000. The buyer replies 'I'll pay £900.' The seller refuses, so the buyer says 'I accept £1,000.' Is there a contract?", o:["No: the counter-offer destroyed the original offer","Yes: the buyer accepted before the offer was revoked","Yes: the original offer stays open for a reasonable time","No: acceptance of an offer must be in writing"], e:"A **counter-offer rejects and destroys** the original offer; a mere request for information would not (Hyde v Wrench)."},
  {t:"offer-acceptance", q:"When does a posted letter of acceptance usually take effect?", o:["When properly posted","When received by the offeror","When opened by the offeror","When the offeror reads it"], e:"**Adams v Lindsell**: the postal rule makes acceptance effective on **posting**, if use of the post is reasonable."},
  {t:"offer-acceptance", q:"When is a postal revocation of an offer effective?", o:["On receipt by the offeree","On posting by the offeror","On the offeror signing it","After a reasonable time"], e:"**Byrne v Van Tienhoven**: revocation must be **communicated**; the postal rule does not apply to revocation."},
  {t:"offer-acceptance", q:"A writes to B: 'If I hear no more, I shall consider the horse mine at £30.' B never replies. Is there a contract?", o:["No: silence cannot amount to acceptance","Yes: A waived communication of acceptance","Yes: silence is acceptance if the offeror says so","Yes: B had a reasonable time to reject"], e:"**Silence is not acceptance**, even where the offeror says it will be (Felthouse v Bindley)."},

  {t:"consideration", q:"A agrees to sell his car to B in return for a peppercorn. Is there valid consideration?", o:["Yes: consideration must be sufficient, not adequate","No: consideration must be of roughly equal value","No: a token is only past consideration","Only if the contract is made by deed"], e:"Consideration must be **sufficient but need not be adequate**; the court does not weigh the bargain (Chappell v Nestle: chocolate wrappers)."},
  {t:"consideration", q:"A builder running late is promised an extra £10,000 to finish on time, with no threats made. The client avoids a penalty under its own head contract. Is the promise binding?", o:["Yes: the practical benefit is good consideration","No: performing an existing duty is never consideration","No: the builder gave nothing new in return","Only if the promise was made by deed"], e:"A **practical benefit**, obtained without duress or fraud, is good consideration for a promise to **pay more** (Williams v Roffey)."},
  {t:"consideration", q:"A creditor agrees to accept £5,000 in full settlement of a £10,000 debt now due. The debtor argues the creditor gained the practical benefit of prompt payment. Can the creditor sue for the balance?", o:["Yes: practical benefit does not apply to part payment of a debt","No: practical benefit is good consideration","No: an agreement to accept less always binds","Only if the creditor objected within 6 months"], e:"Part payment of a debt is not consideration (**Foakes v Beer**); **practical benefit does not extend** to promises to accept less (Re Selectmove)."},
  {t:"consideration", q:"A man promises his ex-wife £100 a week maintenance; she gives nothing in return but relies on it. When he stops paying, can she sue him relying on promissory estoppel?", o:["No: promissory estoppel is a shield, not a sword","Yes: her reliance makes the promise enforceable","Yes: estoppel creates a new cause of action","Yes: estoppel replaces consideration in all contracts"], e:"**Promissory estoppel cannot create a cause of action**; it only stops a promisor going back on strict rights (Combe v Combe)."},

  {t:"intention-certainty-capacity", q:"A husband, living happily with his wife, promises her a monthly allowance. Is the promise presumed to be legally binding?", o:["No: domestic agreements are presumed not binding","Yes: all promises between spouses are binding","Yes: the commercial presumption applies to money","No: spouses lack capacity to contract together"], e:"**Domestic and social agreements are presumed not to be intended as binding** (Balfour); the presumption is rebutted where spouses are separating (Merritt)."},
  {t:"intention-certainty-capacity", q:"Two parties agree to 'negotiate in good faith' for the sale of a business, with no time limit. Is the agreement enforceable?", o:["No: an agreement to negotiate is too uncertain","Yes: the good faith duty makes it certain","Yes: it is an enforceable lock-out agreement","Only if the buyer has paid for the promise"], e:"An **agreement to negotiate in good faith is unenforceable** for uncertainty; a lock-out for a **fixed period** can be enforceable (Walford v Miles)."},
  {t:"intention-certainty-capacity", q:"A contract to buy a van 'on hire purchase terms' does not say what those terms are, and no trade custom or previous dealing fills the gap. Is there a binding contract?", o:["No: the term is too vague, so there is no contract","Yes: the court will imply reasonable terms","Yes: a reasonable price will be implied","Yes: the SGA 1979 supplies the missing terms"], e:"Where an **essential term is too vague** and cannot be made certain, there is **no contract** (Scammell v Ouston)."},
  {t:"intention-certainty-capacity", q:"What must a minor pay for necessaries under s.3 SGA 1979?", o:["A reasonable price","The contract price","Nothing at all","Cost price only"], e:"**s.3 SGA 1979** (Nash v Inman): a **reasonable price** for necessaries suitable to their condition and needs."},

  {t:"privity-third-parties", q:"Under s.1(3) of the 1999 Act, how must a third party be identified?", o:["By name, class or description","By name only","By signature on the contract","By separate written notice"], e:"**s.1(3)**: name, class or description in the contract; they need not exist when it is made."},
  {t:"privity-third-parties", q:"When does a third party's communicated assent under s.2 of the 1999 Act take effect?", o:["On receipt by the promisor","On posting","On signing the contract","On performance"], e:"**s.2**: assent must be communicated to the promisor; the **postal rule does not apply**."},
  {t:"privity-third-parties", q:"What does s.136 LPA 1925 require for a legal assignment of contractual rights?", o:["Absolute, signed writing, written notice to debtor","Deed and consent of the debtor","Oral agreement and notice to debtor","Writing signed by the debtor"], e:"**s.136 LPA 1925**: absolute, in writing signed by the assignor, with **written notice** to the debtor."},
  {t:"privity-third-parties", q:"A manufacturer sells tyres to a wholesaler, who resells them to a retailer under a contract in which the retailer promises not to sell below list price. The retailer undercuts. Ignoring the 1999 Act, can the manufacturer sue the retailer?", o:["No: it is not a party to that contract","Yes: it is the intended beneficiary","Yes: it supplied the goods originally","Yes, but only for nominal damages"], e:"**Privity**: only a party to a contract can enforce it (Dunlop v Selfridge); the 1999 Act is the main statutory exception."},

  {t:"express-terms", q:"A guest books a hotel room at reception. A notice in the bedroom excludes liability for stolen property. Is the exclusion incorporated?", o:["No: the notice came after the contract was made","Yes: it was clearly displayed in the room","Yes: guests are bound by hotel rules","Yes: the guest stayed after seeing it"], e:"Terms must be notified **before or at the time of contracting**; later notice is too late (Olley v Marlborough Court)."},
  {t:"express-terms", q:"A term is not classified as a condition or a warranty. Its breach is serious but does not deprive the innocent party of substantially the whole benefit. What remedy is available?", o:["Damages only","Termination and damages","Termination only","Rescission from the start"], e:"For an **innominate term**, termination is available only if the breach deprives the innocent party of **substantially the whole benefit**; otherwise damages only (Hong Kong Fir)."},
  {t:"express-terms", q:"A contract says variations must be in signed writing. The parties later agree a variation orally. Is the variation effective?", o:["No: the no oral modification clause is valid","Yes: parties can always vary orally","Yes: the later agreement overrides the clause","Only if the variation benefits both parties"], e:"A **no oral modification clause is effective**; an oral variation fails unless the clause's formalities are met (Rock Advertising v MWB)."},
  {t:"express-terms", q:"An unsigned delivery note contains an unusual and very onerous term in small print. What is needed for that term to be incorporated?", o:["Especially prominent notice drawing attention to it","Ordinary reasonable notice, as for any term","Nothing: delivery notes are always contractual","Court approval of the term as reasonable"], e:"The more **onerous or unusual** a term, the **more notice** is needed: the 'red hand' rule (J Spurling v Bradshaw; Interfoto)."},

  {t:"implied-terms", q:"A jetty owner contracts to let a ship moor at its jetty, but the contract is silent on whether the berth is safe. Will a term be implied that the owner takes reasonable care over the berth's safety?", o:["Yes: it is necessary to give the contract business efficacy","No: courts never imply terms the parties did not write","No: terms can only be implied by statute","Yes: because it would be fair and reasonable"], e:"A term is implied in fact if **necessary for business efficacy** (The Moorcock) or so obvious it goes without saying; mere reasonableness is not enough."},
  {t:"implied-terms", q:"Which SGA 1979 section implies that goods are of satisfactory quality?", o:["s.14(2)","s.13","s.14(3)","s.12"], e:"**s.14(2)**, where the seller sells in the course of a business. s.13 is description, s.14(3) fitness, s.12 title."},
  {t:"implied-terms", q:"How long is the consumer's short-term right to reject goods under the CRA 2015?", o:["30 days","14 days","6 months","28 days"], e:"**CRA 2015 s.22**: 30 days from delivery, with a full refund."},
  {t:"implied-terms", q:"Which CRA 2015 section requires a trader to perform a service with reasonable care and skill?", o:["s.49","s.9","s.51","s.55"], e:"**s.49**. s.51 is reasonable price; s.55 is repeat performance; s.9 is satisfactory quality of goods."},

  {t:"exemption-clauses", q:"Under UCTA 1977 s.2(1), what is the effect of excluding liability for negligently caused death?", o:["Void","Subject to reasonableness","Valid if incorporated","Valid between businesses only"], e:"**UCTA s.2(1)**: liability for death or personal injury from negligence cannot be excluded."},
  {t:"exemption-clauses", q:"Under UCTA s.11, when is the reasonableness of a term judged?", o:["When the contract was made","When the breach occurred","When the claim is issued","At trial"], e:"**s.11(1)**: judged at the time of contracting, and the burden is on the party relying on the clause."},
  {t:"exemption-clauses", q:"Which CRA 2015 section contains the fairness test for consumer contract terms?", o:["s.62","s.65","s.31","s.71"], e:"**s.62**: unfair if, contrary to good faith, it causes a significant imbalance to the consumer's detriment."},
  {t:"exemption-clauses", q:"An ambiguous clause limits (rather than wholly excludes) liability to £1,000. How strictly will contra proferentem be applied to it?", o:["Less strictly than to a total exclusion clause","More strictly than to a total exclusion clause","Exactly as strictly as to any exclusion clause","Not at all: limitation clauses are always valid"], e:"**Limitation clauses** are construed **less strictly** than total exclusion clauses (Ailsa Craig)."},

  {t:"misrepresentation", q:"A seller of farmland never used for sheep honestly tells the buyer it could carry 2,000 sheep. It cannot. Is this an actionable misrepresentation?", o:["No: it is an honest opinion, not a statement of fact","Yes: any false statement inducing a contract is actionable","Yes: the seller should have checked the capacity","No: statements about land are never actionable"], e:"An honest **opinion** by someone with **no special knowledge** is not a statement of fact (Bisset v Wilkinson); an expert's opinion may be (Esso v Mardon)."},
  {t:"misrepresentation", q:"A claimant proves a negligent misrepresentation under s.2(1) Misrepresentation Act 1967. How are damages assessed?", o:["As for fraud: all direct loss, even if unforeseeable","As for breach of contract: expectation loss","As for negligence: foreseeable loss only","At the court's discretion in lieu of rescission"], e:"The **fiction of fraud** in s.2(1) means the **deceit measure** applies: all direct loss (Royscot Trust v Rogerson). Discretionary damages in lieu are s.2(2)."},
  {t:"misrepresentation", q:"A seller of a medical practice truthfully states its income in January. By signing in May, income has collapsed, but the seller says nothing. Is there a misrepresentation?", o:["Yes: a statement that becomes false must be corrected","No: the statement was true when made","No: silence is never a misrepresentation","Only if the buyer asked again before signing"], e:"A statement **true when made but falsified by a change of circumstances** before the contract must be corrected (With v O'Flanagan)."},
  {t:"misrepresentation", q:"Five years after buying a painting, a buyer discovers the seller's innocent statement that it was by Constable was false. Can the buyer rescind?", o:["No: lapse of time bars rescission","Yes: time runs only from discovery","Yes: innocent misrepresentation never bars rescission","Yes, if the painting is returned undamaged"], e:"For non-fraudulent misrepresentation, **lapse of time** runs from the **contract**, not discovery; five years was too long (Leaf v International Galleries)."},

  {t:"mistake-duress-ui-illegality", q:"What is the effect on a contract of an operative mistake?", o:["Void","Voidable","Valid but unenforceable","Discharged by frustration"], e:"Mistake makes a contract **void**, so third parties get no title. Duress and undue influence make it voidable."},
  {t:"mistake-duress-ui-illegality", q:"A rogue signs a written hire purchase agreement in the name of a real person whose identity he has stolen. What is the effect on the written agreement?", o:["Void: the hirer is the person named in it","Voidable for fraud until rescinded","Valid: the finance company dealt with the rogue","Valid but unenforceable against the rogue"], e:"In a **written contract**, the other party is the **person named**, so the agreement with the rogue is **void** (Shogun Finance); face-to-face deals are presumed voidable only (Lewis v Averay)."},
  {t:"mistake-duress-ui-illegality", q:"A supplier, without lawful justification, threatens to stop deliveries unless the buyer agrees to a price rise. The buyer agrees. What must the buyer prove for economic duress?", o:["Illegitimate pressure that was a significant cause of agreeing","Any commercial pressure at all","That the threat was to commit a crime","That the contract was at an undervalue"], e:"Economic duress: **illegitimate pressure** that was a **significant cause** of entering the contract, leaving no practical choice (DSND Subsea)."},
  {t:"mistake-duress-ui-illegality", q:"A wife guarantees her husband's business debts to a bank. What must the bank normally do to avoid being affected by any undue influence by the husband?", o:["Ensure she receives independent legal advice","Nothing: guarantees are always enforceable","Ensure she signs before a magistrate","Lend no more than half the property's value"], e:"In a non-commercial surety case the bank is **put on inquiry** and must take reasonable steps, chiefly getting a **solicitor's confirmation** that she was advised (RBS v Etridge (No 2))."},

  {t:"discharge-frustration", q:"A decorator completes a £750 job, but the work has minor defects costing £55 to put right. What can the decorator recover?", o:["£695: the price less the cost of remedying defects","Nothing: performance must be exact","£750: minor defects are irrelevant","Only a reasonable sum on a quantum meruit"], e:"**Substantial performance**: the price less the cost of remedying defects (Hoenig v Isaacs); not where defects are serious (Bolton v Mahadeva)."},
  {t:"discharge-frustration", q:"A seller must ship goods from Sudan to Hamburg. The Suez Canal closes, so the voyage round the Cape is twice as long and much costlier. Is the contract frustrated?", o:["No: more onerous or costly performance is not frustration","Yes: the usual route is impossible","Yes: the costs have doubled","Yes: delay always frustrates a sale of goods"], e:"Frustration needs a **radically different** obligation; a **longer, costlier route** is not enough (Tsakiroglou)."},
  {t:"discharge-frustration", q:"A flat is hired for two days solely, as both parties know, to watch a royal procession. The procession is cancelled. Is the contract frustrated?", o:["Yes: the foundation of the contract has gone","No: the flat can still be used","No: cancellation was foreseeable","Only if the hirer has not yet paid"], e:"A contract is frustrated where the **common purpose** forming its **foundation** is destroyed (Krell v Henry); contrast Herne Bay, where some purpose remained."},
  {t:"discharge-frustration", q:"Under the 1943 Act, up to what limit can a payee keep money for expenses?", o:["Sums paid or payable before frustration","The full value of expenses","The value of any benefit conferred","Half the contract price"], e:"**s.1(2)**: expenses only up to sums paid or payable before the frustrating event."},

  {t:"damages", q:"A carrier delays delivery of a mill's broken crankshaft. It did not know the mill had no spare and would stand idle. Can the mill recover its lost profits?", o:["No: the loss was not within the parties' reasonable contemplation","Yes: all losses caused by breach are recoverable","Yes: lost profit is always a natural loss","Only if the carrier was negligent"], e:"**Remoteness**: loss must arise **naturally** or be within **both parties' contemplation** from special facts made known (Hadley v Baxendale)."},
  {t:"damages", q:"A builder makes a pool six inches shallower than agreed. It is safe and its value is unaffected, but rebuilding would cost £21,000. What will the court award?", o:["A modest sum for loss of amenity","The full £21,000 cost of cure","Nothing, as there is no loss of value","A refund of the whole contract price"], e:"Cost of cure is refused if **wholly disproportionate** to the benefit; a **loss of amenity** award may be made instead (Ruxley v Forsyth)."},
  {t:"damages", q:"A clause requires a party in breach to pay a fixed sum. When is it an unenforceable penalty?", o:["When the detriment is out of all proportion to the innocent party's legitimate interest","Whenever the sum exceeds the actual loss","Whenever the contract calls it a penalty","Whenever it is not a precise estimate of loss"], e:"Modern test: a secondary obligation imposing a **detriment out of all proportion** to any **legitimate interest** of the innocent party (Cavendish v Makdessi; ParkingEye)."},
  {t:"damages", q:"Who bears the burden of proving a failure to mitigate loss?", o:["The defendant","The claimant","The court","Both parties equally"], e:"The **defendant** must prove the claimant failed to take reasonable steps to mitigate."},

  {t:"equitable-remedies-guarantees", q:"A supermarket tenant covenants to keep trading but closes its store. Will the court order specific performance to keep it trading?", o:["No: it would require constant supervision","Yes: damages are inadequate for landlords","Yes: specific performance is available as of right","No: leases can never be specifically enforced"], e:"Courts will not order a business to be **carried on**, as it would need **constant supervision** (Co-operative Insurance v Argyll)."},
  {t:"equitable-remedies-guarantees", q:"Which statute requires a guarantee to be evidenced in signed writing?", o:["Statute of Frauds 1677 s.4","LP(MP)A 1989 s.2","Law of Property Act 1925 s.136","Sale of Goods Act 1979 s.52"], e:"**Statute of Frauds 1677 s.4**. An indemnity needs no writing."},
  {t:"equitable-remedies-guarantees", q:"A lender and borrower agree a substantial increase in the loan without the guarantor's consent. What is the effect on the guarantee?", o:["The guarantor is discharged","The guarantor remains liable in full","The guarantor becomes liable for the increase too","The guarantee becomes an indemnity"], e:"A **material variation** of the principal contract **without the guarantor's consent** discharges them, unless plainly insubstantial or beneficial (Holme v Brunskill)."},
  {t:"equitable-remedies-guarantees", q:"A claimant seeks an interim injunction before trial. What must it first show?", o:["A serious question to be tried","A strong prima facie case","That it will certainly win at trial","That loss has already been suffered"], e:"**Serious question to be tried**, then adequacy of damages and the **balance of convenience** (American Cyanamid)."}
];

;
window.SQE_TERMS = window.SQE_TERMS || {};
window.SQE_TERMS["contract"] = [
  {t:"offer-acceptance", w:"Invitation to treat", d:"An invitation to make an offer, such as goods displayed in a shop."},
  {t:"offer-acceptance", w:"Carlill v Carbolic Smoke Ball", d:"An advertisement can be a unilateral offer to the world, accepted by performance."},
  {t:"offer-acceptance", w:"Hyde v Wrench", d:"A counter-offer rejects the original offer, which cannot then be accepted."},
  {t:"offer-acceptance", w:"Postal rule", d:"Acceptance by post is complete when the letter is posted, if post is reasonable."},
  {t:"offer-acceptance", w:"Felthouse v Bindley", d:"Silence cannot amount to acceptance."},
  {t:"offer-acceptance", w:"Battle of the forms", d:"Where standard terms clash, the last shot fired usually wins."},
  {t:"offer-acceptance", w:"Entores v Miles Far East", d:"Instantaneous acceptance is effective when received by the offeror."},
  {t:"consideration", w:"Currie v Misa", d:"Consideration is some benefit to one party or detriment to the other."},
  {t:"consideration", w:"Past consideration", d:"Something done before the promise is not good consideration."},
  {t:"consideration", w:"Lampleigh v Brathwait", d:"Past act done at the promisor's request, expecting payment, can be consideration."},
  {t:"consideration", w:"Stilk v Myrick", d:"Performing an existing contractual duty owed to the promisor is not consideration."},
  {t:"consideration", w:"Williams v Roffey", d:"Practical benefit from performing an existing duty can support a promise to pay more."},
  {t:"consideration", w:"Foakes v Beer", d:"Paying part of a debt is no consideration for a promise to forgo the rest."},
  {t:"consideration", w:"Promissory estoppel", d:"Promise not to enforce strict rights binds if relied on and inequitable to go back."},
  {t:"intention-certainty-capacity", w:"Balfour v Balfour", d:"Domestic agreements between spouses are presumed not intended to be legally binding."},
  {t:"intention-certainty-capacity", w:"Edwards v Skyways", d:"Heavy burden to rebut presumption that commercial agreements are intended to bind."},
  {t:"intention-certainty-capacity", w:"Honour clause", d:"Clause stating an agreement is not legally binding, rebutting the commercial presumption."},
  {t:"intention-certainty-capacity", w:"Subject to contract", d:"Wording indicating parties do not intend to be bound until a formal contract."},
  {t:"intention-certainty-capacity", w:"Walford v Miles", d:"An agreement to negotiate in good faith is too uncertain to enforce."},
  {t:"intention-certainty-capacity", w:"May and Butcher v R", d:"An agreement to agree on a vital term such as price is not binding."},
  {t:"intention-certainty-capacity", w:"Necessaries", d:"Goods or services suitable to a minor's needs, which the minor must pay for."},
  {t:"privity-third-parties", w:"Privity of contract", d:"Only parties to a contract can enforce it or be bound by it."},
  {t:"privity-third-parties", w:"C(RTP)A 1999 s.1(1)", d:"Third party can enforce a term which expressly allows it or purports to benefit them."},
  {t:"privity-third-parties", w:"s.1(3) identification", d:"The third party must be expressly identified by name, class or description."},
  {t:"privity-third-parties", w:"s.2 variation", d:"Parties cannot vary or rescind once the third party has assented or relied."},
  {t:"privity-third-parties", w:"Shanklin Pier v Detel", d:"A collateral contract can let a non-party enforce a promise."},
  {t:"privity-third-parties", w:"Assignment", d:"Transfer of contractual rights (not burdens) to a third party."},
  {t:"express-terms", w:"Representation or term", d:"Distinguished by importance, special knowledge and timing of the statement."},
  {t:"express-terms", w:"L'Estrange v Graucob", d:"A party who signs a contract is bound by its terms, read or not."},
  {t:"express-terms", w:"Thornton v Shoe Lane Parking", d:"Notice of terms after the contract is made comes too late to incorporate them."},
  {t:"express-terms", w:"Interfoto v Stiletto", d:"Onerous or unusual terms need especially clear notice to be incorporated."},
  {t:"express-terms", w:"Parol evidence rule", d:"Extrinsic evidence cannot usually add to or vary a written contract."},
  {t:"express-terms", w:"Innominate term", d:"Term whose breach allows termination only if the consequences are serious."},
  {t:"implied-terms", w:"Business efficacy test", d:"Term implied if necessary to make the contract work (The Moorcock)."},
  {t:"implied-terms", w:"Officious bystander test", d:"Term implied if so obvious it goes without saying."},
  {t:"implied-terms", w:"M and S v BNP Paribas", d:"Terms are implied in fact only if necessary, not merely reasonable."},
  {t:"implied-terms", w:"s.14(2) SGA satisfactory quality", d:"Goods sold in the course of a business must be of satisfactory quality."},
  {t:"implied-terms", w:"s.13 SGA description", d:"Goods sold by description must match that description."},
  {t:"implied-terms", w:"Short-term right to reject", d:"CRA 2015 consumer right to reject faulty goods within 30 days for full refund."},
  {t:"implied-terms", w:"s.49 CRA 2015", d:"Trader must perform a service with reasonable care and skill."},
  {t:"exemption-clauses", w:"Contra proferentem", d:"Ambiguous terms are interpreted against the party relying on them."},
  {t:"exemption-clauses", w:"Canada Steamship rules", d:"Tests for whether an exclusion clause covers negligence liability."},
  {t:"exemption-clauses", w:"UCTA s.2(1)", d:"Business cannot exclude liability for negligently caused death or personal injury."},
  {t:"exemption-clauses", w:"UCTA s.11 reasonableness", d:"Clause must be fair and reasonable judged when the contract was made."},
  {t:"exemption-clauses", w:"Watford Electronics v Sanderson", d:"Courts reluctant to interfere with terms agreed between commercial parties of equal strength."},
  {t:"exemption-clauses", w:"CRA 2015 s.62 fairness", d:"Consumer term unfair if it causes significant imbalance contrary to good faith."},
  {t:"misrepresentation", w:"Bisset v Wilkinson", d:"An honest statement of opinion is not a misrepresentation."},
  {t:"misrepresentation", w:"Edgington v Fitzmaurice", d:"A false statement of intention is a misrepresentation of existing fact."},
  {t:"misrepresentation", w:"Dimmock v Hallett", d:"A half-truth can be a misrepresentation."},
  {t:"misrepresentation", w:"With v O'Flanagan", d:"Failing to correct a statement made untrue by changed circumstances is misrepresentation."},
  {t:"misrepresentation", w:"Derry v Peek", d:"Fraud means a false statement made knowingly, without belief, or recklessly."},
  {t:"misrepresentation", w:"s.2(1) Misrepresentation Act 1967", d:"Negligent misrepresentation: defendant must prove reasonable grounds for belief."},
  {t:"misrepresentation", w:"Rescission", d:"Remedy setting the contract aside, subject to bars such as affirmation and delay."},
  {t:"mistake-duress-ui-illegality", w:"Res extincta", d:"Common mistake where the subject matter no longer exists, making the contract void."},
  {t:"mistake-duress-ui-illegality", w:"Great Peace Shipping", d:"Common mistake must make performance essentially different from what was agreed."},
  {t:"mistake-duress-ui-illegality", w:"Shogun Finance v Hudson", d:"Mistaken identity in a written contract can make it void."},
  {t:"mistake-duress-ui-illegality", w:"Non est factum", d:"Plea that a signed document was radically different from what was believed."},
  {t:"mistake-duress-ui-illegality", w:"Economic duress", d:"Illegitimate pressure that significantly causes a party to enter a contract."},
  {t:"mistake-duress-ui-illegality", w:"RBS v Etridge (No 2)", d:"Steps a bank must take when a wife guarantees her husband's debts."},
  {t:"mistake-duress-ui-illegality", w:"Patel v Mirza", d:"Illegality defence assessed by policy factors and proportionality."},
  {t:"discharge-frustration", w:"Entire obligations rule", d:"Payment is due only on complete and exact performance (Cutter v Powell)."},
  {t:"discharge-frustration", w:"Substantial performance", d:"Near-complete performance allows payment minus the cost of defects (Hoenig v Isaacs)."},
  {t:"discharge-frustration", w:"Repudiatory breach", d:"Breach of condition or serious breach allowing the innocent party to terminate."},
  {t:"discharge-frustration", w:"Anticipatory breach", d:"Renunciation before performance is due; can sue at once (Hochster v De la Tour)."},
  {t:"discharge-frustration", w:"White and Carter v McGregor", d:"Innocent party may affirm and perform if it has a legitimate interest."},
  {t:"discharge-frustration", w:"Frustration", d:"Contract ends when an event makes performance impossible, illegal or radically different."},
  {t:"discharge-frustration", w:"Taylor v Caldwell", d:"Destruction of the subject matter frustrates the contract."},
  {t:"damages", w:"Robinson v Harman", d:"Expectation damages put the claimant where they would be if performed."},
  {t:"damages", w:"Ruxley Electronics v Forsyth", d:"Cost of cure refused where disproportionate; loss of amenity awarded instead."},
  {t:"damages", w:"Hadley v Baxendale", d:"Recoverable losses arise naturally or were in both parties' contemplation."},
  {t:"damages", w:"Victoria Laundry v Newman", d:"Unusual losses are recoverable only if the defendant knew of special circumstances."},
  {t:"damages", w:"Mitigation", d:"Claimant cannot recover loss that reasonable steps would have avoided."},
  {t:"damages", w:"Penalty clause", d:"Clause imposing a detriment out of proportion to a legitimate interest; unenforceable."},
  {t:"damages", w:"Jarvis v Swans Tours", d:"Mental distress damages recoverable where the contract's object is pleasure."},
  {t:"equitable-remedies-guarantees", w:"Specific performance", d:"Order to perform a contract where damages are inadequate, e.g. land."},
  {t:"equitable-remedies-guarantees", w:"Co-operative Insurance v Argyll", d:"No specific performance requiring constant supervision."},
  {t:"equitable-remedies-guarantees", w:"Lumley v Wagner", d:"Injunction can enforce a negative covenant in a personal service contract."},
  {t:"equitable-remedies-guarantees", w:"Clean hands", d:"Equitable relief is refused to a claimant who has acted unfairly."},
  {t:"equitable-remedies-guarantees", w:"AG v Blake", d:"Account of profits available in exceptional contract cases."},
  {t:"equitable-remedies-guarantees", w:"Guarantee", d:"Secondary promise to answer for another's debt; must be evidenced in writing."},
  {t:"equitable-remedies-guarantees", w:"Indemnity", d:"Primary obligation to cover loss, independent of another's liability."}
];

;
window.SQE_CARDS = window.SQE_CARDS || {};
window.SQE_CARDS["contract"] = [["What five ingredients does a contract need?","**Agreement** (offer and acceptance). **Consideration**. **Intention** to create legal relations. **Certainty**. **Capacity**.","offer-acceptance"],
["How does the court decide whether there was agreement?","**Objectively**. What a **reasonable person** would understand from words and conduct. Not what each party secretly thought.","offer-acceptance"],
["Which contracts need formalities?","**Sale of land**: in writing signed by both parties (LP(MP)A 1989 s.2). **Guarantees**: evidenced in signed writing. **Deeds**. Most other contracts can be oral or by conduct.","offer-acceptance"],
["What is an offer?","A statement of terms on which the offeror is willing to be bound. With the **intention to be bound as soon as it is accepted**. Nothing more to negotiate.","offer-acceptance"],
["Is a statement that a party may be prepared to sell an offer?","**No**. Such words show **no intention to be bound** (Gibson). It is an invitation to apply.","offer-acceptance"],
["What is the difference between a bilateral and a unilateral contract?","**Bilateral**: a promise for a promise; both bound on acceptance. **Unilateral**: a promise for an **act**; accepted by **performing** the act.","offer-acceptance"],
["Can an advertisement be an offer?","**Yes**, if its terms are clear and it shows an **intention to be bound**. E.g. a reward or promise for an act (Carlill smoke ball).","offer-acceptance"],
["Must a person accepting a unilateral offer know of it?","**Yes**, they must **know of the offer** when they act. Their **motive** does not matter.","offer-acceptance"],
["What is an invitation to treat?","An invitation to **make offers** or negotiate. It **cannot be accepted**. The responder makes the offer.","offer-acceptance"],
["What is the legal status of goods displayed in a shop?","An **invitation to treat**. The **customer offers** at the till. The shop **accepts** or refuses.","offer-acceptance"],
["Are newspaper or website adverts usually offers?","**No**: usually **invitations to treat**. The seller might run out of stock.","offer-acceptance"],
["How is a contract formed at an auction?","Each **bid is an offer**. It is accepted on the **fall of the hammer**. A bidder can **withdraw** before then.","offer-acceptance"],
["What is the effect of an auction without reserve?","A **collateral promise** to sell to the **highest genuine bidder**. If the auctioneer withdraws the lot, the highest bidder can claim damages.","offer-acceptance"],
["Is an invitation to tender an offer?","**No**: an invitation to treat. Each **tender is an offer**.","offer-acceptance"],
["When is an invitation to tender a unilateral offer?","When it **promises** to accept the highest (or lowest) bid. A **referential bid** is invalid; the highest **fixed** bid wins.","offer-acceptance"],
["What duty can arise when tenders are invited from a small selected group?","An implied promise to **consider** every tender received **on time** under the stated procedure.","offer-acceptance"],
["Is a statement of price in reply to a question an offer?","**No**: it is **information** only.","offer-acceptance"],
["How do website sales usually work?","The **customer's order is the offer**. The seller **accepts**, usually by confirmation or dispatch, under its terms.","offer-acceptance"],
["What is acceptance?","A **final and unqualified** agreement to **all** the terms of the offer.","offer-acceptance"],
["What is the effect of a counter-offer?","It is **not** an acceptance. It **rejects and destroys** the original offer, which cannot later be accepted.","offer-acceptance"],
["Does a request for information end an offer?","**No**. A mere enquiry (e.g. can delivery be over two months?) leaves the offer **open**.","offer-acceptance"],
["What is the battle of the forms and the usual rule?","Each business sends its own **standard terms**. Each form is a **counter-offer**. The **last shot** before performance is accepted by conduct.","offer-acceptance"],
["When can an earlier form win the battle of the forms?","Where a party clearly **accepted** the other's terms, e.g. by signing and returning a **tear-off slip** (Butler).","offer-acceptance"],
["What if the parties never agree whose terms apply but perform anyway?","The court may find a contract on the **essential terms** only. Without either side's standard terms.","offer-acceptance"],
["How can acceptance be made?","By **words** or by **conduct** (e.g. dispatching goods, acting on a draft agreement).","offer-acceptance"],
["Do identical cross-offers make a contract?","**No**. Acceptance must be **in response to** the offer.","offer-acceptance"],
["Can silence be acceptance?","**No**, even if the offeror says it will be. An offeror cannot impose a contract by a failure to reply.","offer-acceptance"],
["What if the offeree uses a different method of acceptance from the one prescribed?","It is valid if **no less effective**. Unless the offer makes the stated method **mandatory** in clear words.","offer-acceptance"],
["When does acceptance generally take effect?","When and where it is **received** by the offeror.","offer-acceptance"],
["When does an instant acceptance (phone, telex) take effect?","When and where **received**. Out of hours: usually when the office reopens and it would be read.","offer-acceptance"],
["When does an email acceptance take effect?","On **receipt**, judged by reference to **business hours**. The postal rule does not apply.","offer-acceptance"],
["What is the postal rule?","A letter of acceptance takes effect when **properly posted**. Even if delayed or **lost**.","offer-acceptance"],
["When does the postal rule apply?","Only where it is **reasonable** to accept by post. It is **excluded** if the offer requires **actual receipt** (e.g. notice in writing to the vendor).","offer-acceptance"],
["What does the postal rule never apply to?","**Email, fax, telex or phone**. A **revocation** of an offer.","offer-acceptance"],
["Can an offeror revoke after promising to keep the offer open?","**Yes**, at any time before acceptance. Unless the offeree **paid** for the promise (an **option**).","offer-acceptance"],
["When does revocation take effect?","When it is **communicated** (actually received). Posting a revocation is not enough.","offer-acceptance"],
["Can revocation be communicated by a third party?","**Yes**, by a **reliable third party**.","offer-acceptance"],
["How is a unilateral offer to the world revoked?","By **reasonable steps** to bring it to the attention of those who might act. E.g. the same publicity as the offer.","offer-acceptance"],
["Can a unilateral offer be revoked once performance has started?","**No**. The offeree must have a reasonable chance to **finish**. The offeror must not **prevent** completion.","offer-acceptance"],
["When does an offer lapse?","At the end of any stated **time limit**. Otherwise after a **reasonable time**, which is short for perishables or volatile shares.","offer-acceptance"],
["What is the effect of the offeror's death?","The offer probably ends if the offeree **knows** of it or the contract is **personal**. Otherwise it may be accepted against the **estate**.","offer-acceptance"],
["What is the effect of the offeree's death?","The offer **ends**. The offeree's personal representatives cannot accept.","offer-acceptance"],
["When does an offer end for failure of a condition?","When an express or **implied condition** fails. E.g. goods no longer in the same condition.","offer-acceptance"],
["In a timeline question, when does each communication count?","Postal **acceptance**: when **posted**. **Revocation**, rejection and counter-offers: when **received**. Emails and calls: when received.","offer-acceptance"],
["What is consideration?","The **price paid for the other party's promise**. A **promise**, an **act** or a **forbearance**.","consideration"],
["Is a promise in a deed binding without consideration?","**Yes**.","consideration"],
["What are executory and executed consideration?","**Executory**: a promise to do something in future. **Executed**: an act already done in response to the promise. Both are good.","consideration"],
["Must consideration move from the promisee?","**Yes**. Only a person who gave consideration can enforce the promise. It need not move **to the promisor**.","consideration"],
["What does sufficient but need not be adequate mean?","Consideration must have **some value** in law. The court does **not** ask if it was a **fair price** (e.g. £1 a year rent; chocolate wrappers).","consideration"],
["What is not sufficient consideration?","A **vague** promise or moral feeling (e.g. to stop complaining). An existing **legal duty** (subject to exceptions). **Past** consideration.","consideration"],
["Is a promise not to sue good consideration?","**Yes**, if the claim is **reasonable** and made in **good faith**.","consideration"],
["What is the rule on past consideration?","An act done **before** the promise is **not** consideration. It was not given in return for the promise.","consideration"],
["When is a past act good consideration?","Done at the **promisor's request**. Both **understood it would be paid** for. A promise to pay in advance would have been **enforceable** (Lampleigh; Pao On).","consideration"],
["How is the request-and-payment exception applied in business?","If one business asks another to do work, the court **readily infers** both expected payment.","consideration"],
["Is performing a public legal duty consideration for a new promise?","**No**, unless the promisee does **more** than the legal duty (e.g. extra police protection).","consideration"],
["Is performing a duty owed to a third party consideration?","**Yes**. Performing an existing contractual duty to **someone else** is good consideration.","consideration"],
["Is doing what you already owe the promisor consideration for a promise to pay more?","Traditionally **no**. Unless the promisee does **more** than required. Or the promisor gets a **practical benefit**.","consideration"],
["What is the practical benefit test?","A contract for goods or services. **Before completion**, B doubts A will complete. B **promises extra** payment. B obtains a **practical benefit**. No **economic duress or fraud** by A.","consideration"],
["What can defeat a practical benefit argument?","**Economic duress** or **fraud**. E.g. a threat to walk off site unless paid more.","consideration"],
["Is part payment of a debt consideration for forgiving the rest?","**No** (Pinnel; Foakes v Beer). The creditor can sue for the **balance**.","consideration"],
["Can practical benefit make a promise to accept less binding?","**No** (Re Selectmove). It applies to promises to **pay more**, not to accept less.","consideration"],
["Is the part-payment rule still the law?","**Yes**. The Supreme Court in MWB v Rock did **not decide** the point. Foakes v Beer and Re Selectmove remain the law.","consideration"],
["When does part payment discharge the whole debt?","Payment at the **creditor's request** **earlier**, at a **different place**, or with **something different**. Part payment by a **third party**. A **composition** with creditors. A **disputed** or unliquidated claim. **Promissory estoppel**.","consideration"],
["Is paying by cheque instead of cash something different?","**No**. The creditor can still sue for the balance.","consideration"],
["Why can a creditor not sue the debtor after a third party pays part in full settlement?","It would be a **fraud on the third party**.","consideration"],
["What is a composition agreement?","All creditors agree with each other and the debtor to accept a **proportion** in full satisfaction. None can later sue for the balance.","consideration"],
["When does the part-payment rule not apply to a settlement?","Where the debt is genuinely **disputed** or **unliquidated**. It applies only to an **undisputed, fixed** debt that is due.","consideration"],
["What is promissory estoppel?","A party who promises not to enforce strict rights may be **estopped** from going back on it. Even without consideration. If it would be **inequitable**.","consideration"],
["What are the elements of promissory estoppel?","An **existing legal relationship**. A **clear and unequivocal promise** not to enforce strict rights. **Reliance** by the promisee. **Inequitable** to go back on it.","consideration"],
["Is detriment required for promissory estoppel?","Probably **not** strictly. But the promisee must have **acted on** the promise.","consideration"],
["When is it not inequitable to go back on a promise?","When the promisee obtained it by **pressure or intimidation** (e.g. holding a creditor to ransom).","consideration"],
["Can promissory estoppel found a claim?","**No**. It is a **shield, not a sword**. It cannot create a new cause of action.","consideration"],
["Does promissory estoppel end the promisor's rights permanently?","Usually it only **suspends** them. Full rights can resume for the **future** on **reasonable notice**, or when the circumstances end.","consideration"],
["What about rights for the period already covered by the promise?","Generally **extinguished**. E.g. no arrears for the period of reduced rent.","consideration"],
["How are intention, certainty and capacity tested?","**Objectively**: what the parties said and did, judged by a reasonable person.","intention-certainty-capacity"],
["What is the presumption for domestic or social agreements?","**No** intention to be legally bound. The party saying it is binding must prove otherwise.","intention-certainty-capacity"],
["How is the domestic presumption rebutted?","Spouses **separating** and agreeing terms. **Serious reliance** (e.g. selling a house). Money **pooled** in a joint venture. Agreement in **writing**.","intention-certainty-capacity"],
["What is the presumption for commercial agreements?","Intention **is** present. The burden of proving otherwise is **heavy**.","intention-certainty-capacity"],
["Does describing a commercial payment as ex gratia stop it being binding?","**No**. Those words alone do not rebut the presumption.","intention-certainty-capacity"],
["How is the commercial presumption rebutted?","A clear **honour clause**. **Subject to contract**. A **letter of comfort** stating only policy.","intention-certainty-capacity"],
["What is the effect of an honour clause?","The agreement itself is **not legally binding**. Individual orders placed and accepted under it can still be contracts.","intention-certainty-capacity"],
["What does subject to contract mean?","No binding contract until a **formal contract** is signed or exchanged. The parties can **waive** it by conduct (RTS v Müller).","intention-certainty-capacity"],
["Is a letter of comfort binding?","It depends on the words. A statement of **present policy** is not. A clear **promise** about the future can be.","intention-certainty-capacity"],
["What must a contract be in terms of certainty?","**Certain**: the words have an ascertainable meaning. **Complete**: essential terms agreed or a way to fill gaps.","intention-certainty-capacity"],
["What is the court's attitude where parties have acted on an agreement?","It tries hard to **uphold** it. Performance shows they thought they had a deal.","intention-certainty-capacity"],
["What is the effect of a vague essential term?","It is **fatal**: no contract (e.g. on hire-purchase terms).","intention-certainty-capacity"],
["What is the effect of a meaningless subsidiary phrase?","It can be **severed**, leaving a valid contract.","intention-certainty-capacity"],
["Is an agreement to agree the price binding?","**No**, an agreement to agree an **essential term** is not a contract.","intention-certainty-capacity"],
["How can a court fill gaps in an agreement?","**Previous dealings** or **trade custom**. A **machinery** such as arbitration or a valuer. **Statute** (reasonable price). **Implied terms**.","intention-certainty-capacity"],
["Which statutes imply a reasonable price where none is fixed?","**SGA 1979 s.8** (goods). **SGSA 1982 s.15** (business services). **CRA 2015 s.51** (consumer services). Not the sale of a whole business.","intention-certainty-capacity"],
["Can the court imply when payment is due if the parties did not say?","**Yes**, if they clearly intended to be bound (Wells v Devani: commission on **completion**).","intention-certainty-capacity"],
["Is an agreement to negotiate in good faith enforceable?","**No**: too uncertain.","intention-certainty-capacity"],
["When is a lock-out agreement enforceable?","Only if it is for a **fixed, specified period**.","intention-certainty-capacity"],
["What is the general rule for contracts with minors?","**Binding on the adult**. **Not enforceable against the minor**, who can enforce it.","intention-certainty-capacity"],
["What must a minor pay for necessaries?","A **reasonable price**, not necessarily the contract price.","intention-certainty-capacity"],
["What are necessaries?","Goods or services suitable to the minor's **condition in life** and **actual requirements** at the time. Not luxuries or items they already have enough of.","intention-certainty-capacity"],
["Are beneficial contracts of service binding on a minor?","**Yes**, if on the whole for the minor's **benefit** (employment, apprenticeship, training). **Not** if on the whole **oppressive**.","intention-certainty-capacity"],
["Are a minor's trading contracts binding?","**No**, even if beneficial.","intention-certainty-capacity"],
["How are a minor's continuing contracts (lease, shares, partnership) treated?","**Voidable**. Binding unless the minor **repudiates** before or within a **reasonable time after 18**.","intention-certainty-capacity"],
["Can a guarantor of a minor's contract be sued?","**Yes** (Minors' Contracts Act 1987 **s.2**).","intention-certainty-capacity"],
["What can a court order where a contract is unenforceable against a minor?","**Return** of property acquired, or property representing it, if **just and equitable** (MCA 1987 **s.3**).","intention-certainty-capacity"],
["When can a contract be avoided for mental incapacity or drunkenness?","It is **voidable** if the person could not understand. **Only if** the other party **knew or ought to have known**.","intention-certainty-capacity"],
["What if the drunk or incapacitated person later affirms the contract?","They are **bound**.","intention-certainty-capacity"],
["Must a person lacking capacity pay for necessaries?","**Yes**, a **reasonable price** (MCA 2005 s.7; SGA s.3(2)).","intention-certainty-capacity"],
["Is a company's capacity limited by its constitution?","**No** (CA 2006 **s.39**). A director's **authority** is a separate question.","intention-certainty-capacity"],
["What is privity of contract?","A contract creates rights and obligations **only between the parties**. A third party cannot **enforce** it or be **bound** by it.","privity-third-parties"],
["Does the 1999 Act let a contract impose a burden on a third party?","**No**. It changes only the **benefit** side.","privity-third-parties"],
["From when does the Contracts (Rights of Third Parties) Act 1999 apply?","Contracts made on or after **11 May 2000**.","privity-third-parties"],
["What are the two routes to enforcement under s.1?","**s.1(1)(a)**: the contract **expressly provides** the third party may enforce. **s.1(1)(b)**: the term **purports to confer a benefit** on them.","privity-third-parties"],
["How is the s.1(1)(b) presumption rebutted?","Only if the contract, properly construed, shows the parties **did not intend** the third party to enforce (s.1(2)). **Silence is not enough**.","privity-third-parties"],
["Who bears the burden of rebutting the s.1(1)(b) presumption?","The party saying the third party has no right, usually the **promisor**.","privity-third-parties"],
["How must the third party be identified (s.1(3))?","**Expressly in the contract**. By **name**, **class** or **description**. They **need not exist** yet.","privity-third-parties"],
["Will the court read words into a contract to identify a third party?","**No** (Avraamides). The identification must be in the contract itself.","privity-third-parties"],
["On what terms does a third party enforce (s.1(4))?","**Subject to** the contract's other relevant terms, e.g. time limits or arbitration.","privity-third-parties"],
["What remedies does a third party have (s.1(5))?","The **same remedies** as a party: damages, specific performance, injunction.","privity-third-parties"],
["Can a third party rely on an exclusion clause under the Act?","**Yes** (s.1(6)). Enforcing includes taking advantage of an **exclusion or limitation** clause.","privity-third-parties"],
["When can the parties not vary or cancel without the third party's consent (s.2)?","The third party has **communicated assent** to the promisor. The promisor **knows** of reliance. The promisor could **reasonably foresee** reliance **and** the third party has relied.","privity-third-parties"],
["When is a third party's posted assent effective?","Only when **received** by the promisor. The **postal rule does not apply**.","privity-third-parties"],
["Can the contract allow the parties to vary freely?","**Yes**, if it does so **expressly** (s.2(3)).","privity-third-parties"],
["When can the court dispense with the third party's consent?","Their whereabouts are unknown. They lack **capacity**. It cannot be found out whether they relied.","privity-third-parties"],
["What defences can the promisor raise against the third party (s.3)?","Any defence or **set-off** arising from the contract that it would have had against the **promisee**. Any defence it would have against the **third party** personally.","privity-third-parties"],
["Does the promisee keep its own right to enforce (s.4)?","**Yes**. The court avoids **double recovery** (s.5).","privity-third-parties"],
["Which contracts are excluded from the Act (s.6)?","**Negotiable instruments**. A **company's constitution**. LLP documents. Employment contracts enforced **against an employee**. Most **carriage of goods** terms (except exclusion clauses).","privity-third-parties"],
["Does UCTA s.2(2) apply where a third party enforces under the Act?","**No** (s.7(2)). The promisor can exclude negligence liability (not death or PI) against the third party **without** the reasonableness test.","privity-third-parties"],
["Can the parties exclude the 1999 Act?","**Yes**, with a clause saying third parties have no rights under it.","privity-third-parties"],
["Do common law exceptions to privity survive the Act?","**Yes** (s.7(1)).","privity-third-parties"],
["What can a promisee recover when suing for a third party's benefit?","Normally only **its own** loss, which may be **nominal**. **Specific performance** may be ordered so the promisor performs for the third party.","privity-third-parties"],
["When can a promisee recover damages for a third party's loss?","Exceptionally: e.g. **family holidays** or group meals. In building contracts where the property passes to a **later owner**, unless the owner has a **direct right** to sue.","privity-third-parties"],
["Is agency an exception to privity?","Not truly: the **principal** is the real party and can sue and be sued.","privity-third-parties"],
["What is a collateral contract?","A **separate** contract alongside the main one. Consideration is entering the **main contract** (e.g. specifying a supplier's paint on its promise).","privity-third-parties"],
["When can a third party enforce under a trust of a promise?","Where the promisee holds the promise **on trust** for them. A clear **intention to create a trust** is needed, so it is rare.","privity-third-parties"],
["What are the requirements of a legal assignment (LPA 1925 s.136)?","**Absolute**. **In writing** signed by the assignor. **Express written notice** to the debtor.","privity-third-parties"],
["What if an assignment does not meet s.136?","It may be an **equitable assignment**. The assignee usually must **join the assignor** in any claim.","privity-third-parties"],
["Which rights cannot be assigned?","**Personal** contracts. Where the contract **prohibits assignment**.","privity-third-parties"],
["How can the burden of a contract be transferred?","Only by **novation**: a new contract agreed by **all parties**. The burden cannot be assigned.","privity-third-parties"],
["How else might a third party claim if privity blocks them?","In **tort**, e.g. negligence against a manufacturer or a testator's solicitor.","privity-third-parties"],
["Why does it matter whether a statement is a term or a representation?","Breach of a **term**: claim for **breach of contract** (expectation damages, maybe termination). False **representation**: claim only in **misrepresentation**.","express-terms"],
["What is the test for whether a statement is a term?","The parties' **intention**, judged **objectively**. Would a reasonable person think the maker was **promising** it was true?","express-terms"],
["What factors point towards a statement being a term?","The recipient made clear it was **vital**. The maker has **special knowledge**. The maker said **not to check**. Made just **before** contracting. Included in the **written** contract.","express-terms"],
["What factors point towards a representation?","The **recipient** is the expert. The maker told the recipient to **verify** it. A long **gap** before contracting. **Left out** of a later written contract.","express-terms"],
["Is a private seller's statement to a dealer likely to be a term?","**No**, if the private seller has no special knowledge and the dealer is better placed to check.","express-terms"],
["What is the parol evidence rule?","Where a contract is in writing, **extrinsic evidence** cannot usually **add to, vary or contradict** it. It has many exceptions, so it is **weak** in practice.","express-terms"],
["Name exceptions to the parol evidence rule.","The document was not meant to contain **all the terms**. A **collateral contract**. An **implied term**. **Rectification**. **Misrepresentation**.","express-terms"],
["What does an entire agreement clause do?","Prevents a pre-contract statement being a **term** or **collateral warranty**. It does **not** by itself exclude **misrepresentation** liability.","express-terms"],
["What are the three ways a written term is incorporated?","**Signature**. **Reasonable notice**. **Course of dealing**.","express-terms"],
["Is a person bound by terms they signed but did not read?","**Yes** (L'Estrange). Exceptions: **misrepresentation** of the effect, **non est factum**, **fraud**.","express-terms"],
["What if the other party misdescribes the effect of a signed document?","They cannot rely on the term **beyond their description** (e.g. beads and sequins only).","express-terms"],
["When must notice of an unsigned term be given?","**Before or at the time** the contract is made. Terms introduced afterwards are **too late**.","express-terms"],
["When is the contract made at an automatic car park barrier?","When the driver **drives up** to the machine. Terms on the ticket come **too late**.","express-terms"],
["What document can carry contractual terms by notice?","One a reasonable person would expect to **contain terms**. Not a mere **receipt** or voucher.","express-terms"],
["How much notice is needed for an onerous or unusual term?","The more **onerous or unusual**, the more clearly it must be **drawn to attention** (red hand rule). A general reference to conditions is not enough.","express-terms"],
["How are website terms usually incorporated?","By **click-wrap**: ticking a box or clicking I accept before ordering. An obscure link may not be reasonable notice.","express-terms"],
["When does a course of dealing incorporate terms?","Where dealings are **regular and consistent**. A consumer's few dealings over years are not enough. Frequent business dealings can be.","express-terms"],
["When can common trade understanding incorporate terms?","Between businesses **in the same trade** who both know the usual terms apply. Even without previous dealings.","express-terms"],
["What is the aim of contract interpretation?","What a **reasonable person** with the parties' **background knowledge** would understand the words to mean.","express-terms"],
["What background can the court consider?","Anything reasonably available to **both** parties at the time (the **matrix of fact**). Except **pre-contract negotiations** and **subjective intention**.","express-terms"],
["What is the most important factor in interpretation?","The **natural and ordinary meaning** of the words. **Commercial common sense** must not undermine clear language (Arnold v Britton).","express-terms"],
["When does business common sense decide the meaning?","Where a term is genuinely open to **two meanings**. Prefer the one more consistent with **business common sense** (Rainy Sky).","express-terms"],
["What is the unitary approach to interpretation?","Balancing **textual** and **contextual** analysis. Professionally drafted contracts are read more **textually**; informal ones more **contextually**.","express-terms"],
["Are pre-contract negotiations admissible to interpret a contract?","**No**. Except to show a fact known to both, or for **rectification** or **estoppel**.","express-terms"],
["Is subsequent conduct admissible to interpret a contract?","**No**.","express-terms"],
["When can the court correct an obvious drafting mistake?","When it is clear **both** that something has **gone wrong** and **what** a reasonable person would understand was meant.","express-terms"],
["What is contra proferentem?","A genuinely **ambiguous** term is read **against** the party who drafted or relies on it. Mainly used for **exclusion clauses**.","express-terms"],
["How are ambiguous terms in consumer contracts read?","In the way **most favourable to the consumer** (CRA 2015 s.69).","express-terms"],
["What is the ejusdem generis rule?","General words after a list of specific items are limited to things **of the same kind**.","express-terms"],
["What is rectification?","An equitable remedy **correcting** a written document that does not record what the parties **actually agreed**. It **changes the words**, unlike interpretation.","express-terms"],
["What is needed for common mistake rectification?","A **common intention** continuing until signing, judged **subjectively**. An **outward expression of accord**. The document by mistake does not reflect it.","express-terms"],
["When is unilateral mistake rectification available?","Only where one party **knew** the document did not reflect the other's intention and **unfairly kept quiet**.","express-terms"],
["What is the remedy for breach of a condition?","**Terminate and/or damages**, however minor the actual consequences.","express-terms"],
["What is the remedy for breach of a warranty?","**Damages only**. No right to terminate.","express-terms"],
["When can an innocent party terminate for breach of an innominate term?","Only if the breach **deprives them of substantially the whole benefit** of the contract. Otherwise damages only.","express-terms"],
["In what order do you classify a term?","**Statute**. **Case law**. The parties' **express wording**. Otherwise **innominate**.","express-terms"],
["Which terms implied by the Sale of Goods Act 1979 are conditions, and which are warranties?","**Conditions**: the seller's **right to sell** (s.12(1)), **description** (s.13), **satisfactory quality** and **fitness for purpose** (s.14) and **sample** (s.15).\nThe s.12(2) terms (goods **free from undisclosed charges** and the buyer's **quiet possession**) are only **warranties** (s.12(5A)).","express-terms"],
["Are time clauses in commercial contracts conditions?","Usually **yes** (e.g. shipment or notice dates), because **certainty** is vital. Even if the delay causes little harm.","express-terms"],
["Is time of payment of the essence?","**Not usually**, unless the contract says so (SGA s.10(1)).","express-terms"],
["Does labelling a term a condition make it one?","**Not conclusively**. It is strong evidence (Schuler). Ask whether the parties meant **any** breach to allow termination.","express-terms"],
["What wording usually makes a term a condition?","**Time is of the essence**. **Any breach** of this clause entitles termination.","express-terms"],
["What does SGA s.15A do for business buyers?","A **non-consumer** cannot reject for breach of ss.13-15 if the breach is **so slight** rejection would be **unreasonable**. It is treated as a **warranty** breach. The seller proves slightness; s.15A can be excluded.","express-terms"],
["Does a variation need consideration?","**Yes** (or a **deed**). It is itself a contract. Practical benefit may supply it for paying more.","express-terms"],
["How does variation differ from rescission and replacement?","**Variation** keeps the original contract with some terms changed. **Replacement** rescinds the old contract and makes a new one.","express-terms"],
["Is a no oral modification clause effective?","**Yes** (Rock Advertising). An oral variation that does not comply is **ineffective**.","express-terms"],
["When might estoppel stop a party relying on a NOM clause?","Words or conduct **unequivocally representing** the informal variation was valid. And **something more** than the informal promise.","express-terms"],
["What is waiver?","A party chooses not to insist on a right (e.g. accepting late delivery). It may not go back on it without **reasonable notice**.","express-terms"],
["What are the three ways terms are implied?","**In fact**: into this particular contract. **In law**: into all contracts of a type. **By statute**: goods, services, digital content.","implied-terms"],
["Which statutes imply terms into B2B and private sales, and which into consumer contracts?","**B2B and private**: **SGA 1979** and **SGSA 1982**. **Trader to consumer**: **CRA 2015** Part 1.","implied-terms"],
["What are the traditional tests for a term implied in fact?","**Business efficacy**: necessary to make the contract work. **Officious bystander**: so obvious it goes without saying.","implied-terms"],
["What is the modern test for implying a term in fact?","**Necessary for business efficacy** **or** so **obvious** it goes without saying (alternatives). Capable of **clear expression**. Must not **contradict an express term** (M&S v BNP Paribas).","implied-terms"],
["Will a term be implied because it is reasonable or fair?","**No**. **Necessity** (or obviousness) is required.","implied-terms"],
["What must the court do before implying a term?","First **interpret** the express terms.","implied-terms"],
["What is a term implied in law?","A **standard incident** of a defined **class** of contract. Implied where **necessary** given the nature of the relationship.","implied-terms"],
["What term is implied into tenancies of a block with common parts?","The landlord will take **reasonable care** to keep the **common parts** in reasonable repair. No absolute duty.","implied-terms"],
["Give an example of a term implied in law in employment.","The duty of **mutual trust and confidence**.","implied-terms"],
["When is a term implied by custom?","The custom is **notorious**, **certain**, **reasonable** and **not inconsistent** with the express terms.","implied-terms"],
["What does SGA s.12 imply?","The seller has the **right to sell** (good title): a **condition**. Quiet possession and freedom from undisclosed charges are **warranties** (s.12(2)). Applies to private sellers.","implied-terms"],
["What does SGA s.13 imply?","Goods correspond with their **description**. A **condition**; applies to private sellers. Even a small departure can be a breach.","implied-terms"],
["What does SGA s.14(2) imply and who is bound?","Goods are of **satisfactory quality**. Only where sold **in the course of a business**.","implied-terms"],
["Does a one-off sale by a business of its own old equipment count as in the course of a business?","**Yes**. Any sale by a business counts (e.g. a fisherman selling his boat).","implied-terms"],
["What is the test for satisfactory quality?","The standard a **reasonable person** would regard as satisfactory. Taking account of **description**, **price** and other circumstances.","implied-terms"],
["What aspects of quality are listed in SGA s.14(2B)?","Fitness for all **common purposes**. **Appearance and finish**. Freedom from **minor defects**. **Safety**. **Durability**.","implied-terms"],
["When does the satisfactory quality term not cover a defect?","Defects **specifically pointed out** before the contract. Defects an **examination** the buyer made ought to have revealed.","implied-terms"],
["What does SGA s.14(3) imply?","Goods are **reasonably fit** for a **particular purpose** the buyer makes known. Unless the buyer **did not rely**, or it was **unreasonable** to rely, on the seller.","implied-terms"],
["What does SGA s.15 imply?","Goods correspond with the **sample**. A **condition**; applies to private sellers.","implied-terms"],
["Which implied terms does a private seller give?","Only **title** (s.12), **description** (s.13) and **sample** (s.15). **No** quality or fitness terms.","implied-terms"],
["What are a business buyer's remedies for breach of an SGA condition?","**Reject** the goods and claim **damages**. Subject to **s.15A** (slight breach) and **s.35** (acceptance).","implied-terms"],
["When does a buyer accept goods under SGA s.35?","Telling the seller it accepts. An act **inconsistent with the seller's ownership** after a chance to examine. Keeping them beyond a **reasonable time**. After that, damages only.","implied-terms"],
["What terms does SGSA Part II imply into B2B services?","**s.13**: **reasonable care and skill**. **s.14**: **reasonable time**. **s.15**: **reasonable charge**.","implied-terms"],
["How are SGSA service terms classified?","**Innominate**. Termination depends on how serious the breach is.","implied-terms"],
["What does SGSA Part I cover?","Goods transferred under contracts that are not sales: **work and materials** and **hire**. Similar terms to the SGA.","implied-terms"],
["Who is a consumer under the CRA?","An **individual** acting wholly or mainly **outside** their trade, business, craft or profession. A **company** is never a consumer.","implied-terms"],
["Who is a trader under the CRA?","A person acting for purposes relating to their **trade, business, craft or profession**.","implied-terms"],
["What statutory rights apply to goods under the CRA?","**s.9** satisfactory quality; **s.10** fitness; **s.11** description; **s.12** pre-contract information. **s.13-14** sample and model; **s.15** installation; **s.17** right to supply.","implied-terms"],
["What extra factor does CRA s.9 include in satisfactory quality?","**Public statements** by the trader or producer, such as **advertising** and labelling.","implied-terms"],
["What is the effect of incorrect installation by the trader (CRA s.15)?","The goods are treated as **not conforming** to the contract.","implied-terms"],
["What statutory rights apply to services under the CRA?","**s.49** **reasonable care and skill**. **s.50** information the consumer took into account is **binding**. **s.51** reasonable price. **s.52** reasonable time.","implied-terms"],
["What are the three tiers of consumer remedies for goods?","**Short-term right to reject**. **Repair or replacement**. **Price reduction** or **final right to reject**.","implied-terms"],
["How long is the short-term right to reject?","**30 days** from the latest of transfer, **delivery** and **installation**. Shorter for **perishable** goods.","implied-terms"],
["What refund does the short-term right to reject give?","A **full refund**, **no deduction** for use. Within **14 days** of the trader agreeing.","implied-terms"],
["What are the rules on repair or replacement?","The **consumer chooses**. Done within a **reasonable time**, without **significant inconvenience**, at the **trader's cost**. The trader can refuse an option that is **impossible** or **disproportionate**.","implied-terms"],
["When can a consumer claim price reduction or final rejection?","After **one** failed repair **or** replacement. Or if repair or replacement is **impossible** or not done properly in time. One or the other, not both.","implied-terms"],
["When can a deduction for use be made on final rejection?","Not within **6 months** of delivery. **Except** for **motor vehicles**.","implied-terms"],
["What is the 6-month presumption under the CRA?","Goods failing within **6 months** of delivery are **presumed** faulty at delivery unless the trader proves otherwise. It applies to tiers 2 and 3, **not** the short-term right to reject.","implied-terms"],
["What else can a consumer claim besides the tiered remedies?","**Damages** for other loss. **Specific performance** of repair or replacement.","implied-terms"],
["What is the limitation period for a consumer's contract claim?","**6 years** from breach.","implied-terms"],
["What remedies apply to faulty digital content?","**Repair or replacement**, then **price reduction**. **No right to reject** content not on a tangible medium.","implied-terms"],
["What if faulty digital content damages the consumer's device?","If the trader lacked **reasonable care and skill**, it must **repair** the damage or pay **compensation** (s.46).","implied-terms"],
["What remedies apply to services under the CRA?","**Repeat performance** at the trader's cost. Then **price reduction** (up to the full price) if repeat performance is impossible or not done properly.","implied-terms"],
["What remedies apply for breach of CRA ss.51 or 52?","**Ordinary remedies**, such as damages, and possibly termination.","implied-terms"],
["What is the difference between an exclusion clause and a limitation clause?","**Exclusion**: removes liability completely. **Limitation**: caps it (e.g. to £1,000 or the price paid).","exemption-clauses"],
["What are the three stages of controlling exemption clauses?","**Incorporation**. **Construction**: does it cover the loss? **Statutory control**: UCTA or CRA Part 2.","exemption-clauses"],
["Which statute controls exemption clauses in B2B contracts and which in consumer contracts?","**B2B**: **UCTA 1977**. **Trader to consumer**: **CRA 2015 Part 2**. UCTA no longer applies to consumer contracts.","exemption-clauses"],
["How are exemption clauses construed?","**Strictly**: clear words are needed. A genuinely **ambiguous** clause is read **against** the party relying on it (contra proferentem).","exemption-clauses"],
["Is contra proferentem applied equally to exclusion and limitation clauses?","**No**. Less strictly to **limitation** clauses. In commercial contracts it is a **last resort**.","exemption-clauses"],
["How do you decide whether a clause covers negligence?","Does it **expressly** mention **negligence** (or a synonym)? If not, are the words **wide enough**? If so, could it realistically cover **other liability** instead? These are **guidelines** (Canada Steamship).","exemption-clauses"],
["Can an exemption clause cover a fundamental or deliberate breach?","**Yes**, if clearly worded. It is a question of **construction**, not a rule of law.","exemption-clauses"],
["What liability does UCTA mainly control?","**Business liability** (s.1(3)): things done in the course of a business or from occupying business premises.","exemption-clauses"],
["What kinds of clause does UCTA cover besides straight exclusions?","**Restrictive or onerous conditions** (e.g. claims within 7 days). Clauses **restricting remedies**. Excluding rules of **evidence or procedure**. **Notices** as well as terms.","exemption-clauses"],
["Which contracts are outside UCTA?","**Consumer** contracts. Schedule 1 contracts: **insurance**, **land**, company formation, IP. **International supply** contracts.","exemption-clauses"],
["Can a business exclude liability for death or personal injury caused by negligence?","**No**. It is **void** (UCTA **s.2(1)**).","exemption-clauses"],
["How does UCTA treat exclusion of other loss caused by negligence?","Valid only if **reasonable** (**s.2(2)**).","exemption-clauses"],
["When does UCTA s.3 apply?","Where one party deals on the **other's written standard terms of business**. Clauses excluding liability for breach, or allowing **substantially different** or **no** performance, must be **reasonable**.","exemption-clauses"],
["Does UCTA s.3 apply to genuinely negotiated terms?","**No**. s.2 or s.6 may still apply.","exemption-clauses"],
["How does UCTA treat exclusion of the SGA implied terms?","**Title** (s.12): **void**. **Description, quality, fitness, sample** (ss.13-15): **reasonableness** (s.6(1A)).","exemption-clauses"],
["Does UCTA s.6 apply to private sales?","**Yes** (s.6(4)). It covers any contract for the sale of goods.","exemption-clauses"],
["How is exclusion of liability for misrepresentation controlled?","Valid only if **reasonable** (Misrepresentation Act 1967 **s.3**, applying the UCTA test).","exemption-clauses"],
["Does awareness of a negligence exclusion mean the claimant accepted the risk?","**No**, not by itself (UCTA s.2(3); CRA s.65).","exemption-clauses"],
["What is the UCTA reasonableness test (s.11)?","Was it **fair and reasonable to include** the term. Considering what was known or contemplated **when the contract was made**.","exemption-clauses"],
["Who bears the burden of proving reasonableness?","The party **relying** on the clause (s.11(5)).","exemption-clauses"],
["What must be considered for a clause limiting liability to a fixed sum?","The party's **resources** to meet the liability. How far it could have **insured** (s.11(4)).","exemption-clauses"],
["What are the Schedule 2 reasonableness guidelines?","Relative **bargaining strength**. Any **inducement** (e.g. lower price). Whether the customer **knew** of the term. Whether a condition was **practicable** to meet. Goods made to **special order**.","exemption-clauses"],
["What points towards a clause being reasonable?","**Equal bargaining power**; **negotiated** terms. Customer got a **lower price** or could insure. A sensible **cap** rather than total exclusion. Customer **knew** of the clause.","exemption-clauses"],
["What points towards a clause being unreasonable?","Weaker party with **no real choice**. Standard terms imposed. Supplier could **easily insure**. **Total exclusion** or a **tiny cap**. The supplier usually **settled above** the limit.","exemption-clauses"],
["How do courts treat terms negotiated between experienced businesses?","They are **very slow to interfere**. The parties are the best judges of commercial fairness.","exemption-clauses"],
["What does CRA Part 2 apply to?","Terms in **consumer contracts** and **consumer notices**. Whether or not **individually negotiated**.","exemption-clauses"],
["What terms are blacklisted under the CRA for goods and digital content?","Excluding or restricting liability for the **statutory rights** for goods (**s.31**) or digital content (**s.47**).","exemption-clauses"],
["What does CRA s.57 say about services?","Liability under **s.49** (care and skill) and **s.50** cannot be **excluded**. Liability cannot be restricted below the **price paid**.","exemption-clauses"],
["What does CRA s.65 say?","Liability for **death or personal injury** caused by **negligence** cannot be excluded or restricted.","exemption-clauses"],
["What is the CRA fairness test (s.62)?","A term is **unfair** if, **contrary to good faith**, it causes a **significant imbalance** in rights and obligations **to the consumer's detriment**.","exemption-clauses"],
["What is the effect of an unfair term?","It is **not binding on the consumer**, who may still rely on it. The rest of the contract continues where practicable.","exemption-clauses"],
["What is taken into account in judging fairness?","The **nature of the subject matter**. **All circumstances** when the term was agreed. The **other terms** of the contract.","exemption-clauses"],
["What does good faith mean in the fairness test?","**Fair and open dealing**. Clear, legible terms without traps. Not taking advantage of the consumer's **weak position** or inexperience.","exemption-clauses"],
["What is the grey list?","An **indicative, non-exhaustive** list of terms that **may** be unfair (Sch 2 Part 1). They are **not automatically** unfair.","exemption-clauses"],
["Give examples of grey list terms.","A **disproportionately high** sum on cancellation or default. Trader keeps prepayments with no equivalent if it cancels. Trader can **alter terms** or **price** unilaterally. Terms the consumer had no chance to read.","exemption-clauses"],
["What is the core terms exemption (s.64)?","Terms on the **main subject matter** or the **appropriateness of the price** cannot be assessed for fairness. Only if **transparent** and **prominent**.","exemption-clauses"],
["What do transparent and prominent mean under s.64?","**Transparent**: plain, intelligible and **legible**. **Prominent**: an **average consumer** would be aware of it.","exemption-clauses"],
["Can a grey list term benefit from the core terms exemption?","**No** (s.64(6)).","exemption-clauses"],
["Does the core terms exemption protect extra charges for default or cancellation?","**No**. It only stops assessment of whether the **price is too high** for what is supplied.","exemption-clauses"],
["Must the court consider fairness if neither party raises it?","**Yes**, of its own motion, if it has enough material (s.71).","exemption-clauses"],
["Who can act against traders using unfair terms?","The **CMA** and other regulators, by **injunction** (s.70).","exemption-clauses"],
["What is a misrepresentation?","An **untrue statement of fact or law**. Made by one party to the other **before or at** contracting. Which **induces** the contract.","misrepresentation"],
["What is the effect of a misrepresentation on the contract?","It makes the contract **voidable**. Valid until the innocent party **rescinds**. Damages may also be available.","misrepresentation"],
["Can a misrepresentation be made by conduct?","**Yes**, e.g. joining a promotion while knowing a member is leaving.","misrepresentation"],
["When is an ambiguous statement a misrepresentation?","Only if false in the sense the representee **understood** it. And the representor **intended** it to be understood that way.","misrepresentation"],
["Is an honest opinion a misrepresentation?","**No**, where both parties are **equally placed**.","misrepresentation"],
["When is a statement of opinion a misrepresentation?","When the maker has **special knowledge**, so it **implies facts** justifying it. Or the opinion was **not honestly held**.","misrepresentation"],
["Is a statement of future intention a misrepresentation?","**No**, if honestly held. **Yes**, if the maker **did not actually hold** that intention.","misrepresentation"],
["Is sales puff a misrepresentation?","**No**. Vague praise (e.g. fertile and improvable, a goldmine) is not a statement of fact.","misrepresentation"],
["Can a misstatement of law be a misrepresentation?","**Yes**.","misrepresentation"],
["Is silence a misrepresentation?","**No**: there is **no general duty to disclose** (caveat emptor). Subject to exceptions.","misrepresentation"],
["What are the exceptions to the silence rule?","**Half-truths**. A **change of circumstances** before the contract. **Fiduciary** relationships. **Insurance** contracts (now modified by statute).","misrepresentation"],
["What is a half-truth?","A statement literally true but **misleading** because of what is **left out**. E.g. farms let, without saying tenants had given notice.","misrepresentation"],
["What is the rule on change of circumstances?","A statement true when made that becomes **false before the contract** must be **corrected**.","misrepresentation"],
["What disclosure duties apply to insurance today?","**Consumer**: take **reasonable care** not to misrepresent (CIDRA 2012). **Business**: duty of **fair presentation** (Insurance Act 2015).","misrepresentation"],
["Who must make the misrepresentation?","The **other contracting party** or their agent. A stranger's statement is not an operative misrepresentation.","misrepresentation"],
["How important must the misrepresentation be to the decision?","It must be **a** reason for contracting. Not necessarily the only or main reason.","misrepresentation"],
["Is it a defence that the representee could have discovered the truth?","**No**. The representee **need not check**.","misrepresentation"],
["When is there no inducement?","The representee **did not know** of the statement. **Did not believe** it or let it affect them. **Relied on their own judgement** or experts instead.","misrepresentation"],
["How is inducement proved for a material statement?","It is readily **inferred** if a reasonable person would have been induced. The representee need not **believe** it, only be **influenced** by it.","misrepresentation"],
["What is fraudulent misrepresentation?","A statement made **knowingly**, **without belief** in its truth, or **recklessly** careless whether true or false.","misrepresentation"],
["Is an honest but unreasonable belief fraud?","**No** (Derry v Peek).","misrepresentation"],
["What damages are available for fraudulent misrepresentation?","Tort of **deceit**: tort measure. **All direct loss** flowing from the fraud, whether or not foreseeable. **Contributory negligence** is **no defence**.","misrepresentation"],
["What is the test for liability under s.2(1) Misrepresentation Act 1967?","Liable as if fraudulent, **unless** the representor proves **reasonable grounds to believe** and **did believe** the statement up to the contract.","misrepresentation"],
["Why is s.2(1) usually the best claim for non-fraudulent misrepresentation?","**Burden** is on the representor. **No duty of care** needed. **Fraud measure** of damages: all direct loss, even unforeseeable (Royscot).","misrepresentation"],
["Can s.2(1) damages be reduced for contributory negligence?","**Yes**, where the defendant is also concurrently liable in **negligence**.","misrepresentation"],
["How does a negligent misstatement claim at common law differ?","The claimant must prove a **duty of care** and breach. Damages for **reasonably foreseeable** loss.","misrepresentation"],
["Are damages available as of right for wholly innocent misrepresentation?","**No**. The court **may** award **damages in lieu of rescission** under s.2(2).","misrepresentation"],
["When can the court award damages in lieu of rescission (s.2(2))?","For **non-fraudulent** misrepresentation where rescission is available. If **equitable**, considering the misrepresentation and the losses either way.","misrepresentation"],
["What indemnity is available with rescission?","For expenses incurred under **obligations created by the contract**. Not wider losses.","misrepresentation"],
["What is the measure of misrepresentation damages compared with contract damages?","**Misrepresentation**: as if the statement **had not been made** (tort). **Contract**: as if the statement **had been true** (expectation).","misrepresentation"],
["Which claim is worth more where the claimant made a good bargain?","Usually the **contract** claim, if the statement was also a **term**.","misrepresentation"],
["What is rescission?","Setting the contract aside **from the beginning**. Each party returns what it received. Available for **all types** of misrepresentation.","misrepresentation"],
["How is rescission effected?","By **communicating** the decision to the representor. Or another act clearly showing it, e.g. telling the police if a rogue cannot be found.","misrepresentation"],
["What are the bars to rescission?","**Affirmation**. **Lapse of time**. **Restitutio in integrum impossible**. **Third party rights**. The court's discretion under **s.2(2)**.","misrepresentation"],
["What is affirmation?","The representee, **knowing** of the misrepresentation, shows it intends to **continue** (e.g. keeps using the goods).","misrepresentation"],
["When does time run for the lapse of time bar?","**Non-fraudulent**: can run from the **contract** date. **Fraud**: from **discovery**.","misrepresentation"],
["Must restoration be exact for rescission?","**No**. **Substantial** restoration is enough; money adjustments can be made.","misrepresentation"],
["How do third party rights bar rescission?","An innocent third party acquires the goods **in good faith and for value** **before** rescission.","misrepresentation"],
["Can liability for misrepresentation be excluded?","Only if the term is **reasonable** (MA 1967 **s.3**, UCTA s.11 test). **Fraud** can never be excluded.","misrepresentation"],
["Do entire agreement or non-reliance clauses avoid s.3?","**Entire agreement** clauses do not exclude misrepresentation liability by themselves. **Non-reliance** clauses are still subject to s.3.","misrepresentation"],
["What statutory redress can a misled consumer have?","Rights to **unwind** the contract, a **discount** or **damages**. Now under the **DMCCA 2024** (from 6 April 2025).","misrepresentation"],
["What is the effect of an operative mistake?","The contract is **void**: it never existed and no ownership passes. An innocent buyer from a rogue gets **nothing**.","mistake-duress-ui-illegality"],
["What is the effect of duress or undue influence?","The contract is **voidable**: valid until rescinded. An innocent buyer for value **before** rescission keeps the goods.","mistake-duress-ui-illegality"],
["What happens if specific goods have perished when the contract is made?","The contract is **void** if the seller did not know (SGA **s.6**; res extincta).","mistake-duress-ui-illegality"],
["What is res sua?","The buyer **already owns** the thing. The agreement can be set aside.","mistake-duress-ui-illegality"],
["When does a common mistake as to quality make a contract void?","Only if it makes the subject matter **essentially and radically different**. This is almost never satisfied.","mistake-duress-ui-illegality"],
["What is the test for common mistake?","A **common assumption**. **Neither party warranted** it. Not either party's **fault**. Performance **impossible** or **essentially different**. About the existence or a **vital attribute** of the subject matter.","mistake-duress-ui-illegality"],
["Is there an equitable doctrine of rescission for common mistake?","**No** (Great Peace).","mistake-duress-ui-illegality"],
["What if one party promised the subject matter existed?","It takes the **risk** and is liable in **damages**. There is no common mistake.","mistake-duress-ui-illegality"],
["How is mutual mistake (cross-purposes) resolved?","**Objectively**: a contract on the meaning a reasonable person would prefer. **No contract** only if no meaning can be preferred.","mistake-duress-ui-illegality"],
["When does a unilateral mistake about the terms prevent a contract?","When the other party **knows or ought to know** of the mistake (e.g. price per pound instead of per piece).","mistake-duress-ui-illegality"],
["Does a unilateral mistake about quality affect the contract?","**No**, even if the other party knows, unless they **caused** it by misrepresentation.","mistake-duress-ui-illegality"],
["What is the presumption in a face-to-face dealing with a rogue?","The seller intends to deal with **the person in front of them**. The contract is **voidable** for fraud, not void.","mistake-duress-ui-illegality"],
["What is the position where a written contract names a specific real person and a rogue impersonates them?","The contract is with the **person named**. It is **void**, so the owner can recover the goods.","mistake-duress-ui-illegality"],
["In a rogue question, what else must you check?","Whether the owner **rescinded before** the rogue sold on (e.g. by telling the **police**).","mistake-duress-ui-illegality"],
["What must be shown for non est factum?","The document was **radically different** from what the signer believed. And the signer was **not careless**.","mistake-duress-ui-illegality"],
["Who mainly benefits from non est factum?","People who are **blind**, **illiterate** or have a disability preventing understanding, and who took **reasonable care**.","mistake-duress-ui-illegality"],
["What is duress to the person and how much must it influence the decision?","Threats of **violence** or unlawful imprisonment. It need only be **a** reason. The threatener must prove it contributed **nothing**.","mistake-duress-ui-illegality"],
["How is duress to goods treated now?","As a form of **economic duress**.","mistake-duress-ui-illegality"],
["What is the test for economic duress?","**Pressure** leaving **no practical choice**. The pressure was **illegitimate**. It was a **significant cause**, at least a **but for** cause.","mistake-duress-ui-illegality"],
["Is a threat to break a contract illegitimate pressure?","**Usually yes**, particularly if made in **bad faith**.","mistake-duress-ui-illegality"],
["What factors does the court consider in economic duress?","Did the victim **protest**? Any **realistic alternative**? **Independent advice**? Did it act **promptly** to avoid the contract? Was the threatener in **good or bad faith**?","mistake-duress-ui-illegality"],
["How can a victim of economic duress lose the right to rescind?","By **affirming**, e.g. paying and then **waiting months** without protest.","mistake-duress-ui-illegality"],
["When can a threat to do something lawful be duress?","Very rarely. Only where **reprehensible** or **unconscionable**. E.g. using knowledge of **criminal conduct**, or **deliberately creating** the victim's vulnerability to demand something with **no reasonable** claim.","mistake-duress-ui-illegality"],
["Is hard bargaining by a stronger party duress?","**No**.","mistake-duress-ui-illegality"],
["What is undue influence?","Taking unfair advantage of **influence** over another so their decision was not their **free will**. The transaction is **voidable**.","mistake-duress-ui-illegality"],
["What must a claimant prove for actual undue influence?","That the wrongdoer **actually exerted** improper influence (pressure, coercion, domination). No relationship of trust is needed.","mistake-duress-ui-illegality"],
["What must be proved to raise presumed undue influence?","A relationship of **trust and confidence**. And a transaction that **calls for explanation**.","mistake-duress-ui-illegality"],
["What is the effect of the presumption of undue influence?","The **burden shifts** to the wrongdoer to show the victim acted freely. Usually by proving **independent advice**.","mistake-duress-ui-illegality"],
["Which relationships automatically involve trust and confidence?","**Solicitor and client**; **doctor and patient**; **trustee and beneficiary**. **Parent and minor child**; **religious adviser and follower**.","mistake-duress-ui-illegality"],
["Is husband and wife an automatic relationship of trust and confidence?","**No**. It must be **proved on the facts**, e.g. a wife who left all finances to her husband.","mistake-duress-ui-illegality"],
["Is a wife guaranteeing her husband's business debts a transaction calling for explanation?","**Not in itself**. Wives commonly support husbands' businesses.","mistake-duress-ui-illegality"],
["When is a bank put on inquiry?","When a wife, or anyone in a **non-commercial relationship** with the debtor, offers to **stand surety** for the debtor's or **their company's** debts.","mistake-duress-ui-illegality"],
["Is a bank put on inquiry by a joint loan to husband and wife?","**No**, if for their **joint benefit**, unless the bank knows it is really for the husband's purposes.","mistake-duress-ui-illegality"],
["What reasonable steps must the bank take?","Contact the wife **directly** and explain it needs a solicitor's confirmation. She **nominates a solicitor**. Give the solicitor the **financial information**. Obtain **written confirmation** she was advised.","mistake-duress-ui-illegality"],
["What must the wife's solicitor do?","Meet her **face to face**, **without the husband**. Explain the documents and risks (she could **lose her home**). Explain she has a **choice** and check she wishes to proceed.","mistake-duress-ui-illegality"],
["What if the bank took the reasonable steps but the advice was poor?","The bank can **enforce** the charge. The wife's remedy is against her **solicitor**.","mistake-duress-ui-illegality"],
["What if the bank failed to take the steps?","It has **constructive notice** of any proven undue influence or misrepresentation. The charge can be **set aside**.","mistake-duress-ui-illegality"],
["Do the bank inquiry principles apply beyond spouses?","**Yes**, to other **non-commercial** relationships, e.g. a junior employee guaranteeing her employer's debts.","mistake-duress-ui-illegality"],
["What is the test for illegality?","Would enforcing the claim be **contrary to the public interest** by harming the **integrity of the legal system** (Patel v Mirza)?","mistake-duress-ui-illegality"],
["What is the trio of considerations for illegality?","The **purpose** of the prohibition broken. Any **other public policy**. Whether denying the claim is **proportionate**.","mistake-duress-ui-illegality"],
["What factors are relevant to proportionality in illegality?","**Seriousness** of the conduct. Its **centrality** to the contract. Whether **intentional**. Any **disparity** in culpability.","mistake-duress-ui-illegality"],
["Can money paid under an illegal contract be recovered?","**Usually yes**, in **unjust enrichment**, unless the trio of considerations points the other way.","mistake-duress-ui-illegality"],
["When is a restraint of trade clause valid?","Only if it protects a **legitimate interest** and is **reasonable** in area, time and activity. Otherwise **void**.","mistake-duress-ui-illegality"],
["What are legitimate interests for a restraint of trade?","**Trade secrets**. **Customer connections**. **Goodwill** of a business sold. Not mere protection from competition.","mistake-duress-ui-illegality"],
["When can an unreasonable part of a restraint be severed?","If it can be **deleted** without adding to or rewriting the rest. And without changing the **overall effect** of the restraint.","mistake-duress-ui-illegality"],
["What are the ways a contract is terminated?","**Performance**, **expiry** or a **specified event**. **Agreement**. **Breach**. **Frustration**.","discharge-frustration"],
["What is the entire obligations rule?","If complete performance is required before payment, partial or defective performance earns **nothing** under the contract.","discharge-frustration"],
["What are the exceptions to the entire obligations rule?","**Substantial performance**. **Severable** obligations. **Free acceptance** of partial performance. **Prevention** by the other party. **Tender** of performance.","discharge-frustration"],
["What does a party recover for substantial performance?","The **contract price minus the cost of remedying** the defects.","discharge-frustration"],
["When is performance not substantial?","When the work does not do its **main job** (e.g. a heating system that fumes and heats poorly). The claimant recovers **nothing**.","discharge-frustration"],
["What are severable obligations?","Payment due in **stages** or instalments. Each completed stage can be claimed.","discharge-frustration"],
["When must a party pay for partial performance it received?","When it **freely chose** to accept it: a **quantum meruit**. Not where it had **no real choice** (e.g. half-built structures on its own land).","discharge-frustration"],
["What can a party claim if the other prevents completion?","A **quantum meruit** for work done, or damages.","discharge-frustration"],
["What is the effect of tendering performance that is refused?","The party is treated as having **performed** and is discharged. It can claim damages for non-acceptance.","discharge-frustration"],
["What if time is not of the essence and the other party is late?","Serve a **notice** giving a reasonable period. After that, time becomes **of the essence**.","discharge-frustration"],
["What are a condition precedent and a condition subsequent?","**Precedent**: must happen before obligations arise (e.g. subject to planning). **Subsequent**: an event that **ends** the contract.","discharge-frustration"],
["What rights can a termination clause give?","Termination **on notice** for no reason. Or for **specified breaches or events**, even if not repudiatory.","discharge-frustration"],
["What must a party do when using a termination clause?","Follow its **procedure exactly**. It may not give damages for loss of the whole bargain unless the breach was also repudiatory.","discharge-frustration"],
["What consideration is needed to end a contract by agreement?","If both still have obligations: **mutual release**. If one has fully performed: **accord and satisfaction** (fresh consideration) or a **deed**.","discharge-frustration"],
["What is a breach of contract?","Failing to perform when due, **defective** performance, or **repudiation**, without lawful excuse. **Every** breach gives a right to **damages**.","discharge-frustration"],
["When is a breach repudiatory?","Breach of a **condition**. A serious breach of an **innominate** term depriving the innocent party of **substantially the whole benefit**. **Renunciation**.","discharge-frustration"],
["Does a repudiatory breach end the contract automatically?","**No**. The innocent party must **elect** to **affirm** or **terminate**.","discharge-frustration"],
["What is the effect of affirming after a repudiatory breach?","The contract **continues**. Both must still perform. The innocent party claims **damages**.","discharge-frustration"],
["What is the effect of accepting a repudiation?","Both are released from **future** obligations. **Accrued rights** stay enforceable. The innocent party claims damages including **loss of the bargain**.","discharge-frustration"],
["How must acceptance of a repudiation be made?","**Clear and unequivocal** and **communicated**. No particular form; sometimes **conduct** or failure to perform is enough.","discharge-frustration"],
["Can a party who affirmed later terminate?","Not for the **same** breach. It can for a **later** repudiatory breach.","discharge-frustration"],
["What is the effect of wrongful termination?","The terminating party is itself in **repudiatory breach**.","discharge-frustration"],
["What is an anticipatory breach?","Before performance is due, a party clearly indicates it **will not perform**. Or disables itself from performing.","discharge-frustration"],
["What can the innocent party do on an anticipatory breach?","**Accept** and sue **immediately**, but must **mitigate**. Or **affirm** and wait, with no duty to mitigate before acceptance.","discharge-frustration"],
["What is the risk of affirming after an anticipatory breach?","A later event may **frustrate** the contract and the claim is **lost** (Avery v Bowden).","discharge-frustration"],
["When can an innocent party perform anyway and claim the full price?","It can perform **without the other party's cooperation**. And it has a **legitimate interest** in performing (White and Carter).","discharge-frustration"],
["What is the test for frustration?","An event **after** contracting, **not the fault** of either party, **not provided for**. Making performance **impossible**, **illegal** or **radically different**.","discharge-frustration"],
["Does increased cost or difficulty frustrate a contract?","**No**. E.g. labour shortages, a longer route when a canal closes, or market changes.","discharge-frustration"],
["What events can frustrate a contract?","**Destruction** of the subject matter. **Death or incapacity** in personal services. **Supervening illegality**. Cancellation of an event that is the **sole foundation**. **Long delay** or government interference.","discharge-frustration"],
["When does cancellation of an event frustrate a hire contract?","When the event was the **foundation** of the contract known to both. Not if the main purpose can still be achieved (e.g. the fleet cruise could still go ahead).","discharge-frustration"],
["Can a lease be frustrated?","In principle **yes**, but it almost never happens (e.g. not by Brexit).","discharge-frustration"],
["What is self-induced frustration?","An event the party **caused or chose**, e.g. allocating licences or vessels elsewhere. It does **not** frustrate the contract.","discharge-frustration"],
["What is the effect of a force majeure clause?","If the contract **provides for** the event, its terms apply instead of frustration.","discharge-frustration"],
["What is the effect of frustration at common law?","The contract ends **automatically** at the event. Obligations due **after** it are released; earlier ones remain.","discharge-frustration"],
["When could money be recovered at common law after frustration?","Only on a **total failure of consideration**. The 1943 Act now applies.","discharge-frustration"],
["What does s.1(2) of the 1943 Act say about money paid or payable?","Money **paid** before the event is **recoverable**. Money **payable** before the event **ceases to be payable**.","discharge-frustration"],
["What is the expenses proviso in s.1(2)?","The court **may** let the payee keep or recover its **expenses** if **just**. Capped at the sums **paid or payable before** the event.","discharge-frustration"],
["What does s.1(3) of the 1943 Act provide?","A party that obtained a **valuable benefit** (not money) must pay a **just sum**, up to the **value of the benefit**.","discharge-frustration"],
["Can the parties contract out of the 1943 Act?","**Yes** (s.2(3)). Contractual provision for frustration applies instead.","discharge-frustration"],
["Which contracts are outside the 1943 Act?","Most **carriage of goods by sea**. **Insurance**. Sale of **specific goods** that **perish** before risk passes (SGA s.7).","discharge-frustration"],
["What are the four questions in unjust enrichment?","Is the defendant **enriched**? **At the claimant's expense**? Is it **unjust** (an unjust factor)? Any **defence**?","discharge-frustration"],
["Name unjust factors.","**Failure of basis**. **Mistake**. **Duress**. **Undue influence**.","discharge-frustration"],
["What is the change of position defence?","The defendant in **good faith** changed its position in reliance on the receipt. So full repayment would be unfair.","discharge-frustration"],
["How is a benefit valued in unjust enrichment?","**Objectively**: the market value of the services. Not what the defendant subjectively thought.","discharge-frustration"],
["When is a quantum meruit available on termination?","Where there is no contractual right to payment: the contract was **void**, never concluded though work began at request, or completion was **prevented**.","discharge-frustration"],
["Can a party in breach recover advance payments?","It may recover advance payments on **failure of basis**. A genuine **deposit** is normally **forfeited**.","discharge-frustration"],
["What is the aim of contract damages?","**Compensation, not punishment**. They are available **as of right** for every breach. No **punitive** damages.","damages"],
["What do expectation damages do?","Put the claimant in the position as if the contract had been **properly performed**.","damages"],
["What are the two ways of calculating expectation loss?","**Difference in value**. **Cost of cure**.","damages"],
["When is cost of cure not awarded?","When it is **wholly unreasonable** or **out of all proportion** to the benefit of curing. Damages for **loss of amenity** may be awarded instead (Ruxley pool).","damages"],
["What are damages when a seller fails to deliver goods?","**Market price** minus **contract price** at the time delivery was due (SGA s.51).","damages"],
["What are damages when a buyer refuses to accept goods?","**Contract price** minus **market price** at the time acceptance was due (SGA s.50).","damages"],
["What are damages for breach of warranty of goods (SGA s.53)?","The value **as promised** minus the value **as delivered**.","damages"],
["What if there is no available market for the goods?","Damages are assessed on **actual loss**, e.g. lost profit.","damages"],
["Can damages be recovered for loss of a chance?","**Yes**, for a **real and substantial chance**, discounted for probability.","damages"],
["When are nominal damages awarded?","Where there is a breach but **no loss** is proved.","damages"],
["What do reliance damages do?","Compensate **wasted expenditure**, as if the contract had **never been made**. Used where lost profits are **too speculative**.","damages"],
["Can pre-contract expenditure be recovered as reliance loss?","**Yes**, if the defendant must have known it would be **wasted** on breach.","damages"],
["What is the limit on reliance damages?","No escape from a **bad bargain**. If the defendant proves the claimant would not have recovered its spending anyway, damages are **reduced**.","damages"],
["Can damages be recovered for distress caused by breach of contract?","**Generally no** (Addis), e.g. for the manner of dismissal or injured feelings.","damages"],
["When can damages for distress or disappointment be recovered?","Where a **major or important object** is **pleasure, relaxation or peace of mind** (holidays, weddings). Distress from **physical inconvenience**. **Loss of amenity**.","damages"],
["Must peace of mind be the sole object of the contract?","**No**. It is enough that it was **a major or important object** (Farley v Skinner).","damages"],
["What is the causation requirement in contract?","The breach must be an **effective cause** of the loss. It need not be the only cause.","damages"],
["When does an intervening act break the chain of causation?","When it is **unreasonable** or not something the defendant should guard against. **Not** if the duty was precisely to guard against it.","damages"],
["What are the two limbs of the remoteness rule?","**Limb 1**: loss arising **naturally** in the **usual course of things**. **Limb 2**: loss in both parties' **contemplation** at contracting because of **special circumstances** known to the defendant.","damages"],
["Can ordinary lost profits be recovered where unusually lucrative contracts cannot?","**Yes**. Ordinary profits fall in **limb 1**. Specific lucrative contracts the defendant did **not know** of are **too remote**.","damages"],
["What degree of likelihood does the contract remoteness test require?","Loss **not unlikely** or a **serious possibility**. A **higher** degree than tort's reasonably foreseeable test.","damages"],
["Is the type or the extent of loss what must be contemplated?","The **type**. If the type was contemplated, the full **extent** is recoverable (Parsons pigs).","damages"],
["When is assumption of responsibility used in remoteness?","Only in **unusual** cases where the normal test would defeat the parties' or the market's expectations. **Hadley v Baxendale** remains the **standard** test.","damages"],
["When is remoteness judged in contract?","When the **contract was made**. Information given **after** contracting does not count.","damages"],
["Why is contract remoteness stricter than tort?","Contracting parties can **warn** each other of special risks when contracting. A tort victim cannot.","damages"],
["What is the duty to mitigate?","The claimant cannot recover loss it could have **avoided by reasonable steps**. It is not a true duty; failure just **reduces** damages.","damages"],
["Are benefits from mitigation deducted?","**Yes** (e.g. savings from more efficient replacement turbines).","damages"],
["Who bears the burden on mitigation and what standard applies?","The **defendant** must prove failure to mitigate. The standard expected of the claimant is **not high**.","damages"],
["Are costs of mitigation recoverable?","**Yes**, if **reasonable**, even if the attempt fails or increases the loss.","damages"],
["Is refusing a reasonable offer from the party in breach a failure to mitigate?","**Yes**, e.g. refusing cash-on-order supply or an offer of re-employment on the same terms.","damages"],
["What need a claimant not do to mitigate?","Take **risky** steps. Damage its **reputation**. Start complex **litigation** against a third party.","damages"],
["When does the duty to mitigate arise after an anticipatory breach?","Only once the repudiation is **accepted**.","damages"],
["When does contributory negligence reduce contract damages?","Only where the contractual duty is the **same** as an independent **duty of care in tort**. Not for **strict** contractual obligations.","damages"],
["What is a liquidated damages clause?","A clause fixing in advance the sum payable on **breach**. If valid, the **agreed sum** is recovered whether actual loss is higher or lower.","damages"],
["What is the effect of a penalty clause?","It is **unenforceable**. The innocent party recovers only its **actual loss**.","damages"],
["What is the modern penalty test?","A **secondary obligation** imposing a **detriment out of all proportion** to the innocent party's **legitimate interest** in enforcing the primary obligation (Makdessi; ParkingEye).","damages"],
["Can a sum higher than the likely loss be valid liquidated damages?","**Yes**. A **legitimate interest** can go beyond compensation, e.g. protecting goodwill or managing a car park.","damages"],
["How are negotiated clauses between advised parties treated?","Strong presumption that the parties are the **best judges** of what is legitimate.","damages"],
["Does the penalty rule apply to sums payable on a lawful event?","**No**. It applies **only** to sums triggered by **breach**.","damages"],
["Until when do liquidated damages for delay accrue if the contract is terminated?","Up to **termination**. General damages apply after that, unless the clause clearly says otherwise.","damages"],
["Can a deposit be a penalty?","**Yes**, if unreasonably large. **10%** is customary in land sales; **25%** was held a penalty.","damages"],
["How are disproportionate cancellation sums treated in consumer contracts?","They are on the CRA **grey list** and may be **unfair**.","damages"],
["How do equitable remedies differ from damages?","They are **discretionary**: the court can refuse them even if breach is proved. Damages are available **as of right**.","equitable-remedies-guarantees"],
["What is specific performance and the consequence of disobeying it?","An order to **perform** the contract. Disobedience is **contempt of court**.","equitable-remedies-guarantees"],
["What is the basic requirement for specific performance?","**Damages must be inadequate**, typically because the subject matter is **unique** or unobtainable.","equitable-remedies-guarantees"],
["When are damages typically inadequate?","**Land**. **Unique goods** (SGA s.52: specific or ascertained goods). Goods **unobtainable** elsewhere. **Private company shares**. Where damages would be **nominal**. CRA s.58 repair or replacement.","equitable-remedies-guarantees"],
["Why can a promisee's estate get specific performance of a promise to pay a third party?","The estate's own loss is **nominal**, so damages are **inadequate** (Beswick).","equitable-remedies-guarantees"],
["What are the bars to specific performance?","**Personal service**. **Constant supervision**. Lack of **mutuality**. **Unclean hands**. **Delay**. **Severe hardship**. **Volunteer** (no consideration). **Uncertainty** or impossibility.","equitable-remedies-guarantees"],
["Will a court order an employee to work?","**No**. Statute forbids compelling an employee to work (TULRCA s.236).","equitable-remedies-guarantees"],
["Will a court order a business to keep trading under a keep-open covenant?","**Usually no**: it would need **constant supervision** of an **activity**. An order to achieve a **result** (e.g. finish building works) may be granted.","equitable-remedies-guarantees"],
["When does hardship bar specific performance?","Hardship **out of all proportion** to the claimant's benefit, amounting to **injustice**. It need not be caused by the claimant.","equitable-remedies-guarantees"],
["Will equity enforce a gratuitous promise by specific performance?","**No**: equity will not assist a **volunteer**, even if the promise is in a **deed**.","equitable-remedies-guarantees"],
["What can the court award if it refuses specific performance or an injunction?","**Damages in lieu** or in addition (Senior Courts Act 1981 **s.50**). These can cover **future** loss.","equitable-remedies-guarantees"],
["What is the difference between prohibitory and mandatory injunctions?","**Prohibitory**: not to do something. **Mandatory**: do something to **undo** a breach.","equitable-remedies-guarantees"],
["When will a prohibitory injunction be granted to enforce a negative promise?","**Usually**, where there is an **express negative promise** (exclusivity, non-compete, confidentiality). Inadequacy of damages need not be proved.","equitable-remedies-guarantees"],
["When will an injunction be refused in a personal service contract?","If it would in practice **compel performance**: the defendant has **no realistic choice** but to work for the claimant or not at all (e.g. a pop group needing a manager).","equitable-remedies-guarantees"],
["When will an injunction be granted in a personal service contract?","Where the defendant can still **earn a living in other ways** (e.g. an actress, a jockey kept off one rival horse).","equitable-remedies-guarantees"],
["How readily are mandatory injunctions granted?","**Less readily**. The court weighs the defendant's **cost** against the claimant's **benefit**.","equitable-remedies-guarantees"],
["What is the test for an interim injunction?","**Serious question to be tried**. Would **damages** adequately compensate the claimant? Would the claimant's **undertaking in damages** protect the defendant? **Balance of convenience**; if even, preserve the **status quo**.","equitable-remedies-guarantees"],
["What is an action for an agreed sum?","A **debt claim** for a sum **due** under the contract. **Remoteness** and **mitigation** do not apply.","equitable-remedies-guarantees"],
["When can a seller of goods sue for the price?","When **property** has passed to the buyer. Or the price was payable on a **fixed day** (SGA s.49).","equitable-remedies-guarantees"],
["When is an account of profits available for breach of contract?","Only in **exceptional** cases where ordinary remedies are inadequate. And the claimant has a **legitimate interest** in preventing the defendant's profit.","equitable-remedies-guarantees"],
["When are negotiating damages available?","Only where the breach caused loss of a **valuable asset** created or protected by the right (land covenant, IP, confidential information). **Not** for ordinary non-compete breaches with provable loss.","equitable-remedies-guarantees"],
["What is a guarantee?","A promise to a creditor to answer for the **debt, default or miscarriage of another**, if that person fails to perform.","equitable-remedies-guarantees"],
["What is the nature of a guarantor's liability?","**Secondary**: only if the principal debtor **defaults**.","equitable-remedies-guarantees"],
["What formality does a guarantee need?","**In writing** or evidenced by a memorandum, **signed** by the guarantor (Statute of Frauds 1677 **s.4**).","equitable-remedies-guarantees"],
["Can emails satisfy the Statute of Frauds?","**Yes**. Emails read together can suffice, and a **typed name** can be a signature.","equitable-remedies-guarantees"],
["Can estoppel be used to enforce an oral guarantee?","**No**, not merely by relying on the oral promise itself.","equitable-remedies-guarantees"],
["Does a guarantee need consideration?","**Yes**, usually credit given at the guarantor's request. Unless made by **deed**.","equitable-remedies-guarantees"],
["What does co-extensiveness mean for guarantees?","The guarantor's liability is **no greater** than the debtor's. If the main debt is void, unenforceable or reduced, the guarantee is usually affected too. Exception: guarantees of a **minor's** contract.","equitable-remedies-guarantees"],
["When is a guarantor released?","The creditor and debtor **vary the principal contract** without consent (unless **insubstantial**). A **binding agreement to give time**. Release of the debtor or a **co-guarantor**. Loss or release of **security**.","equitable-remedies-guarantees"],
["How do creditors avoid discharging guarantors?","By an **indulgence** (anti-discharge) clause.","equitable-remedies-guarantees"],
["What rights does a guarantor have after paying?","An **indemnity** from the debtor. **Subrogation** to the creditor's rights and security. **Contribution** from co-guarantors.","equitable-remedies-guarantees"],
["What is an indemnity?","A promise to **make good a loss**, whether or not anyone else is liable. Liability is **primary** and **independent**.","equitable-remedies-guarantees"],
["Does an indemnity need to be in writing?","**No**. Statute of Frauds s.4 does not apply.","equitable-remedies-guarantees"],
["Is an indemnity affected if the underlying obligation is void or unenforceable?","**No**, unless its terms say so (e.g. an indemnity for a minor's hire purchase).","equitable-remedies-guarantees"],
["How do you tell a guarantee from an indemnity?","By the **substance**, not the label. **If he does not pay, I will** is a guarantee. **I will see you paid** or I will make good your loss is an indemnity.","equitable-remedies-guarantees"],
["Why do commercial documents combine a guarantee and an indemnity?","If the **guarantee fails**, the creditor can still claim under the **indemnity** as a primary obligation.","equitable-remedies-guarantees"]];

;
window.SQE_QA = window.SQE_QA || {};
window.SQE_QA["contract"] = [
 {
  "t": "offer-acceptance",
  "q": "Brightside Garden Centre displays a hand-carved bench in its shop window with a price label reading £85. The label should have read £850. Mira enters the shop, picks up the label, takes it to the till and says she will buy the bench for £85. The manager refuses to sell it at that price.\n\nWhich of the following best describes the legal position?",
  "o": [
   "There is a contract at £85 because the window display was an offer that Mira accepted at the till.",
   "There is no contract because the display was an invitation to treat and Mira's offer at the till was rejected.",
   "There is a contract at £850 because the court will correct the obvious pricing mistake.",
   "There is no contract because Mira knew or ought to have known of the pricing mistake and so her acceptance was void.",
   "There is a contract at £85 because the shop is bound by the price it chose to advertise to the public."
  ],
  "a": 1,
  "e": "**No contract: the display was an invitation to treat.**\n- Goods displayed in shop windows or on shelves are **invitations to treat**, not offers (**Fisher v Bell**, **Pharmaceutical Society v Boots**).\n- Mira made the **offer** at the till, which the manager was free to **reject**. No acceptance means no contract.\n\nWhy the others are wrong:\n- The display was not an offer, so Mira could not accept it, and the shop is not bound by the advertised price.\n- The court will not create a contract at £850; nothing was agreed at that price.\n- Unilateral mistake (Hartog v Colin and Shields) is irrelevant because no contract was ever formed."
 },
 {
  "t": "offer-acceptance",
  "q": "On 1 March, Halden Ltd wrote to Corin offering to sell him a printing press for £20,000. Corin received the letter on 3 March. On 4 March, Halden posted a letter revoking the offer. On 5 March, Corin posted a properly addressed and stamped letter accepting the offer. Halden's revocation reached Corin on 6 March, and Corin's acceptance reached Halden on 7 March. The offer said nothing about how it should be accepted.\n\nWhich of the following is correct?",
  "o": [
   "No contract was formed because the postal rule applies equally to acceptance and revocation, so the earlier posting prevails.",
   "No contract was formed because Halden's revocation was posted on 4 March, before Corin posted his acceptance.",
   "A contract was formed on 7 March when Halden received Corin's acceptance.",
   "No contract was formed because Corin received the revocation before Halden received the acceptance.",
   "A contract was formed on 5 March when Corin posted his acceptance, because the revocation had not yet been received."
  ],
  "a": 4,
  "e": "**Contract formed on 5 March, when the acceptance was posted.**\n- Under the **postal rule** (**Adams v Lindsell**), an acceptance is effective when **properly posted**, provided post was a reasonable method and the offer did not require actual receipt.\n- A **revocation** is effective only when **received** (**Byrne v Van Tienhoven**). Halden's revocation reached Corin on 6 March, after the contract was formed on 5 March, so it was too late.\n\nWhy the others are wrong:\n- The postal rule does **not** apply to revocation, so posting the revocation on 4 March achieved nothing.\n- Acceptance was not delayed until receipt on 7 March because the postal rule applied.\n- The order in which letters arrived is irrelevant once the acceptance was posted before the revocation was received."
 },
 {
  "t": "offer-acceptance",
  "q": "Tamsin offered by email to sell her vintage van to Leon for £12,000, saying the offer was open for a week. Leon replied the next day: 'I'll give you £10,500 for it.' Tamsin replied: 'No, I will not take £10,500.' Two days later, before the week had expired, Leon emailed: 'Fine, I accept your offer of £12,000.' Tamsin has since had a better offer and refuses to sell to Leon.\n\nWhat is the best advice to Leon?",
  "o": [
   "He has a contract because Tamsin's reply rejecting his counter-offer revived the original offer automatically.",
   "He has a contract because he accepted within the week during which Tamsin promised to keep her offer open.",
   "He has no contract because his counter-offer of £10,500 rejected and destroyed Tamsin's original offer.",
   "He has no contract because acceptance by email takes effect only when the offeror reads it.",
   "He has a contract because his first reply was merely a request for information about the price."
  ],
  "a": 2,
  "e": "**No contract: the counter-offer destroyed the original offer.**\n- Leon's reply 'I'll give you £10,500' proposed **new terms**. It was a **counter-offer** that **rejected** Tamsin's offer (**Hyde v Wrench**). The original offer could not later be accepted.\n- Tamsin's reply simply refused the counter-offer and made no fresh offer, so Leon's later 'acceptance' was at most a new offer, which Tamsin can refuse.\n\nWhy the others are wrong:\n- Rejecting a counter-offer does not revive the original offer.\n- A promise to keep an offer open is not binding without consideration, and in any event the offer had been rejected.\n- A counter-offer naming a different price is not a request for information (contrast **Stevenson v McLean**).\n- The timing of email receipt does not matter because there was no live offer to accept."
 },
 {
  "t": "offer-acceptance",
  "q": "Ashgrove Ltd posted an online notice offering £5,000 to anyone who recovers its stolen prototype drone and returns it to its office. Priya tracked the drone to a storage unit and spent three days arranging access and transport. As she was driving it to Ashgrove's office, Ashgrove posted a further notice withdrawing the reward. Priya delivered the drone an hour later.\n\nWhich of the following best describes Priya's position?",
  "o": [
   "She is entitled to £5,000 because Ashgrove could not revoke its offer once she had started performance.",
   "She is not entitled to the reward because Ashgrove revoked its offer before she completed the act requested.",
   "She is entitled to a reasonable sum for her work, but not the full reward, because the offer was revoked.",
   "She is not entitled to the reward because she never communicated her acceptance to Ashgrove.",
   "She is entitled to the reward only if she saw the original notice and the revocation notice at the same time."
  ],
  "a": 0,
  "e": "**She is entitled to the £5,000.**\n- The notice was a **unilateral offer**: a promise in exchange for an act.\n- Acceptance is by **performance**; there is **no need to communicate acceptance** in advance.\n- Once the offeree has **started performance**, the offeror **cannot revoke** (**Errington v Errington**, **Daulia v Four Millbank**). Priya had begun, and was close to completing, the act when Ashgrove tried to withdraw.\n\nWhy the others are wrong:\n- Revocation before completion is ineffective once performance has begun.\n- She is entitled to the agreed reward on completion, not merely a reasonable sum.\n- Communication of acceptance is not needed in a unilateral contract.\n- The timing of her seeing the notices is irrelevant beyond her knowing of the offer when she acted."
 },
 {
  "t": "consideration",
  "q": "Kestrel Developments contracted with Owain, a joiner, to fit out 20 flats for £40,000. Halfway through, Owain told Kestrel he was in financial difficulty and might not finish. Kestrel faced a penalty under its own contract with the building owner if the flats were late, so it promised Owain an extra £500 per completed flat. Owain completed the work on time. Kestrel now refuses to pay the extra money, saying Owain only did what he was already bound to do. There was no threat or pressure from Owain.\n\nWhich of the following best describes Kestrel's promise?",
  "o": [
   "It is not binding because promissory estoppel can only be used as a shield and not as a sword.",
   "It is not binding because performing an existing contractual duty owed to the promisor can never be consideration.",
   "It is binding only if Owain did more work than the original contract required.",
   "It is binding because Kestrel obtained a practical benefit from Owain's completion and there was no economic duress.",
   "It is binding only because Kestrel's promise was made in writing and signed."
  ],
  "a": 3,
  "e": "**Binding: practical benefit.**\n- Under **Williams v Roffey Bros**, a promise to pay **more** for performance of an existing contractual duty is supported by consideration where:\n  - the promisor had reason to doubt the other would complete;\n  - the promisor obtains a **practical benefit** (here, avoiding the **penalty** and the cost of finding a replacement); and\n  - there was **no economic duress or fraud**.\n- All of these are satisfied.\n\nWhy the others are wrong:\n- **Stilk v Myrick** has been refined by Williams v Roffey; the absolute rule no longer applies to promises to pay more.\n- Owain need not exceed his duties (that was the Hartley v Ponsonby exception, not needed here).\n- Owain relies on contract, not estoppel.\n- Writing is not required for consideration."
 },
 {
  "t": "consideration",
  "q": "Fenwick Properties let a shop to Gemma at £24,000 a year. When a road closure badly hit trade, Fenwick wrote to Gemma: 'We will accept half rent while the roadworks continue.' Gemma relied on this and paid half rent for ten months. The roadworks have now finished. Fenwick demands the unpaid half of the rent for the ten months and full rent from now on.\n\nWhat is the best advice to Gemma?",
  "o": [
   "Fenwick can recover the arrears because part payment of a debt is never good consideration for a promise to accept less.",
   "Fenwick cannot recover the arrears for the ten months, but can require full rent for the future now the roadworks have ended.",
   "Fenwick cannot recover the arrears or require full rent in future, because its promise permanently varied the lease.",
   "Fenwick can recover the arrears because practical benefit does not apply to promises to accept less.",
   "Fenwick cannot recover the arrears because Gemma provided practical benefit by staying on as tenant."
  ],
  "a": 1,
  "e": "**Arrears not recoverable; full rent can resume for the future.**\n- **Promissory estoppel** (**High Trees**, **Hughes v Metropolitan Railway**): Fenwick made a **clear promise** not to enforce its full rights within an existing contract. Gemma **relied** on it, and it would be **inequitable** to go back on it for the past period.\n- Estoppel is usually **suspensory**: Fenwick can resume its full rights for the **future**, on reasonable notice or once the circumstances the promise was based on have ended.\n\nWhy the others are wrong:\n- **Foakes v Beer** would otherwise apply, but estoppel prevents recovery of the past arrears.\n- **Re Selectmove** means practical benefit cannot support a promise to accept less, so Gemma relies on estoppel instead.\n- The promise was limited to the roadworks period, so it did not permanently vary the lease."
 },
 {
  "t": "consideration",
  "q": "Dariusz, a web designer, asked Hollis Ltd's managing director whether he could redesign Hollis's website. The director said 'go ahead'. Nothing was said about payment. After Dariusz had finished and Hollis had launched the new site, the director promised to pay him £3,000. Hollis now refuses to pay, saying the work was done before the promise was made.\n\nWhich of the following is correct?",
  "o": [
   "Dariusz can enforce the promise only if it was made by deed.",
   "Dariusz cannot enforce the promise because past consideration is never good consideration.",
   "Dariusz can enforce the promise only if he can show that Hollis obtained a practical benefit from the work.",
   "Dariusz cannot enforce the promise because there was no intention to create legal relations when the work was requested.",
   "Dariusz can enforce it: the work was requested and both parties expected it to be paid for."
  ],
  "a": 4,
  "e": "**Enforceable under the exception to past consideration.**\n- Past consideration is generally no good (**Re McArdle**), but under **Lampleigh v Brathwait** and **Pao On v Lau Yiu Long** a past act is good consideration if:\n  - it was done at the **promisor's request**;\n  - both parties **understood** it would be **paid for**; and\n  - a promise to pay, if made in advance, would have been **legally enforceable**.\n- Professional work requested in a business context is understood to be paid for, so the later promise fixes the amount.\n\nWhy the others are wrong:\n- The rule against past consideration has this well-established exception.\n- Practical benefit concerns promises to pay more for an existing duty.\n- Commercial dealings carry a presumption of intention to create legal relations.\n- A deed is not required where consideration exists."
 },
 {
  "t": "intention-certainty-capacity",
  "q": "Alana and Rob, a married couple, separated. Before Rob moved out, they signed a written agreement under which Rob would pay Alana £600 a month towards the mortgage on the family home, and Alana would pay the remaining mortgage. Once the mortgage was paid off, Rob would transfer his share of the house to her. Alana has paid the mortgage off, but Rob refuses to transfer his share, saying it was only a family arrangement.\n\nWhich of the following best describes the position?",
  "o": [
   "The agreement is binding only if Alana can prove that Rob received independent legal advice before signing it.",
   "The agreement is not binding because agreements between spouses are always presumed not to be intended to create legal relations.",
   "It is likely binding, because separating spouses who put terms in writing rebut the presumption.",
   "The agreement is not binding because Alana gave no consideration for Rob's promise to transfer his share.",
   "The agreement is binding because all written agreements are presumed to be intended to create legal relations."
  ],
  "a": 2,
  "e": "**Likely binding.**\n- **Domestic** agreements are **presumed not** to be intended to create legal relations (**Balfour v Balfour**).\n- The presumption is **rebuttable**. Where spouses are **separating** and deal at arm's length, especially in **writing**, an intention to be bound is readily found (**Merritt v Merritt**, on very similar facts).\n\nWhy the others are wrong:\n- The presumption is not absolute and is rebutted here.\n- Independent legal advice is not a requirement for intention.\n- Alana provided consideration by paying off the mortgage.\n- Writing helps rebut the presumption but does not create a general presumption of intention on its own."
 },
 {
  "t": "intention-certainty-capacity",
  "q": "Jago, aged 17, works as a trainee chef. He buys on credit from Brightwells, a department store, a set of professional knives for his work at a reasonable price, and also a £1,500 designer leather jacket. He already owns several jackets. He has paid for neither item and has worn the jacket only once.\n\nWhich of the following best describes Brightwells' position?",
  "o": [
   "It can recover a reasonable price for the knives, but cannot sue for the price of the jacket, although the court may order Jago to return it.",
   "It can recover the full contract price for both items, because Jago was working and earning a wage.",
   "It cannot recover anything, because no contract is ever enforceable against a person under 18.",
   "It can recover the price of the jacket, but not the knives, because tools for work are never necessaries.",
   "It can recover the price of both items only if Jago affirms the contracts within a reasonable time after turning 18."
  ],
  "a": 0,
  "e": "Contracts are generally **not enforceable against a minor**, but a minor must pay a **reasonable price** for **necessaries**: goods suitable to his condition in life and **actual requirements** at the time. Work knives for a trainee chef are likely necessaries; a luxury jacket when he already has plenty is not. Under the **Minors' Contracts Act 1987 s.3** the court may order the jacket returned if just and equitable. Ratification after 18 could make the jacket contract enforceable, but it is not a precondition for recovering a reasonable price for the knives, and nothing suggests Jago has ratified."
 },
 {
  "t": "privity-third-parties",
  "q": "Clara contracted with Norland Builders to build an extension. The contract said that Norland's obligation to remedy defects for five years 'may be enforced by Clara's daughter, Ines, as a future owner of the property'. Ines wrote to Norland stating that she agreed to and would rely on this term. Later Clara and Norland agreed to delete the term in exchange for a price reduction. The contract says nothing about variation. Defects have now appeared.\n\nWhat is the best advice to Ines?",
  "o": [
   "She cannot enforce the term because the parties are always free to vary a contract between themselves.",
   "She cannot enforce the term because she is not a party to the contract and the doctrine of privity applies.",
   "She can enforce the term only if she gave consideration to Norland for it.",
   "She can enforce the term, because her assent had reached Norland before the variation.",
   "She can enforce the term only if she became owner of the property before the contract was made."
  ],
  "a": 3,
  "e": "**She can enforce the term.**\n- Under **s.1(1)(a) Contracts (Rights of Third Parties) Act 1999**, a third party may enforce a term that **expressly** says she may. Ines is **expressly identified** by name (s.1(3)).\n- Under **s.2**, once the third party has **communicated her assent** to the promisor, the parties **cannot vary or rescind** the contract to extinguish her rights **without her consent**, unless the contract allows it. It does not.\n\nWhy the others are wrong:\n- Privity is displaced by the 1999 Act.\n- A third party need not give consideration.\n- The parties' freedom to vary is limited by s.2.\n- A third party need not own anything, or even exist, when the contract is made."
 },
 {
  "t": "privity-third-parties",
  "q": "Marta pays Greenleaf Ltd to landscape her garden. The written contract states: 'Greenleaf will also lay a new path for Marta's neighbour, Tom Reid, at 4 Elm Road.' The contract says nothing else about Tom. Greenleaf lays Marta's garden but refuses to lay Tom's path. Tom wants to sue Greenleaf.\n\nWhich of the following best describes Tom's position?",
  "o": [
   "He cannot sue, because he gave no consideration to Greenleaf.",
   "He can sue, because the term purports to benefit him, he is named and nothing shows the parties intended otherwise.",
   "He can sue only if he has communicated his assent to the term to Greenleaf.",
   "He cannot sue, because only Marta, as the contracting party, can enforce the contract.",
   "He can sue only if the contract expressly mentions the Contracts (Rights of Third Parties) Act 1999."
  ],
  "a": 1,
  "e": "Under **s.1(1)(b) C(RTP)A 1999** a third party may enforce a term that **purports to confer a benefit** on him, if he is **expressly identified** (s.1(3)). The presumption that he may enforce is rebutted only if the contract shows the parties **did not intend** that (s.1(2)), and **silence is not enough**. Express mention of the Act is needed only for the separate s.1(1)(a) route, and assent matters only for whether the parties can later vary the term."
 },
 {
  "t": "express-terms",
  "q": "Jasper booked a room at the Brook Hotel at the reception desk and paid in full. When he got to his room, he saw a notice on the wardrobe door: 'The hotel accepts no liability for any items stolen from rooms, however caused.' Jasper's laptop was stolen from his room because a member of staff carelessly left the door unlocked. Jasper had never stayed at the hotel before.\n\nCan the hotel rely on the notice?",
  "o": [
   "Yes, because Jasper accepted the term by conduct when he continued to use the room.",
   "Yes, because Jasper had reasonable notice of the term before the theft occurred.",
   "Yes, because the term is reasonable under the Unfair Contract Terms Act 1977.",
   "No, because a clause excluding liability for negligence is automatically void in every contract.",
   "No, because the notice was not brought to Jasper's attention until after the contract had been made."
  ],
  "a": 4,
  "e": "**No: the term was not incorporated.**\n- Notice of a term must be given **before or at the time** the contract is made (**Olley v Marlborough Court Hotel**, almost identical facts). The contract was made at **reception**; the notice in the room came too late.\n- There was no prior course of dealing to incorporate it.\n\nWhy the others are wrong:\n- Notice before the theft is irrelevant; what matters is notice before contracting.\n- The statutory controls (here the **CRA 2015**, as Jasper is a consumer) only matter if the term is incorporated.\n- Exclusion of negligence liability is only automatically void for death or personal injury; for property damage it is subject to fairness or reasonableness.\n- Continuing to use the room does not amount to agreeing to a new term."
 },
 {
  "t": "express-terms",
  "q": "Sabine, a consumer, has had her car serviced at Westway Motors three times in the last four years. Each time she signed a form at collection containing a clause excluding liability for damage to vehicles 'however caused'. On her fourth visit, she booked the service by phone and signed nothing. A mechanic negligently damaged her car while it was at the garage.\n\nWhich of the following best describes whether the clause is part of the fourth contract?",
  "o": [
   "It is incorporated because a consumer is deemed to know the standard terms of any business she has used before.",
   "It is incorporated, because she had signed a form containing the same clause on each previous occasion.",
   "It is unlikely to be incorporated, as three dealings in four years is not a regular course of dealing.",
   "It is unlikely to be incorporated because course of dealing can never apply to consumer contracts.",
   "It is incorporated because Westway's standard terms apply automatically unless the customer expressly rejects them."
  ],
  "a": 2,
  "e": "**Unlikely to be incorporated.**\n- Terms can be incorporated by a **course of dealing**, but the dealings must be **regular and consistent** (**McCutcheon v MacBrayne**).\n- In **Hollier v Rambler Motors**, three or four dealings over five years did **not** amount to a course of dealing with a **consumer**. Sabine's three services in four years look similar. The previous forms were also signed at **collection**, after each contract was made.\n\nWhy the others are wrong:\n- Signing on earlier occasions is not enough without a regular and consistent course of dealing.\n- There is no rule that consumers are deemed to know a business's terms.\n- Course of dealing can apply to consumers, but rarely does on facts like these.\n- Standard terms are not incorporated automatically.\n- Even if incorporated, the clause would face the CRA 2015 fairness test."
 },
 {
  "t": "express-terms",
  "q": "Quayside Shipping chartered a vessel from Orme Ltd for 12 months. The charter required the vessel to be 'in every way fitted for ordinary cargo service'. Because of an inefficient engine crew, the vessel was out of service for repairs for five weeks in the first three months. It was then fully repaired and seaworthy for the remaining nine months. Quayside wants to terminate the charter. The contract does not say what happens on breach of this obligation.\n\nWhich of the following is the best advice to Quayside?",
  "o": [
   "It may claim damages only, as the breach did not deprive it of substantially the whole benefit.",
   "It may terminate and claim damages, because the obligation to provide a seaworthy vessel is a condition.",
   "It may terminate but cannot claim damages, because termination is an alternative to damages.",
   "It may claim damages only, because the obligation is a warranty and breach of a warranty never allows termination.",
   "It may terminate, because any breach of an express term in a commercial contract is repudiatory."
  ],
  "a": 0,
  "e": "**Damages only: innominate term, breach not serious enough.**\n- On facts like **Hong Kong Fir Shipping**, a seaworthiness obligation is an **innominate term**: it can be broken in trivial or serious ways.\n- Whether the innocent party can terminate depends on whether the breach **deprives it of substantially the whole benefit** of the contract. Five weeks out of twelve months, with the ship then fully fit, does not.\n\nWhy the others are wrong:\n- The term has not been classified by statute, the contract or case law as a condition.\n- Where termination is justified, the innocent party may terminate **and** claim damages.\n- It is not a warranty; it is innominate.\n- Not every breach of an express term is repudiatory."
 },
 {
  "t": "express-terms",
  "q": "A supply contract professionally drafted for two companies provides that the price 'shall increase by 8% compounded annually'. Ten years on, the buyer argues that the clause should be read as a simple (non-compounding) increase, because the compound figure has become commercially absurd. Emails from the negotiations show that the seller's negotiator once suggested a simple increase.\n\nHow is the court most likely to interpret the clause?",
  "o": [
   "As a simple increase, because the court will prefer the commercially sensible meaning.",
   "As a simple increase, because the negotiation emails show what the parties really intended.",
   "As a simple increase, because ambiguous terms are read against the party relying on them.",
   "As a compound increase, because the words are clear and the court will not rewrite a bad bargain.",
   "As void for uncertainty, because the parties never agreed how the increase would work."
  ],
  "a": 3,
  "e": "The **natural and ordinary meaning** of clear words is the most important factor, and **commercial common sense** cannot be used to escape clear language just because the bargain has turned out badly for one side. Business common sense decides only where words are genuinely open to **two meanings**. **Pre-contract negotiations** are inadmissible to interpret a contract, and contra proferentem applies only to real ambiguity."
 },
 {
  "t": "implied-terms",
  "q": "Nadia, a consumer, bought a new washing machine from Hartwell Appliances. Three weeks after delivery, it started leaking because of a manufacturing fault. Nadia contacted Hartwell straight away and said she wanted her money back. Hartwell offered to repair the machine instead.\n\nWhat is the best advice to Nadia?",
  "o": [
   "She must accept a repair first, because a consumer can only reject goods after one failed repair or replacement.",
   "She can insist on a full refund because she is exercising her short-term right to reject within 30 days of delivery.",
   "She can obtain a refund, but Hartwell may deduct an amount for the three weeks' use.",
   "She can only claim damages from the manufacturer, because the fault was a manufacturing defect.",
   "She must prove that the fault existed at the time of delivery before she can claim any remedy."
  ],
  "a": 1,
  "e": "**Full refund under the short-term right to reject.**\n- Under the **Consumer Rights Act 2015**, goods must be of **satisfactory quality** (s.9). A leaking new machine is not.\n- The consumer has a **short-term right to reject** for **30 days** from delivery (ss.20-22), giving a **full refund** with **no deduction** for use. Nadia acted within three weeks.\n\nWhy the others are wrong:\n- Repair or replacement is an alternative she may choose; she need not try it first while the 30-day right lasts.\n- Deduction for use only applies to the **final** right to reject, and not within 6 months of delivery.\n- Her contract is with the retailer; the CRA claim lies against Hartwell, whoever caused the fault.\n- A fault appearing within **6 months** is **presumed** present at delivery."
 },
 {
  "t": "implied-terms",
  "q": "Ravi, a consumer, buys a new laptop from TechHouse for £1,200. Ten weeks after delivery the screen fails. TechHouse says Ravi must prove the fault was there when he bought it, and that in any event it will only repair it. Ravi wants a full refund.\n\nWhat is the best advice to Ravi?",
  "o": [
   "He can reject the laptop for a full refund, because it failed within six months.",
   "He must prove the fault existed at delivery before claiming any remedy.",
   "He has no remedy against TechHouse and must claim against the manufacturer.",
   "He can obtain a refund less a deduction for ten weeks' use.",
   "He can require repair or replacement, and the fault is presumed to have existed at delivery."
  ],
  "a": 4,
  "e": "The **30-day short-term right to reject** has expired, so Ravi's first remedy is **repair or replacement**, which he may choose subject to proportionality. Because the fault appeared within **6 months** of delivery, it is **presumed** to have existed at delivery unless TechHouse proves otherwise. Only after **one failed** repair or replacement can he claim a price reduction or the **final right to reject**. The claim lies against the trader, not the manufacturer."
 },
 {
  "t": "implied-terms",
  "q": "Oakwell Ltd, a printing company, sells one of its old delivery vans to Saffron, a florist, for use in her business. Oakwell has never sold a vehicle before. Within a week, the van's gearbox fails because of a defect that existed at the sale and was not pointed out. Oakwell says it gave no promise about quality because it is not a car dealer.\n\nWhich of the following best describes the position?",
  "o": [
   "There is no implied term about quality, because Oakwell does not normally sell vans.",
   "The Consumer Rights Act 2015 applies, because Saffron is a small business owner.",
   "There is an implied condition of satisfactory quality, because Oakwell sold the van in the course of a business.",
   "There is an implied term about quality only if Saffron told Oakwell of a particular purpose.",
   "There is no implied term about quality, because the sale was between two businesses."
  ],
  "a": 2,
  "e": "**SGA 1979 s.14(2)** implies a condition of **satisfactory quality** where the seller sells **in the course of a business**, and this covers **any** sale by a business, even a one-off sale of its own old equipment. The CRA does not apply because Saffron buys for her business, so she is not a consumer. Fitness for a particular purpose under s.14(3) is a separate term and is not needed here."
 },
 {
  "t": "exemption-clauses",
  "q": "Corbel Ltd sells industrial ovens to bakeries on its written standard terms. Clause 12 limits Corbel's liability for defects to replacing faulty parts and excludes liability for lost profits. Tasker Bakeries bought an oven, which failed because of a design fault, causing Tasker substantial lost profits. Tasker had no real opportunity to negotiate the terms, and Corbel had insurance covering such losses.\n\nWhich of the following is correct?",
  "o": [
   "Clause 12 is effective only if Corbel proves it was reasonable when the contract was made.",
   "Clause 12 is void because a business cannot exclude the implied term that goods are of satisfactory quality.",
   "Clause 12 is effective unless Tasker proves that it was unreasonable at the time the oven failed.",
   "Clause 12 is subject to the fairness test in the Consumer Rights Act 2015 because Tasker dealt on Corbel's standard terms.",
   "Clause 12 is valid because UCTA 1977 does not apply to contracts between businesses."
  ],
  "a": 0,
  "e": "**Effective only if Corbel proves it is reasonable.**\n- This is a **B2B** sale on **standard terms**, so **UCTA 1977** applies. Under **s.6**, the implied terms in **ss.13-15 SGA** (including satisfactory quality) can be excluded or restricted only so far as **reasonable**; s.3 also applies to standard terms.\n- Under **s.11**, reasonableness is judged at the **time of contracting**, and the **burden** is on the party relying on the clause. Relevant factors include unequal bargaining power and Corbel's **insurance**, which point against reasonableness.\n\nWhy the others are wrong:\n- Only s.12 SGA (title) can never be excluded.\n- The burden is on Corbel, and the time is when the contract was made, not the breach.\n- The CRA applies to consumer contracts only.\n- UCTA does apply between businesses."
 },
 {
  "t": "exemption-clauses",
  "q": "Hannah, a consumer, joins Peak Fitness. The standard membership terms, which she signs, state: (1) 'Peak Fitness accepts no liability for any injury caused by the negligence of its staff', and (2) 'The monthly fee is £45', which is shown in large print on the sign-up page. Hannah is injured when an instructor negligently sets up equipment. She also now thinks the fee is too high.\n\nWhich of the following best describes the position?",
  "o": [
   "Both clauses must be tested for reasonableness under the Unfair Contract Terms Act 1977.",
   "Both clauses are binding because Hannah signed the terms.",
   "Clause 1 is binding if it is fair, and clause 2 is not binding because the price is excessive.",
   "Clause 1 is not binding, and the fairness of the fee cannot be assessed.",
   "Clause 1 is subject to the fairness test, and clause 2 is on the grey list."
  ],
  "a": 3,
  "e": "Under **CRA 2015 s.65** a trader cannot exclude liability for **death or personal injury** caused by **negligence**, so clause 1 is not binding. Under **s.64** the **price** cannot be assessed for fairness if the term is **transparent** and **prominent**, as it is here. UCTA does not apply to consumer contracts, and signing does not save a blacklisted term."
 },
 {
  "t": "exemption-clauses",
  "q": "Bexley Ltd and Corda plc, two large companies, negotiate a software supply contract over several months with legal advice on both sides. Bexley accepts a lower price in return for a clause limiting Corda's liability to the contract price. Both companies could insure against the risk. The software fails and Bexley's loss is ten times the contract price.\n\nWhich of the following best describes the limitation clause?",
  "o": [
   "It is void, because liability for defective software cannot be limited between businesses.",
   "It is likely to satisfy the reasonableness test.",
   "It is likely to be unreasonable, because the cap turned out to be far below the actual loss Bexley suffered.",
   "It is subject to the Consumer Rights Act 2015 fairness test.",
   "It is effective without any test, because UCTA 1977 applies only to written standard terms."
  ],
  "a": 1,
  "e": "Where UCTA applies to a limitation clause between businesses, for example under **s.6(1A)** if the software is supplied as goods or **s.2(2)** for negligence (s.3 applies only to written standard terms), the clause must satisfy the **reasonableness test**, judged **when the contract was made**, with the burden on the party relying on it. Where experienced businesses of **equal bargaining power** negotiate terms with advice, the court is **very slow to interfere**, and a **lower price** and the ability to **insure** point to reasonableness. Comparing the cap with the actual loss uses hindsight, which is the wrong time to judge. UCTA controls more than standard terms, so it is wrong to say no test can apply."
 },
 {
  "t": "misrepresentation",
  "q": "Isaac was buying a commercial unit from Varley Estates. Before contracts were exchanged, Varley's agent told Isaac that the unit had planning permission for use as a gym. Varley had never checked, and the agent had simply assumed it. There was no such permission. Isaac bought the unit and fitted it out as a gym, then had to close after the council took enforcement action. Some of Isaac's losses were not reasonably foreseeable.\n\nWhich claim gives Isaac the best prospect of recovering all his losses?",
  "o": [
   "A claim for breach of contract, because all pre-contract statements become terms of the contract.",
   "A claim for negligent misstatement at common law, because damages are limited to reasonably foreseeable losses.",
   "A claim for damages in lieu of rescission under s.2(2) Misrepresentation Act 1967, because the statement was wholly innocent.",
   "A claim in the tort of deceit, because Varley was careless about whether the statement was true.",
   "A claim under s.2(1) Misrepresentation Act 1967, with the fraud measure of damages."
  ],
  "a": 4,
  "e": "**A s.2(1) Misrepresentation Act 1967 claim.**\n- The agent made a **false statement of fact** that **induced** the contract.\n- Under **s.2(1)**, Varley is liable unless **it proves** it had **reasonable grounds to believe** and did believe the statement was true. An unchecked assumption is unlikely to be enough.\n- Damages are on the **fraud measure** (**Royscot Trust v Rogerson**): **all direct loss**, even if unforeseeable.\n\nWhy the others are wrong:\n- Common law negligence requires Isaac to prove a duty and breach and limits recovery to foreseeable loss.\n- The statement was not wholly innocent, and s.2(2) damages are discretionary and generally smaller.\n- Deceit requires fraud (knowledge, no belief or **recklessness**); mere carelessness is not enough (**Derry v Peek**).\n- Not every pre-contract statement becomes a term."
 },
 {
  "t": "misrepresentation",
  "q": "Felix sold his rare guitar to Milo after Milo falsely told him he was a professional musician who would use it on a world tour, which persuaded Felix to accept a lower price. Milo paid in full and, two weeks later, sold the guitar to Ruth, who paid the market price and knew nothing of the earlier deal. Felix has now discovered the truth and wants the guitar back.\n\nWhat is the best advice to Felix?",
  "o": [
   "He can recover the guitar from Ruth because the right to rescind for fraud is never lost.",
   "He can recover the guitar from Ruth because Milo's fraudulent misrepresentation made the contract void.",
   "He cannot recover the guitar from Ruth, but he can claim damages from Milo.",
   "He cannot claim any remedy because Milo's statement about his future intentions was not a statement of fact.",
   "He can recover the guitar from Ruth, because she did not ask Milo how or from whom he had obtained it."
  ],
  "a": 2,
  "e": "**Rescission barred by third party rights; damages against Milo.**\n- Misrepresentation makes a contract **voidable**, not void. Milo obtained good title, which he passed to Ruth before Felix rescinded.\n- Rescission is barred where an innocent **third party** has acquired rights **in good faith and for value**.\n- Felix can still sue Milo in **deceit** (or under s.2(1)) for damages.\n\nWhy the others are wrong:\n- Fraud makes the contract voidable, not void.\n- The right to rescind can be lost, including for fraud, through the usual bars.\n- A false statement of present intention or status is a statement of fact (**Edgington v Fitzmaurice**); Milo also lied about being a professional musician.\n- A good faith purchaser is not required to make inquiries."
 },
 {
  "t": "misrepresentation",
  "q": "In January, Celia tells Ivo, who is buying her florist business, that it has a contract to supply a local hotel worth £30,000 a year. This is true. In March the hotel terminates the contract. Celia says nothing, and Ivo completes the purchase in April, relying on the figure. He discovers the truth in May and immediately writes to rescind.\n\nWhich of the following best describes Ivo's position?",
  "o": [
   "He can rescind for misrepresentation, as Celia failed to correct her statement.",
   "He has no claim, because a seller has no general duty to disclose information.",
   "He has no claim, because he could have checked the position before completion.",
   "He can claim only for breach of contract, because the statement was about an existing contract.",
   "He has no claim, because Celia's statement was true when she made it."
  ],
  "a": 0,
  "e": "Silence is not usually a misrepresentation, but a statement that is true when made and becomes **false before the contract** must be **corrected**. Celia's silence makes her earlier statement a misrepresentation, and Ivo relied on it. It is no defence that he could have discovered the truth, and he acted promptly, so rescission is not barred by delay or affirmation."
 },
 {
  "t": "mistake-duress-ui-illegality",
  "q": "Lowther Foods had a contract to buy packaging from Pressco Ltd at a fixed price for two years. After six months, Pressco said it would stop deliveries immediately unless Lowther agreed to a 30% price increase. Lowther could not find another supplier in time to meet orders, so it signed a variation agreeing to the increase, protesting in writing. Lowther then paid the higher price without complaint for eight months, after alternative suppliers had become available. It now wants to recover the extra payments.\n\nWhich of the following best describes Lowther's position?",
  "o": [
   "The variation is valid because Lowther protested in writing, which shows it acted voluntarily.",
   "The variation is void for economic duress, so Lowther can recover all the extra payments regardless of its later conduct.",
   "There was no economic duress because a threat to break a contract is legitimate commercial pressure.",
   "There was economic duress, but Lowther has probably affirmed the variation by its later conduct.",
   "The variation is unenforceable because Lowther gave no consideration for it, so the extra payments must be repaid."
  ],
  "a": 3,
  "e": "**Economic duress, but probably affirmed.**\n- **Economic duress** requires **illegitimate pressure** (a threat to break the contract usually is) which was a **significant cause** of entering the variation. Lowther had **no practical alternative** and protested, so duress is likely.\n- Duress makes a contract **voidable**, not void. The right to set it aside is lost by **affirmation**. Paying without protest for a long period after the pressure ended amounts to affirmation (**The Atlantic Baron**).\n\nWhy the others are wrong:\n- Duress makes a contract voidable, so later conduct matters.\n- A threat to break a contract to extract more money is generally illegitimate.\n- Protest supports a duress claim; it does not show free consent.\n- The consideration issue is overtaken: the claim to recover fails because the variation was affirmed."
 },
 {
  "t": "mistake-duress-ui-illegality",
  "q": "Erin agreed to guarantee the business overdraft of her husband's company with Hallmark Bank, and to secure it with a charge over their jointly owned home. Hallmark knew Erin had no financial interest in the company. Hallmark sent the documents to the husband and asked him to arrange for Erin to sign. A solicitor recommended by the husband met them together for ten minutes, and Erin signed. The bank never communicated with Erin or asked for confirmation from a solicitor. Erin now says her husband pressured her.\n\nWhich of the following is correct?",
  "o": [
   "Hallmark is unaffected by any undue influence because it was not the party that exerted it.",
   "If she proves her husband's undue influence, she can set the charge aside against Hallmark.",
   "Erin can set aside the charge only if she proves that Hallmark itself exercised undue influence over her.",
   "Undue influence is presumed between husband and wife, so the charge is automatically void.",
   "Hallmark is protected because a solicitor met Erin and her husband before she signed the documents."
  ],
  "a": 1,
  "e": "**She can set aside the charge against Hallmark if undue influence is proved.**\n- Under **RBS v Etridge (No 2)**, a lender is **put on inquiry** whenever a wife stands **surety** for her husband's or his company's debts in a non-commercial relationship.\n- The lender must take **reasonable steps**: contact the wife **directly**, ask her to nominate a solicitor, give the solicitor the financial information and obtain **written confirmation** that she was advised. Hallmark did none of this, so it has **constructive notice** of the husband's wrongdoing.\n- The solicitor should have seen Erin **alone**, explained the risks and her choice. A short joint meeting falls short.\n\nWhy the others are wrong:\n- A lender can be affected by a third party's undue influence through constructive notice.\n- Erin need not prove the bank's own wrongdoing.\n- There is no automatic presumption between spouses, and undue influence makes a transaction voidable, not void.\n- The solicitor's meeting did not meet Etridge, and the bank never obtained confirmation."
 },
 {
  "t": "mistake-duress-ui-illegality",
  "q": "On 3 June, Odette agreed to buy a specific consignment of 500 crates of mangoes from Patel Imports, which both believed were in a warehouse at Felixstowe. Unknown to either, the mangoes had been destroyed by a warehouse fire on 1 June. Odette had paid a deposit.\n\nWhat is the legal position?",
  "o": [
   "The contract is valid but Odette bears the risk because she had agreed to buy the goods.",
   "The contract is frustrated because the goods were destroyed, and the Law Reform (Frustrated Contracts) Act 1943 applies.",
   "The contract is valid and Patel Imports is in breach for failing to deliver the goods.",
   "The contract is voidable for misrepresentation because Patel Imports represented that the goods existed.",
   "The contract is void for common mistake because the goods had perished before the contract was made, so Odette can recover her deposit."
  ],
  "a": 4,
  "e": "**Void for common mistake (res extincta).**\n- Where both parties contract on the shared mistaken belief that the subject matter exists, and it had already **perished** before the contract, the contract is **void** (**Couturier v Hastie**; **s.6 Sale of Goods Act 1979** for specific goods).\n- Money paid under a void contract is recoverable (total failure of basis).\n\nWhy the others are wrong:\n- **Frustration** concerns events **after** the contract is made. The fire was before.\n- There is no breach if the contract is void, unless the seller had warranted the goods' existence (**McRae**), which these facts do not suggest.\n- Patel genuinely shared the mistake; there is no indication it made a misrepresentation in the legal sense.\n- Risk is irrelevant where the contract never came into existence."
 },
 {
  "t": "mistake-duress-ui-illegality",
  "q": "A man calls at Della's house in response to her advert for a used car. He says he is Ben Carter, a well-known local businessman, and pays with a cheque, which later bounces. Della hands over the car and the documents. The next day he sells the car to Wes, a dealer who buys in good faith for the market price. Two days later Della discovers the fraud and tells the police.\n\nWhich of the following best describes who owns the car?",
  "o": [
   "Della, because the contract was void for mistake as to identity.",
   "Della, because informing the police rescinded the contract and this takes effect retrospectively against Wes.",
   "Wes, because the contract with the rogue was voidable and he bought in good faith before Della rescinded.",
   "Della, because a person who pays with a worthless cheque never obtains any title to goods.",
   "Wes, but only if he can show that he checked the rogue's identity documents."
  ],
  "a": 2,
  "e": "In a **face-to-face** dealing, the seller is presumed to intend to contract with **the person in front of her**, so the contract is **voidable** for fraud, not void. A voidable title can pass to an innocent buyer who takes **in good faith and for value** **before** the contract is **rescinded**. Della's later report to the police can rescind the contract, but it comes too late to affect Wes."
 },
 {
  "t": "discharge-frustration",
  "q": "Amberley Events hired a marquee from Zenith Hire for £10,000 for a festival. Amberley paid a deposit of £3,000 on signing, and the balance was due on the day of the festival. Before the festival, a new government order banned all outdoor gatherings in the area for the period. Zenith had spent £1,000 preparing the marquee. The contract made no provision for this situation.\n\nWhich of the following is the most likely outcome?",
  "o": [
   "It is frustrated; Amberley recovers the £3,000, but Zenith may keep up to £1,000 for expenses.",
   "The contract is frustrated; Zenith keeps the £3,000 deposit because the loss lies where it falls.",
   "The contract is frustrated; Amberley must pay the full £10,000 because the balance had already become payable.",
   "The contract is not frustrated because Amberley could hold the festival at a later date.",
   "The contract is not frustrated; Amberley is in breach and liable for the full price less Zenith's savings."
  ],
  "a": 0,
  "e": "**Frustrated; deposit recoverable less any expenses allowed.**\n- A supervening **illegality** making performance unlawful, without fault of either party, **frustrates** the contract.\n- Under **s.1(2) Law Reform (Frustrated Contracts) Act 1943**:\n  - money **paid before** frustration is **recoverable** (the £3,000);\n  - money **payable** before frustration ceases to be payable (the balance was not yet due anyway);\n  - the court **may** allow the payee to keep a just sum for **expenses**, up to the amount paid or payable before frustration. Zenith's £1,000 is within the £3,000.\n\nWhy the others are wrong:\n- 'Loss lies where it falls' was the old common law rule, replaced by the 1943 Act.\n- The balance was not payable before the frustrating event.\n- The contract was for a specific festival period; a later date would be a different contract.\n- Neither party is in breach."
 },
 {
  "t": "discharge-frustration",
  "q": "In January, Carrick Ltd contracted to supply bespoke steel beams to Dunmore Construction for delivery on 1 September. In April, Carrick wrote to Dunmore stating clearly that it would not be supplying the beams because it had taken on more profitable work. Dunmore wants to know its options.\n\nWhat is the best advice to Dunmore?",
  "o": [
   "It must affirm the contract because it cannot terminate a contract before performance is due.",
   "It must wait until 1 September before it can bring any claim, because there is no breach until performance is due.",
   "It may terminate the contract, but can only recover damages if it waits until 1 September.",
   "It may accept the repudiation, terminate the contract and sue for damages immediately, or affirm the contract and wait until 1 September.",
   "It may sue immediately for specific performance, because anticipatory breach entitles the innocent party to that remedy."
  ],
  "a": 3,
  "e": "**Terminate and sue now, or affirm and wait.**\n- Carrick's clear statement that it will not perform is an **anticipatory breach** (renunciation), which is repudiatory.\n- The innocent party may **elect**:\n  - **accept** the repudiation, **terminate** and **sue immediately** (**Hochster v De la Tour**). Once it accepts, its duty to **mitigate** applies; or\n  - **affirm** the contract and wait for the performance date, with the risk that an intervening event discharges the contract (**Avery v Bowden**).\n\nWhy the others are wrong:\n- There is no need to wait for the performance date.\n- Damages are available on termination.\n- Anticipatory breach does allow termination before the due date.\n- Specific performance is discretionary and unlikely where damages are adequate."
 },
 {
  "t": "discharge-frustration",
  "q": "Harrow Builders contracts to build an office block for a fixed price of £2 million within 12 months. A sudden national shortage of steel means the job takes 20 months and costs Harrow an extra £400,000. Harrow claims the contract was frustrated and seeks a reasonable sum for all its work instead of the contract price.\n\nWhich of the following best describes the position?",
  "o": [
   "The contract is frustrated, because the delay and cost increase were not Harrow's fault.",
   "The contract is not frustrated, because performance became more costly and slower but not radically different.",
   "The contract is frustrated only for the period of the shortage, after which it revives.",
   "The contract is frustrated, and Harrow can recover a just sum under the Law Reform (Frustrated Contracts) Act 1943.",
   "The contract is not frustrated, because frustration never applies to building contracts."
  ],
  "a": 1,
  "e": "Frustration requires an event that makes performance **impossible, illegal or radically different** from what was undertaken. A contract that becomes **more expensive or takes longer** is not frustrated: the work is the same, only harder. So Harrow remains bound to the fixed price and the 1943 Act does not apply. Building contracts are not excluded from frustration as a category."
 },
 {
  "t": "damages",
  "q": "Melrose Bakery's oven broke. Melrose contracted with Fastfix Couriers to take the broken part to the manufacturer for repair within 24 hours. Fastfix was not told that Melrose had no spare part and that its bakery would close until delivery. Fastfix delivered three days late. Melrose lost its normal profits for those days and also lost a one-off, highly lucrative contract to supply a royal garden party, which it had not mentioned.\n\nWhich losses can Melrose recover from Fastfix?",
  "o": [
   "The normal profits only, because loss of an exceptionally lucrative contract is never recoverable.",
   "Both the normal profits and the garden party profits, because both were caused by the late delivery.",
   "The garden party profits only, because normal trading losses for a few days are too speculative to recover.",
   "Both, because Fastfix is liable for all losses that were foreseeable at the time of breach.",
   "Neither, unless Fastfix knew when contracting that the bakery would be idle without the part."
  ],
  "a": 4,
  "e": "**Probably neither, unless Fastfix knew the bakery would stop.**\n- Under **Hadley v Baxendale**, loss is recoverable if it arises **naturally** from the breach (limb 1) or was in the **contemplation of both parties** at the time of contracting because of **special circumstances** made known (limb 2).\n- In Hadley itself, a carrier delivering a mill shaft was **not** liable for the mill's lost profits because it was not told the mill was idle without the part. A courier would not ordinarily assume a business has no spare.\n- The garden party contract was an unusual, exceptionally lucrative loss not communicated (**Victoria Laundry**).\n\nWhy the others are wrong:\n- Causation alone is not enough; the loss must not be too remote.\n- Remoteness is judged at the time of **contracting**, not breach.\n- Exceptional profits **can** be recovered if the defendant knew of them when contracting."
 },
 {
  "t": "damages",
  "q": "Sterling Car Park Ltd allows motorists two hours' free parking at its retail park car park, after which they must pay a charge of £90. Clear signs state this at the entrance and throughout. Sterling's actual loss from an overstay is minimal, but the charge helps it manage the car park for the retailers and their customers. Kofi overstayed by an hour and refuses to pay, saying the charge is a penalty.\n\nWhich of the following best describes the charge?",
  "o": [
   "It is unenforceable because a clause designed to deter breach is always a penalty.",
   "It is unenforceable, because £90 is not a genuine pre-estimate of the loss Sterling suffers from an overstay.",
   "It is likely enforceable, because it protects a legitimate interest and is not out of all proportion to it.",
   "It is likely enforceable because the penalty rule does not apply to consumer contracts.",
   "It is unenforceable because Sterling suffers no loss from an overstay and can recover only nominal damages."
  ],
  "a": 2,
  "e": "**Likely enforceable.**\n- Under **Cavendish v Makdessi; ParkingEye v Beavis**, a clause is a **penalty** only if it imposes a **detriment** on the contract-breaker **out of all proportion** to the innocent party's **legitimate interest** in performance of the primary obligation.\n- The legitimate interest can go beyond compensating for loss. In **ParkingEye**, an £85 overstay charge was valid because it served the interest in managing the car park efficiently. These facts are almost identical.\n\nWhy the others are wrong:\n- The old 'genuine pre-estimate of loss' test is no longer the test.\n- A deterrent element does not by itself make a clause a penalty.\n- The penalty rule does apply to consumer contracts, alongside the CRA fairness test (in ParkingEye it was not unfair either).\n- Lack of actual loss is not decisive."
 },
 {
  "t": "damages",
  "q": "Kendal Fabrics agrees to buy cloth from Loom Ltd in monthly instalments on 30 days' credit. After a dispute, Loom says it will continue delivering only if Kendal pays cash on each order, at the same price. The market price has risen by 20%. Kendal refuses Loom's offer and buys the cloth elsewhere at the higher market price, then sues Loom for the difference.\n\nWhich of the following best describes Kendal's damages?",
  "o": [
   "They are reduced, because Kendal unreasonably refused Loom's offer and so failed to mitigate its loss.",
   "Kendal recovers the full difference, because a party in breach cannot dictate new terms.",
   "Kendal recovers nothing, because it chose to buy elsewhere.",
   "Kendal recovers the full difference, because the burden is on Kendal to show it acted reasonably and it has done so.",
   "Kendal recovers only nominal damages, because Loom's breach caused no loss."
  ],
  "a": 0,
  "e": "A claimant cannot recover loss it could have avoided by **reasonable steps**, and refusing a **reasonable offer** from the party in breach (here, supply for cash at the contract price) can be a **failure to mitigate**. Kendal's damages are limited to what it would have lost by accepting cash terms. The **burden** is on the **defendant** to prove failure to mitigate, not on the claimant."
 },
 {
  "t": "equitable-remedies-guarantees",
  "q": "Rosalind agreed in writing to buy a Grade II listed cottage from Talbot for £450,000. Before completion, Talbot received a higher offer and told Rosalind he would not complete, offering to pay her any losses. Rosalind has chosen this cottage because it backs onto her parents' home and she has not delayed in bringing her claim.\n\nWhich remedy is Rosalind most likely to obtain?",
  "o": [
   "An injunction preventing Talbot from selling to anyone else, but not an order to sell to her.",
   "Damages only, because specific performance is never ordered where the defendant offers to pay compensation.",
   "Damages only, because Rosalind's preference for the cottage is a personal reason that equity ignores.",
   "Specific performance, because land is regarded as unique and damages would not be an adequate remedy.",
   "Specific performance, but only if Rosalind can show that Talbot acted fraudulently."
  ],
  "a": 3,
  "e": "**Specific performance.**\n- **Specific performance** is available where **damages are inadequate**. Each piece of **land** is treated as **unique**, so contracts for the sale of land are routinely specifically enforced.\n- No bar applies: Rosalind has not delayed, there is no hardship or unclean hands, and no personal service or constant supervision is involved.\n\nWhy the others are wrong:\n- A defendant cannot avoid specific performance by offering damages.\n- The uniqueness of land is the established basis for the remedy, regardless of the buyer's reasons.\n- An injunction alone would not give Rosalind the cottage; specific performance is the appropriate order.\n- Fraud is not needed; the remedy is discretionary but available for ordinary breach."
 },
 {
  "t": "equitable-remedies-guarantees",
  "q": "Sasha's company owes Fernhill Supplies £25,000. In a phone call, Sasha tells Fernhill's manager: 'If my company doesn't pay you, I will.' Nothing is put in writing. The company goes into liquidation without paying. Fernhill relied on Sasha's promise in continuing to supply.\n\nWhich of the following best describes Fernhill's position against Sasha?",
  "o": [
   "It can enforce the promise as an indemnity, which needs no writing.",
   "It cannot enforce the promise, because it is a guarantee that was not evidenced in signed writing.",
   "It can enforce the promise because it relied on it, so Sasha is estopped from denying liability.",
   "It can enforce the promise, because a director is always personally liable for the company's trade debts.",
   "It cannot enforce the promise, because guarantees can only be made by deed."
  ],
  "a": 1,
  "e": "A promise to pay **if the debtor does not** is a **guarantee**: secondary liability. Under **Statute of Frauds 1677 s.4** it is unenforceable unless evidenced in **writing signed** by the guarantor. Reliance on the oral promise itself does not create an **estoppel** that gets round the statute. An indemnity would be a primary promise to make good a loss whatever happens, which is not what Sasha said."
 },
 {
  "t": "equitable-remedies-guarantees",
  "q": "Rowan, a well-known chef, agrees with the Quayside restaurant to work as its head chef for two years and not to work as a chef for any other restaurant in the city during that time. After six months he leaves to become head chef at a rival restaurant in the city. Quayside wants to stop him.\n\nWhich remedy is Quayside most likely to obtain?",
  "o": [
   "Specific performance requiring Rowan to return to work at Quayside.",
   "An account of all profits made by the rival restaurant while Rowan works there.",
   "An injunction requiring Rowan to work at Quayside for the rest of the two years.",
   "No remedy, because injunctions are never granted in contracts of personal service.",
   "An injunction preventing him working as a chef at other restaurants in the city."
  ],
  "a": 4,
  "e": "The court will **not** order **specific performance** of a contract of **personal service**. But it will usually grant a **prohibitory injunction** to enforce an **express negative promise**, provided it does not in practice **compel** the defendant to work for the claimant. Rowan can still earn a living outside the city or in other work, so an injunction limited to the restraint is likely. An account of profits is exceptional and would not reach a third party's profits."
 }
];

;
window.SQE_QUICK = window.SQE_QUICK || {};
window.SQE_QUICK["tort"] = [
  {t:"negligence", q:"A driver negligently injures a pedestrian. Must the court apply the three-stage Caparo test to decide whether a duty of care is owed?", o:["No: it is an established duty category","Yes: Caparo applies to every negligence claim","Yes, but only the proximity stage","No: drivers owe duties only to other drivers"], e:"In an **established category** a duty exists without more; **Caparo** is used only in **novel** situations (Robinson v CC West Yorkshire)."},
  {t:"negligence", q:"What standard of care applies to a learner driver?", o:["A reasonably competent qualified driver","A reasonable learner driver","A reasonable driver of similar age","The driver's own personal best"], e:"**Nettleship v Weston**: no allowance is made for inexperience; the standard is objective."},
  {t:"negligence", q:"A surgeon does not mention a small risk of serious complication that a reasonable patient would want to know about, though many surgeons would not mention it. How is breach judged?", o:["By whether the risk was material to a reasonable patient","By whether a responsible body of doctors would not disclose it","By whether the risk was above 10%","By what the surgeon honestly thought best"], e:"Doctors must disclose **material risks**: those a **reasonable patient** would think significant. Bolam does not apply to risk disclosure (Montgomery)."},
  {t:"negligence", q:"A cricket ball is hit out of a ground, which had happened about six times in 30 years, and injures a passer-by. Was the club in breach of duty?", o:["No: the risk was so small it could reasonably be ignored","Yes: the harm was foreseeable","Yes: sports clubs owe a strict duty","No: passers-by are owed no duty"], e:"Breach weighs the **likelihood of harm**; a very **small risk** may reasonably be ignored (Bolton v Stone)."},
  {t:"negligence", q:"Which statute makes a relevant criminal conviction admissible as evidence of breach in a civil claim?", o:["Civil Evidence Act 1968 s.11","Compensation Act 2006 s.1","SARAH Act 2015","Law Reform Act 1945 s.1"], e:"**Civil Evidence Act 1968 s.11** allows a conviction to be used as evidence in civil proceedings."},

  {t:"causation-remoteness", q:"A doctor negligently fails to examine a patient, who dies of arsenic poisoning that would have killed him even with proper treatment. Is the doctor liable for the death?", o:["No: but-for causation fails","Yes: failing to examine was a breach","Yes: the hospital owed a duty of care","Only for a proportion of the loss"], e:"**But-for test**: the death would have happened anyway, so the breach did not cause it (Barnett)."},
  {t:"causation-remoteness", q:"Under the Compensation Act 2006 s.3, how is liability for mesothelioma allocated between defendants?", o:["Jointly and severally","Apportioned by length of exposure","Shared equally per defendant","Borne only by the last employer"], e:"**s.3** makes each defendant who materially increased the risk liable in full (**joint and several**)."},
  {t:"causation-remoteness", q:"The defendant negligently injures the claimant's back. Before trial, the claimant develops an unrelated natural spinal disease that would have disabled him anyway. How does this affect the defendant's damages?", o:["They are limited to the period before the disease","No effect: the defendant stays liable for the whole loss","The defendant's liability ends at the accident date","They are increased for the extra suffering"], e:"A **supervening natural illness** is taken into account (Jobling); a later **tort** does not reduce the first tortfeasor's liability (Baker v Willoughby)."},
  {t:"causation-remoteness", q:"Oil negligently spilled in a harbour is ignited by a freak chain of events and burns a wharf. Fire damage was not reasonably foreseeable, though fouling was. Is the defendant liable for the fire damage?", o:["No: that type of damage was not reasonably foreseeable","Yes: the fire was a direct consequence","Yes: some damage to the wharf was foreseeable","Yes: the defendant takes the victim as found"], e:"**Remoteness**: liability only for damage of a **reasonably foreseeable type**, not all direct consequences (The Wagon Mound (No 1))."},
  {t:"causation-remoteness", q:"The defendant negligently causes a minor burn to the claimant's lip. Because of a pre-malignant condition, the burn triggers cancer and the claimant dies. Is the defendant liable for the death?", o:["Yes: the defendant takes the victim as he finds him","No: cancer was not a foreseeable type of harm","No: the pre-existing condition broke the chain","Only for the burn itself"], e:"**Eggshell skull rule**: if the type of injury (a burn) was foreseeable, the defendant is liable for its **full extent** (Smith v Leech Brain)."},

  {t:"economic-loss", q:"In Spartan Steel v Martin, which loss was NOT recoverable?", o:["Profit on melts not processed","Value of the damaged melt","Profit on the damaged melt","Physical damage to the furnace"], e:"**Spartan Steel**: loss flowing from physical damage was recoverable, but lost profit on future melts was **pure economic loss**."},
  {t:"economic-loss", q:"A council negligently approves defective foundations. Cracks appear and the owner sells at a loss; no one is hurt and no other property is damaged. Can the owner recover the loss in negligence?", o:["No: the loss is pure economic loss","Yes: the building has been physically damaged","Yes: councils owe a duty to all homeowners","Only the cost of repair, not the loss on sale"], e:"Damage to the **defective thing itself** is **pure economic loss**, not recoverable in negligence (Murphy v Brentwood)."},
  {t:"economic-loss", q:"A solicitor negligently delays drafting a will and the client dies before signing it, so the intended beneficiary gets nothing. Can the beneficiary sue the solicitor?", o:["Yes: the solicitor owes a duty to the intended beneficiary","No: only the client could sue, in contract","No: pure economic loss is never recoverable","No: the beneficiary relied on nothing the solicitor said"], e:"An exception to the economic loss rule: a solicitor owes a **duty to an intended beneficiary** of a will (White v Jones)."},
  {t:"economic-loss", q:"A mortgage valuer knows the buyer of a modest house will rely on the valuation, but includes a disclaimer of liability. The valuation is negligent. Will the disclaimer protect the valuer?", o:["No: the disclaimer is unreasonable, so unenforceable","Yes: a disclaimer always negates a Hedley Byrne duty","Yes: the valuer had no contract with the buyer","Yes: the buyer could have got their own survey"], e:"A valuer's disclaimer to a buyer of a **modest house** who relies on it fails the **reasonableness** test (Smith v Eric S Bush, under UCTA)."},

  {t:"psychiatric-harm", q:"The claimant is in a car crash caused by the defendant's negligence. The claimant is physically unhurt but the shock triggers a recognised psychiatric illness. Can the claimant recover?", o:["Yes: physical injury was foreseeable, so the claimant is a primary victim","No: psychiatric injury itself was not foreseeable","No: the claimant must satisfy the Alcock control mechanisms","Only if the claimant saw a loved one injured"], e:"A **primary victim** in the zone of physical danger recovers if **physical injury was foreseeable**; psychiatric harm need not be (Page v Smith)."},
  {t:"psychiatric-harm", q:"For which relationship is a close tie of love and affection presumed under Alcock?", o:["Parent and child","Brother and sister","Close friends","Grandparent and grandchild"], e:"**Alcock** presumes the tie for parents/children, spouses and fiancé(e)s. Siblings and others must prove it."},
  {t:"psychiatric-harm", q:"What did Paul v Royal Wolverhampton NHS Trust (2024) require a secondary victim to witness?", o:["An accident","The negligent act itself","The victim's death","A medical diagnosis"], e:"**Paul** (UKSC 2024): there must be an **accident**, an external event. A medical crisis from negligent treatment is not enough."},
  {t:"psychiatric-harm", q:"How are rescuers treated for psychiatric harm claims?", o:["No special status","Automatically primary victims","Automatically secondary victims","Barred from claiming"], e:"**White v CC South Yorkshire**: rescuers recover only as primary victims or by meeting the secondary-victim rules."},

  {t:"employers-liability", q:"An employer delegates safety to a competent manager, who sets up an unsafe system of work, and an employee is injured. Can the employer escape liability by showing it delegated properly?", o:["No: the duty is personal and non-delegable","Yes: it chose a competent manager","Yes: only the manager is liable","Yes, if the employee was also careless"], e:"The employer's duty (competent staff, adequate plant, **safe place, safe system**) is **non-delegable** (Wilsons & Clyde Coal v English)."},
  {t:"employers-liability", q:"Which Act deems the employer negligent where defective equipment was due to a third party's fault?", o:["Employers' Liability (Defective Equipment) Act 1969","Employers' Liability (Compulsory Insurance) Act 1969","Consumer Protection Act 1987","Health and Safety at Work Act 1974"], e:"The **Employers' Liability (Defective Equipment) Act 1969** deems the employer negligent; it can seek contribution from the manufacturer."},
  {t:"employers-liability", q:"Which provision removed civil liability for breach of most health and safety regulations?", o:["ERRA 2013 s.69","Compensation Act 2006 s.1","SARAH Act 2015 s.2","Civil Evidence Act 1968 s.11"], e:"**ERRA 2013 s.69** (breaches from 1 Oct 2013): the employee must now prove **negligence**."},
  {t:"employers-liability", q:"An employee known for years for dangerous horseplay, never disciplined, trips a colleague and injures him. Is the employer liable for breach of its own duty?", o:["Yes: it failed to provide competent fellow employees","No: horseplay is not work","No: employers are never liable for deliberate acts","Only if the employer encouraged the horseplay"], e:"Breach of the duty to provide **competent fellow employees**: the employer knew of the risk and did nothing (Hudson v Ridge Manufacturing)."},

  {t:"vicarious-liability", q:"A prisoner working in a prison kitchen negligently injures a catering manager. Can the prison service be vicariously liable though the prisoner is not an employee?", o:["Yes: the relationship is akin to employment","No: vicarious liability needs a contract of employment","No: prisoners work involuntarily","Only if the prisoner was paid the minimum wage"], e:"A relationship **akin to employment** (work integral to the defendant's business and for its benefit) can found vicarious liability (Cox v MoJ)."},
  {t:"vicarious-liability", q:"A bank sends job applicants for medicals to a self-employed doctor with his own practice and other clients. He assaults some applicants. Is the bank vicariously liable?", o:["No: the doctor was in business on his own account","Yes: the relationship was akin to employment","Yes: the bank chose and directed him","Yes: the bank paid for each examination"], e:"No vicarious liability for a genuine **independent contractor** carrying on his own business (Various Claimants v Barclays Bank)."},
  {t:"vicarious-liability", q:"Why was the employer not liable in WM Morrison v Various Claimants (2020)?", o:["Employee pursued a personal vendetta","No employment relationship existed","Data leak caused no damage","Employee acted on instructions"], e:"**WM Morrison** (2020): leaking payroll data to pursue a **personal vendetta** was not closely connected to the job."},
  {t:"vicarious-liability", q:"A milkman, forbidden to give lifts, lets a boy ride along to help deliver milk, and injures him by negligent driving. Is the employer vicariously liable?", o:["Yes: it was an authorised task done in a prohibited way","No: lifts were expressly prohibited","No: the boy was a trespasser on the float","Only if the employer knew of the lifts"], e:"A prohibited **way of doing an authorised task** remains in the course of employment, especially where it furthers the employer's business (Rose v Plenty)."},

  {t:"defences", q:"Which provision stops volenti being used against a passenger in a vehicle requiring compulsory insurance?", o:["Road Traffic Act 1988 s.149","Law Reform Act 1945 s.1","Compensation Act 2006 s.1","OLA 1957 s.2(5)"], e:"**RTA 1988 s.149** bars volenti against passengers, even one who knew the driver was drunk."},
  {t:"defences", q:"Under Froom v Butcher, what reduction applies if a seatbelt would have prevented injury altogether?", o:["25%","15%","20%","50%"], e:"**Froom v Butcher**: 25% if injury prevented entirely, 15% if less severe, nil if no difference."},
  {t:"defences", q:"Which Act governs the partial defence of contributory negligence?", o:["Law Reform (Contributory Negligence) Act 1945","Law Reform (Miscellaneous Provisions) Act 1934","Civil Liability (Contribution) Act 1978","Compensation Act 2006"], e:"The **1945 Act s.1** reduces damages to the extent that is **just and equitable**."},
  {t:"defences", q:"A claimant injured while jointly committing a crime sues his co-offender in negligence. How does the court decide whether illegality bars the claim?", o:["Weighing the purpose of the prohibition, other policies and proportionality","Asking only whether the claimant must rely on the illegality","Applying a fixed rule that any crime bars the claim","Reducing damages by a fixed 50%"], e:"Illegality is **policy-based**: purpose of the prohibition, other relevant policies, and **proportionality** (Patel v Mirza)."},

  {t:"remedies", q:"What is the personal injury discount rate in England and Wales from 11 January 2025?", o:["+0.5%","-0.25%","-0.75%","+1.0%"], e:"The rate was set at **+0.5%** from 11 January 2025, used with the Ogden Tables."},
  {t:"remedies", q:"What is the current statutory bereavement award under the Fatal Accidents Act 1976?", o:["£15,120","£12,980","£11,800","£20,000"], e:"**FAA 1976 s.1A**: a fixed **£15,120** for spouses/civil partners, 2+ year cohabitants or parents of an unmarried minor."},
  {t:"remedies", q:"What is the basic limitation period for a personal injury claim?", o:["3 years","6 years","2 years","1 year"], e:"**LA 1980 ss.11 and 14**: 3 years from the cause of action or date of knowledge; s.33 allows disapplication."},
  {t:"remedies", q:"What is the longstop for latent damage claims in negligence (not personal injury)?", o:["15 years","10 years","12 years","6 years"], e:"**LA 1980 s.14B**: a **15-year longstop** from the negligent act."},

  {t:"occupiers-liability", q:"A brewery owns a pub run by a manager living upstairs; the brewery keeps the right to do repairs. A visitor falls on the private staircase. Who can be an occupier?", o:["Both the brewery and the manager","Only the brewery, as owner","Only the manager, as resident","Neither, as the staircase is private"], e:"An occupier is anyone with **sufficient control**; there can be **more than one** (Wheat v Lacon)."},
  {t:"occupiers-liability", q:"Two chimney sweeps die from carbon monoxide while sealing a flue, despite the occupier's warning. Is the occupier liable?", o:["No: skilled visitors must guard against risks of their calling","Yes: occupiers owe visitors a strict duty","Yes: a warning never discharges the duty","Only if the sweeps were unpaid"], e:"**OLA 1957 s.2(3)(b)**: a person exercising a calling is expected to **guard against special risks** incident to it (Roles v Nathan)."},
  {t:"occupiers-liability", q:"Which type of loss is NOT recoverable under the Occupiers' Liability Act 1984?", o:["Property damage","Personal injury","Death","Psychiatric injury"], e:"**OLA 1984 s.1(8)**: the duty covers **injury only**, not property damage."},
  {t:"occupiers-liability", q:"An adult dives into a shallow lake in a council park, despite 'no swimming' signs, and is paralysed. Is the council liable?", o:["No: no duty to protect against obvious risks freely run","Yes: the council knew people swam there","Yes: signs are never enough","Only if the council failed to fence the lake"], e:"No duty to protect **adults** from **obvious risks** they **freely choose** to run (Tomlinson v Congleton BC)."},

  {t:"product-liability", q:"What is the minimum value for a property damage claim under the CPA 1987?", o:["Over £275","Over £500","Over £1,000","Over £100"], e:"**CPA 1987 s.5**: property damage claims must exceed **£275**."},
  {t:"product-liability", q:"Under CPA 1987 s.3, when is a product defective?", o:["Safety below what persons generally expect","Producer failed to take reasonable care","Not of satisfactory quality","Not fit for its purpose"], e:"**s.3**: safety is not such as **persons generally are entitled to expect**. Fault is not required."},
  {t:"product-liability", q:"What is the longstop for claims under the Consumer Protection Act 1987?", o:["10 years from circulation","15 years from the defect","6 years from damage","3 years from circulation"], e:"3 years from damage or knowledge, subject to an absolute **10-year longstop** from when the product was put into circulation."},
  {t:"product-liability", q:"When does a retailer become liable as a supplier under the CPA 1987?", o:["Fails to identify producer when asked","Sells the product in its shop","Labels the product with prices","Fails to inspect the product"], e:"**s.2(3)**: a supplier is liable only if it fails to identify the producer or importer within a reasonable time after request."},

  {t:"nuisance-rylands", q:"A homeowner's adult son, who lives at home but has no interest in the property, suffers noise and dust from a neighbour's works. Can the son sue in private nuisance?", o:["No: he has no proprietary interest in the land","Yes: he lives at the property","Yes: anyone affected can sue","Only with his parents' consent"], e:"Only those with a **proprietary interest** or exclusive possession can sue in private nuisance (Hunter v Canary Wharf)."},
  {t:"nuisance-rylands", q:"How many years of actionable nuisance are needed for prescription?", o:["20 years","12 years","10 years","15 years"], e:"**Prescription** requires 20 years of actionable nuisance. Coming to the nuisance is not a defence."},
  {t:"nuisance-rylands", q:"A council's ordinary water supply pipe bursts, without negligence, and the escaping water damages neighbouring land. Is the council strictly liable under Rylands v Fletcher?", o:["No: an ordinary water pipe is not a non-natural use","Yes: water is likely to do mischief if it escapes","Yes: any escape of something brought onto land suffices","No: Rylands applies only to fire"], e:"**Non-natural use** means **extraordinary and unusual**; ordinary water pipes do not qualify (Transco v Stockport MBC)."},
  {t:"nuisance-rylands", q:"Visitors on a gallery's viewing platform constantly look into and photograph the inside of neighbouring glass-walled flats. Can the flat owners sue in private nuisance?", o:["Yes: intrusive overlooking can be an actionable nuisance","No: overlooking can never be a nuisance","No: glass walls make the owners hypersensitive","Only if the platform lacked planning permission"], e:"Intrusive **overlooking** that substantially interferes with **use and enjoyment** can be a nuisance (Fearn v Tate Gallery, 2023)."}
];

;
