window.SQE_TERMS["tort"] = [
  {t:"negligence", w:"Donoghue v Stevenson", d:"Established the neighbour principle: take care not to injure those foreseeably affected."},
  {t:"negligence", w:"Caparo v Dickman", d:"Novel duty: foreseeability, proximity, and fair, just and reasonable."},
  {t:"negligence", w:"Robinson v CC West Yorkshire", d:"Apply established categories first; Caparo only for novel situations."},
  {t:"negligence", w:"Bolam test", d:"Professional not negligent if acting as a responsible body of peers would."},
  {t:"negligence", w:"Bolitho", d:"Professional opinion must withstand logical analysis."},
  {t:"negligence", w:"Montgomery v Lanarkshire", d:"Doctors must disclose material risks a reasonable patient would want to know."},
  {t:"negligence", w:"Nettleship v Weston", d:"Learner drivers are judged by the standard of a reasonable competent driver."},
  {t:"negligence", w:"Bolton v Stone", d:"Low likelihood of harm can mean no breach."},
  {t:"causation-remoteness", w:"But for test", d:"Would the harm have occurred but for the defendant's breach?"},
  {t:"causation-remoteness", w:"Barnett v Chelsea & Kensington HMC", d:"No liability where the patient would have died anyway."},
  {t:"causation-remoteness", w:"Fairchild", d:"Material increase in risk suffices for mesothelioma causation."},
  {t:"causation-remoteness", w:"Novus actus interveniens", d:"A new, independent act that breaks the chain of causation."},
  {t:"causation-remoteness", w:"The Wagon Mound (No 1)", d:"Only reasonably foreseeable types of damage are recoverable."},
  {t:"causation-remoteness", w:"Eggshell skull rule", d:"Take the victim as found, even if harm is worse than expected."},
  {t:"causation-remoteness", w:"Hughes v Lord Advocate", d:"Precise way the harm occurs need not be foreseeable."},
  {t:"economic-loss", w:"Pure economic loss", d:"Financial loss not flowing from physical damage; generally irrecoverable in negligence."},
  {t:"economic-loss", w:"Spartan Steel v Martin", d:"Consequential economic loss recoverable, but pure economic loss is not."},
  {t:"economic-loss", w:"Hedley Byrne v Heller", d:"Duty for negligent misstatements where there is assumption of responsibility and reliance."},
  {t:"economic-loss", w:"Murphy v Brentwood DC", d:"Defect in the thing itself is pure economic loss."},
  {t:"economic-loss", w:"White v Jones", d:"Solicitor owes a duty to an intended beneficiary of a negligently drafted will."},
  {t:"economic-loss", w:"Smith v Eric S Bush", d:"Surveyor's disclaimer to house buyer failed the UCTA reasonableness test."},
  {t:"psychiatric-harm", w:"Recognised psychiatric illness", d:"Required for any claim; ordinary grief or distress is not enough."},
  {t:"psychiatric-harm", w:"Primary victim", d:"Claimant in the zone of physical danger or reasonably believing they were."},
  {t:"psychiatric-harm", w:"Page v Smith", d:"Primary victim recovers if physical injury foreseeable, even if psychiatric harm not."},
  {t:"psychiatric-harm", w:"Alcock v CC South Yorkshire", d:"Secondary victims need close love tie, proximity, and perception by own senses."},
  {t:"psychiatric-harm", w:"Paul v Royal Wolverhampton", d:"Secondary victim must witness an accident, an external event causing or risking injury."},
  {t:"psychiatric-harm", w:"Hatton v Sutherland", d:"Guidance on when work stress causing psychiatric harm is foreseeable."},
  {t:"employers-liability", w:"Wilsons & Clyde Coal v English", d:"Employer owes personal, non-delegable duty of reasonable care to employees."},
  {t:"employers-liability", w:"Safe system of work", d:"Employer duty covering organisation, training, supervision and work methods."},
  {t:"employers-liability", w:"Defective Equipment Act 1969", d:"Employer liable for equipment defects caused by a third party's fault."},
  {t:"employers-liability", w:"ERRA 2013 s.69", d:"Breach of health and safety regulations no longer gives a civil claim alone."},
  {t:"employers-liability", w:"Competent fellow employees", d:"Employer must provide competent staff to work alongside employees."},
  {t:"vicarious-liability", w:"Vicarious liability", d:"Strict liability of one person for a tort committed by another."},
  {t:"vicarious-liability", w:"Cox v Ministry of Justice", d:"Relationship akin to employment can give rise to vicarious liability."},
  {t:"vicarious-liability", w:"Various Claimants v Barclays", d:"No vicarious liability for genuine independent contractors."},
  {t:"vicarious-liability", w:"Lister v Hesley Hall", d:"Close connection test: tort closely connected with the employment."},
  {t:"vicarious-liability", w:"WM Morrison v Various Claimants", d:"No liability for an employee pursuing a personal vendetta."},
  {t:"vicarious-liability", w:"Frolic of his own", d:"Employee acting outside employment, so the employer is not liable."},
  {t:"defences", w:"Volenti non fit injuria", d:"Complete defence where claimant freely consented with full knowledge of the risk."},
  {t:"defences", w:"RTA 1988 s.149", d:"Volenti cannot be used against a car passenger."},
  {t:"defences", w:"Contributory negligence", d:"Partial defence reducing damages where claimant failed to take reasonable care."},
  {t:"defences", w:"Froom v Butcher", d:"Failing to wear a seatbelt reduces damages by up to 25%."},
  {t:"defences", w:"Ex turpi causa", d:"Illegality defence barring claims arising from the claimant's own wrongdoing."},
  {t:"defences", w:"Henderson v Dorset Healthcare", d:"No damages for losses flowing from the claimant's own criminal sentence."},
  {t:"remedies", w:"PSLA", d:"Pain, suffering and loss of amenity: general damages for the injury itself."},
  {t:"remedies", w:"Multiplier and multiplicand", d:"Method of calculating future losses: annual loss times adjusted years."},
  {t:"remedies", w:"Personal injury discount rate", d:"Rate adjusting lump sums for future investment return; +0.5% from January 2025."},
  {t:"remedies", w:"Fatal Accidents Act 1976", d:"Lets dependants claim loss of dependency after a wrongful death."},
  {t:"remedies", w:"Bereavement damages", d:"Fixed sum of £15,120 for eligible relatives after a wrongful death."},
  {t:"remedies", w:"Compensation Recovery Unit", d:"Recovers state benefits paid to the claimant from the defendant."},
  {t:"occupiers-liability", w:"Wheat v Lacon", d:"Occupier is anyone with sufficient control; there can be more than one."},
  {t:"occupiers-liability", w:"Common duty of care (s.2(2))", d:"Occupier must take reasonable care to keep visitors reasonably safe."},
  {t:"occupiers-liability", w:"Allurement", d:"Something attractive to children, requiring extra care under s.2(3)(a)."},
  {t:"occupiers-liability", w:"Skilled visitors (s.2(3)(b))", d:"Expected to guard against risks ordinarily incident to their calling."},
  {t:"occupiers-liability", w:"OLA 1984 s.1(3)", d:"Duty to trespassers if occupier aware of danger, of their presence, and protection expected."},
  {t:"occupiers-liability", w:"Warnings (s.2(4)(a))", d:"Warning discharges duty only if enough to keep the visitor reasonably safe."},
  {t:"product-liability", w:"CPA 1987 Part 1", d:"Strict liability on producers for damage caused by defective products."},
  {t:"product-liability", w:"Producer", d:"Manufacturer, own-brander or importer into the UK."},
  {t:"product-liability", w:"Defect (s.3)", d:"Safety is not such as persons generally are entitled to expect."},
  {t:"product-liability", w:"Wilkes v DePuy", d:"Defect judged on the overall safety level the public is entitled to expect."},
  {t:"product-liability", w:"£275 threshold", d:"Property damage claims under the CPA must exceed £275."},
  {t:"product-liability", w:"Development risks defence", d:"Scientific knowledge at the time did not allow the defect to be discovered."},
  {t:"nuisance-rylands", w:"Private nuisance", d:"Unlawful interference with a person's use or enjoyment of land."},
  {t:"nuisance-rylands", w:"Hunter v Canary Wharf", d:"Only those with a proprietary interest in the land can sue."},
  {t:"nuisance-rylands", w:"Sturges v Bridgman", d:"Character of the locality is relevant to whether interference is unreasonable."},
  {t:"nuisance-rylands", w:"Coventry v Lawrence", d:"Coming to the nuisance is no defence; damages may replace an injunction."},
  {t:"nuisance-rylands", w:"Christie v Davey", d:"Malicious conduct can make an interference unreasonable."},
  {t:"nuisance-rylands", w:"Rylands v Fletcher", d:"Strict liability for escape of something dangerous from non-natural land use."},
  {t:"nuisance-rylands", w:"Transco v Stockport", d:"Non-natural use means extraordinary and unusual use of land."}
];

