window.SQE_SHOPIMG={"pandan": "img/shop-drawn-web/pandan.webp", "latte": "img/shop-drawn-web/latte.webp", "crocs": "img/shop-drawn-web/crocs.webp", "charms": "img/shop-drawn-web/charms.webp", "socks": "img/shop-drawn-web/socks.webp", "clawsocks": "img/shop-drawn-web/clawsocks.webp", "pens": "img/shop-drawn-web/pens.webp", "stickers": "img/shop-drawn-web/stickers.webp", "colouring": "img/shop-drawn-web/colouring.webp", "calendar": "img/shop-drawn-web/calendar.webp", "toppers": "img/shop-drawn-web/toppers.webp", "plaque": "img/shop-drawn-web/plaque.webp", "soap": "img/shop-drawn-web/soap.webp", "lamp": "img/shop-drawn-web/lamp.webp", "sweets": "img/shop-drawn-web/sweets.webp", "tote": "img/shop-drawn-web/tote.webp", "skincare": "img/shop-drawn-web/skincare.webp", "cup": "img/shop-drawn-web/cup.webp", "player": "img/shop-drawn-web/player.webp", "rec_ss": "img/shop/rec_ss.webp", "rec_mj": "img/shop/rec_mj.webp", "corn": "img/shop-drawn-web/corn.webp", "coop": "img/shop/coop.webp", "bonnie": "img/bonnie.webp", "swing": "img/shop/swing.webp", "cookies": "img/shop/cookies.webp", "nestbox": "img/shop/nestbox.webp", "goldcorn": "img/shop/goldcorn.webp", "palace": "img/shop/palace.webp", "incubator": "img/kit/incubator.webp", "medicine": "img/kit/medicine.webp", "parents": "img/shop/parents.webp", "monnie": "img/shop-drawn-web/monnie.webp"};
